declare w public.wallet_accounts%rowtype; r public.credit_reservations%rowtype; next_balance numeric(20,6);
begin
 if p_amount <= 0 or p_ttl_seconds < 1 or p_ttl_seconds > 86400 then raise exception 'invalid reservation amount or ttl'; end if;
 select * into r from public.credit_reservations where idempotency_key=p_idempotency_key for update;
 if found then
  if r.wallet_id<>p_wallet_id or r.user_id<>p_user_id or r.amount<>p_amount then raise exception 'idempotency conflict'; end if;
  return jsonb_build_object('reservation_id',r.id,'status',r.status,'amount',r.amount,'expires_at',r.expires_at);
 end if;
 select * into w from public.wallet_accounts where id=p_wallet_id for update;
 if not found or w.status<>'active' then raise exception 'wallet unavailable'; end if;
 if w.owner_type='user' and w.owner_id<>p_user_id then raise exception 'wallet ownership mismatch'; end if;
 if w.balance < p_amount then raise exception 'insufficient credits'; end if;
 next_balance := w.balance-p_amount;
 update public.wallet_accounts set balance=next_balance,updated_at=now() where id=w.id;
 insert into public.credit_reservations(wallet_id,user_id,run_id,amount,status,idempotency_key,expires_at)
 values(p_wallet_id,p_user_id,p_run_id,p_amount,'reserved',p_idempotency_key,now()+make_interval(secs=>p_ttl_seconds)) returning * into r;
 insert into public.credit_ledger(wallet_id,entry_type,amount,balance_after,reference_type,reference_id,idempotency_key,description,created_by)
 values(p_wallet_id,'reserve',-p_amount,next_balance,'reservation',r.id,'reserve:'||p_idempotency_key,'Credit reservation',p_user_id);
 return jsonb_build_object('reservation_id',r.id,'status',r.status,'amount',r.amount,'expires_at',r.expires_at,'balance',next_balance);
end

declare r public.credit_reservations%rowtype; w public.wallet_accounts%rowtype;
 delta numeric(20,6); next_balance numeric(20,6);
begin
 if p_actual_amount < 0 then raise exception 'invalid settlement amount'; end if;
 select * into r from public.credit_reservations where id=p_reservation_id for update;
 if not found then raise exception 'reservation not found'; end if;
 if r.status='settled' then
  if r.settled_amount<>p_actual_amount then raise exception 'settlement idempotency conflict'; end if;
  return jsonb_build_object('reservation_id',r.id,'status',r.status,'settled_amount',r.settled_amount);
 end if;
 if r.status<>'reserved' then raise exception 'reservation is not active'; end if;
 select * into w from public.wallet_accounts where id=r.wallet_id for update;
 if not found then raise exception 'wallet not found'; end if;
 delta := r.amount-p_actual_amount;
 if delta < 0 then
  if w.balance < abs(delta) then raise exception 'insufficient balance for settlement overage'; end if;
  next_balance := w.balance-abs(delta);
  update public.wallet_accounts set balance=next_balance,updated_at=now() where id=w.id;
  insert into public.credit_ledger(wallet_id,entry_type,amount,balance_after,reference_type,reference_id,idempotency_key,description,created_by)
  values(w.id,'consume',delta,next_balance,'reservation',r.id,'settle-extra:'||p_idempotency_key,'Settlement overage',r.user_id);
 elsif delta > 0 then
  next_balance := w.balance+delta;
  update public.wallet_accounts set balance=next_balance,updated_at=now() where id=w.id;
  insert into public.credit_ledger(wallet_id,entry_type,amount,balance_after,reference_type,reference_id,idempotency_key,description,created_by)
  values(w.id,'release',delta,next_balance,'reservation',r.id,'settle-release:'||p_idempotency_key,'Unused reservation released',r.user_id);
 else next_balance := w.balance;
 end if;
 update public.credit_reservations set status='settled',settled_amount=p_actual_amount,settled_at=now() where id=r.id;
 insert into public.outbox_events(aggregate_type,aggregate_id,event_type,payload)
 values('credit_reservation',r.id,'credit.settled',jsonb_build_object('reservation_id',r.id,'wallet_id',w.id,'user_id',r.user_id,'amount',p_actual_amount));
 return jsonb_build_object('reservation_id',r.id,'status','settled','settled_amount',p_actual_amount,'balance',next_balance);
end

declare r public.credit_reservations%rowtype; w public.wallet_accounts%rowtype; next_balance numeric(20,6);
begin
 select * into r from public.credit_reservations where id=p_reservation_id for update;
 if not found then raise exception 'reservation not found'; end if;
 if r.status='released' then return jsonb_build_object('reservation_id',r.id,'status',r.status); end if;
 if r.status<>'reserved' then raise exception 'reservation is not active'; end if;
 select * into w from public.wallet_accounts where id=r.wallet_id for update;
 next_balance := w.balance+r.amount;
 update public.wallet_accounts set balance=next_balance,updated_at=now() where id=w.id;
 update public.credit_reservations set status='released',settled_amount=0,settled_at=now() where id=r.id;
 insert into public.credit_ledger(wallet_id,entry_type,amount,balance_after,reference_type,reference_id,idempotency_key,description,created_by)
 values(w.id,'release',r.amount,next_balance,'reservation',r.id,'release:'||p_idempotency_key,'Reservation released',r.user_id);
 insert into public.outbox_events(aggregate_type,aggregate_id,event_type,payload)
 values('credit_reservation',r.id,'credit.released',jsonb_build_object('reservation_id',r.id,'wallet_id',w.id,'user_id',r.user_id,'amount',r.amount));
 return jsonb_build_object('reservation_id',r.id,'status','released','balance',next_balance);
end

declare r public.agent_runs%rowtype;
begin
 if p_lease_seconds not between 15 and 900 then raise exception 'invalid lease duration'; end if;
 select * into r from public.agent_runs
 where status='queued' and available_at<=now() and attempt<max_attempts
 order by available_at,created_at
 for update skip locked limit 1;
 if not found then return null; end if;
 update public.agent_runs set status='running',attempt=attempt+1,started_at=coalesce(started_at,now()),updated_at=now()
 where id=r.id returning * into r;
 insert into public.agent_run_events(run_id,event_type,sequence,payload)
 select r.id,'worker.claimed',coalesce(max(sequence),0)+1,jsonb_build_object('attempt',r.attempt,'lease_seconds',p_lease_seconds)
 from public.agent_run_events where run_id=r.id;
 return jsonb_build_object('id',r.id,'user_id',r.user_id,'workspace_id',r.workspace_id,'conversation_id',r.conversation_id,'status',r.status,'attempt',r.attempt,'max_attempts',r.max_attempts,'input',r.input);
end

declare seq bigint;
begin
 if not exists(select 1 from public.agent_runs where id=p_run_id and status='running') then raise exception 'run is not running'; end if;
 insert into public.agent_run_checkpoints(run_id,checkpoint_key,state)
 values(p_run_id,p_checkpoint_key,p_state)
 on conflict(run_id,checkpoint_key) do update set state=excluded.state,created_at=now();
 select coalesce(max(sequence),0)+1 into seq from public.agent_run_events where run_id=p_run_id;
 insert into public.agent_run_events(run_id,event_type,sequence,payload) values(p_run_id,p_event_type,seq,jsonb_build_object('checkpoint_key',p_checkpoint_key));
 return jsonb_build_object('run_id',p_run_id,'checkpoint_key',p_checkpoint_key,'sequence',seq);
end

declare r public.agent_runs%rowtype; seq bigint; next_status text;
begin
 if p_status not in('succeeded','failed','cancelled') then raise exception 'invalid terminal status'; end if;
 select * into r from public.agent_runs where id=p_run_id for update;
 if not found then raise exception 'run not found'; end if;
 if r.status in('succeeded','failed','cancelled') then return jsonb_build_object('run_id',r.id,'status',r.status); end if;
 if p_status='failed' and r.attempt<r.max_attempts then
   next_status:='queued';
   update public.agent_runs set status=next_status,error=p_error,available_at=now()+make_interval(secs=>greatest(1,least(p_retry_delay_seconds,3600))),updated_at=now() where id=r.id;
 else
   next_status:=p_status;
   update public.agent_runs set status=next_status,output=p_output,error=p_error,finished_at=now(),updated_at=now() where id=r.id;
 end if;
 select coalesce(max(sequence),0)+1 into seq from public.agent_run_events where run_id=r.id;
 insert into public.agent_run_events(run_id,event_type,sequence,payload)
 values(r.id,'worker.'||next_status,seq,jsonb_build_object('attempt',r.attempt,'error',p_error));
 return jsonb_build_object('run_id',r.id,'status',next_status,'attempt',r.attempt);
end

declare r public.agent_runs%rowtype; seq bigint;
begin
 if p_worker_id is null or length(p_worker_id)<8 or length(p_worker_id)>128 or p_lease_seconds not between 15 and 900 then raise exception 'invalid worker claim'; end if;
 update public.agent_runs set status='failed',finished_at=now(),dead_lettered_at=now(),lease_owner=null,lease_expires_at=null,updated_at=now()
 where status='running' and lease_expires_at<now() and attempt>=max_attempts;
 insert into public.agent_run_events(run_id,event_type,sequence,payload)
 select id,'worker.dead_lettered',coalesce((select max(e.sequence) from public.agent_run_events e where e.run_id=agent_runs.id),0)+1,jsonb_build_object('reason','lease_expired_max_attempts')
 from public.agent_runs where dead_lettered_at is not null and finished_at > now()-interval '2 seconds' and status='failed';
 select * into r from public.agent_runs
 where ((status='queued' and available_at<=now()) or (status='running' and lease_expires_at<now()))
 and attempt<max_attempts and cancel_requested_at is null
 order by available_at,created_at for update skip locked limit 1;
 if not found then return null; end if;
 update public.agent_runs set status='running',attempt=attempt+1,lease_owner=p_worker_id,
 lease_expires_at=now()+make_interval(secs=>p_lease_seconds),heartbeat_at=now(),
 started_at=coalesce(started_at,now()),updated_at=now()
 where id=r.id returning * into r;
 select coalesce(max(sequence),0)+1 into seq from public.agent_run_events where run_id=r.id;
 insert into public.agent_run_events(run_id,event_type,sequence,payload) values(r.id,'worker.claimed',seq,jsonb_build_object('worker_id',p_worker_id,'attempt',r.attempt,'lease_seconds',p_lease_seconds));
 return jsonb_build_object('id',r.id,'user_id',r.user_id,'workspace_id',r.workspace_id,'conversation_id',r.conversation_id,'agent_definition_id',r.agent_definition_id,'status',r.status,'attempt',r.attempt,'max_attempts',r.max_attempts,'input',r.input,'lease_owner',r.lease_owner,'lease_expires_at',r.lease_expires_at);
end

declare r public.agent_runs%rowtype;
begin
 if p_lease_seconds not between 15 and 900 then raise exception 'invalid lease duration'; end if;
 update public.agent_runs set heartbeat_at=now(),lease_expires_at=now()+make_interval(secs=>p_lease_seconds),updated_at=now()
 where id=p_run_id and status='running' and lease_owner=p_worker_id and cancel_requested_at is null
 returning * into r;
 if not found then return jsonb_build_object('alive',false,'cancel_requested',exists(select 1 from public.agent_runs where id=p_run_id and cancel_requested_at is not null)); end if;
 return jsonb_build_object('alive',true,'lease_expires_at',r.lease_expires_at);
end

