 values(p_user_id,p_run_id,p_idempotency_key,p_request_hash)
 on conflict(user_id,idempotency_key) do nothing returning * into r;
 if found then created:=true;
 else
  select * into r from public.llm_request_records where user_id=p_user_id and idempotency_key=p_idempotency_key for update;
  if r.request_hash<>p_request_hash then raise exception 'idempotency key reused with different request'; end if;
 end if;
 return jsonb_build_object('created',created,'id',r.id,'status',r.status,'reservation_id',r.reservation_id,'response_text',r.response_text,'provider_key',r.provider_key,'model_key',r.model_key,'input_tokens',r.input_tokens,'output_tokens',r.output_tokens,'actual_cost',r.actual_cost,'error_code',r.error_code);
end

declare r public.llm_request_records%rowtype;
begin
 update public.llm_request_records set reservation_id=coalesce(reservation_id,p_reservation_id),estimated_cost=p_estimated_cost,updated_at=now()
 where id=p_request_id and status='processing' returning * into r;
 if not found then select * into r from public.llm_request_records where id=p_request_id; end if;
 if r.reservation_id is distinct from p_reservation_id then raise exception 'reservation mismatch'; end if;
 return jsonb_build_object('id',r.id,'reservation_id',r.reservation_id,'status',r.status);
end

declare r public.llm_request_records%rowtype;
begin
 if p_input_tokens<0 or p_output_tokens<0 or p_actual_cost<0 or p_latency_ms<0 then raise exception 'invalid provider usage'; end if;
 update public.llm_request_records set status='provider_succeeded',provider_key=p_provider_key,model_key=p_model_key,
 response_text=p_response_text,input_tokens=p_input_tokens,output_tokens=p_output_tokens,
 actual_cost=p_actual_cost,latency_ms=p_latency_ms,updated_at=now()
 where id=p_request_id and status in ('processing','provider_succeeded') returning * into r;
 if not found then select * into r from public.llm_request_records where id=p_request_id; end if;
 if r.status not in ('provider_succeeded','succeeded') then raise exception 'request cannot accept provider result'; end if;
 return jsonb_build_object('id',r.id,'status',r.status);
end

declare r public.llm_request_records%rowtype; u public.llm_usage%rowtype;
begin
 select * into r from public.llm_request_records where id=p_request_id for update;
 if not found then raise exception 'llm request not found'; end if;
 if r.status='succeeded' then return jsonb_build_object('id',r.id,'status','succeeded','response_text',r.response_text); end if;
 if r.status<>'provider_succeeded' or r.reservation_id is null then raise exception 'llm request is not ready for settlement'; end if;
 perform public.moreai_credit_settle(r.reservation_id,p_actual_credits,p_settlement_key);
 insert into public.llm_usage(user_id,run_id,provider_key,model_key,request_id,input_tokens,output_tokens,estimated_cost,actual_cost,status,idempotency_key,latency_ms,reservation_id,provider_response_id)
 values(r.user_id,r.run_id,r.provider_key,r.model_key,r.id::text,r.input_tokens,r.output_tokens,r.estimated_cost,r.actual_cost,'succeeded',r.idempotency_key,r.latency_ms,r.reservation_id,p_provider_response_id)
 on conflict(user_id,idempotency_key) do nothing;
 update public.llm_request_records set status='succeeded',updated_at=now() where id=r.id;
 return jsonb_build_object('id',r.id,'status','succeeded','response_text',r.response_text);
end

declare r public.llm_request_records%rowtype;
begin
 select * into r from public.llm_request_records where id=p_request_id for update;
 if not found then raise exception 'llm request not found'; end if;
 if r.status in ('succeeded','failed') then return jsonb_build_object('id',r.id,'status',r.status); end if;
 if p_release and r.reservation_id is not null then
  perform public.moreai_credit_release(r.reservation_id,coalesce(p_release_key,'llm-release:'||r.id::text));
  update public.llm_request_records set status='failed',error_code=p_error_code,updated_at=now() where id=r.id;
 else
  update public.llm_request_records set status='unknown',error_code=p_error_code,updated_at=now() where id=r.id;
 end if;
 return jsonb_build_object('id',r.id,'status',case when p_release then 'failed' else 'unknown' end);
end

declare v_method public.network_verification_method_catalog%rowtype; v_config public.network_verification_configs%rowtype;
begin
 select * into v_method from public.network_verification_method_catalog where method_key=p_method_key and enabled=true;
 if not found then raise exception using errcode='22023',message='VERIFICATION_METHOD_NOT_AVAILABLE'; end if;
 update public.partner_networks set active_verification_method=p_method_key,updated_at=now() where id=p_network_id;
 if not found then raise exception using errcode='P0002',message='NETWORK_NOT_FOUND'; end if;
 update public.network_verification_configs set enabled=false,updated_at=now() where network_id=p_network_id and method_key<>p_method_key and enabled=true;
 insert into public.network_verification_configs(network_id,method_key,config_public,enabled,policy)
 values(p_network_id,p_method_key,coalesce(p_config_public,'{}'::jsonb),false,'{}'::jsonb)
 on conflict(network_id,method_key) do update set config_public=excluded.config_public,enabled=false,updated_at=now()
 returning * into v_config;
 return jsonb_build_object('network_id',p_network_id,'active_method',p_method_key,'selected',true,'activated',false,'adapter_ready',v_method.adapter_ready);
end;

declare v_selected_method text; v_adapter_ready boolean;
begin
 if new.enabled then
  select active_verification_method into v_selected_method from public.partner_networks where id=new.network_id;
  if v_selected_method is distinct from new.method_key then raise exception using errcode='23514',message='ONLY_SELECTED_VERIFICATION_METHOD_CAN_BE_ENABLED'; end if;
  select adapter_ready into v_adapter_ready from public.network_verification_method_catalog where method_key=new.method_key and enabled=true;
  if coalesce(v_adapter_ready,false) is not true then raise exception using errcode='23514',message='VERIFICATION_ADAPTER_NOT_READY'; end if;
 end if;
 return new;
end;

declare v_inserted uuid;
begin
 if p_expires_at<=now() or p_expires_at>now()+interval '5 minutes' then return false; end if;
 delete from public.network_gateway_nonces where expires_at<now()-interval '1 hour';
 insert into public.network_gateway_nonces(network_id,nonce_hash,expires_at) values(p_network_id,p_nonce_hash,p_expires_at)
 on conflict(network_id,nonce_hash) do nothing returning id into v_inserted;
 return v_inserted is not null;
end;

declare
  v_partner public.partner_organizations%rowtype;
  v_member public.partner_members%rowtype;
  v_count integer;
  v_correlation text := coalesce(nullif(p_correlation_id, ''), gen_random_uuid()::text);
begin
  if p_user_id is null
    or length(trim(coalesce(p_legal_name, ''))) < 2
    or length(trim(coalesce(p_legal_name, ''))) > 160
    or length(trim(coalesce(p_display_name, ''))) < 2
    or length(trim(coalesce(p_display_name, ''))) > 120 then
    raise exception using errcode = '22023', message = 'PARTNER_APPLICATION_INVALID';
  end if;

  select count(*) into v_count from public.partner_members where user_id = p_user_id;
  if v_count > 1 then
    raise exception using errcode = '23505', message = 'PARTNER_CONTEXT_AMBIGUOUS';
  elsif v_count = 1 then
    select po.* into v_partner
    from public.partner_members pm
    join public.partner_organizations po on po.id = pm.partner_id
    where pm.user_id = p_user_id
    limit 1;
    select pm.* into v_member
    from public.partner_members pm
    where pm.user_id = p_user_id
    limit 1;
    return jsonb_build_object(
      'partner', to_jsonb(v_partner),
      'membership', to_jsonb(v_member),
      'replayed', true
    );
  end if;

  insert into public.partner_organizations(
    legal_name, display_name, status, created_by
  ) values (
    trim(p_legal_name), trim(p_display_name), 'pending', p_user_id
  ) returning * into v_partner;

  insert into public.partner_members(
    partner_id, user_id, role_key, location_id, status
  ) values (
    v_partner.id, p_user_id, 'partner_owner', null, 'active'
  ) returning * into v_member;

  insert into public.admin_audit_logs(
    actor_user_id, action, resource_type, resource_id, scope_type, scope_id,
    correlation_id, outcome, metadata
  ) values (
    p_user_id, 'partner.application.submitted', 'partner_organization',
    v_partner.id::text, 'partner', v_partner.id, v_correlation, 'success',
    jsonb_build_object('legal_name', v_partner.legal_name, 'display_name', v_partner.display_name)
  );

  return jsonb_build_object(
    'partner', to_jsonb(v_partner),
    'membership', to_jsonb(v_member),
    'replayed', false
  );
end;

declare
  v_partner public.partner_organizations%rowtype;
  v_next_status text;
  v_correlation text := coalesce(nullif(p_correlation_id, ''), gen_random_uuid()::text);
begin
  if p_actor_user_id is null or p_partner_id is null
    or p_decision is null or p_decision not in ('approve', 'reject', 'suspend')
    or length(coalesce(p_reason, '')) > 500 then
    raise exception using errcode = '22023', message = 'PARTNER_REVIEW_INVALID';
  end if;

  if not exists (
    select 1
    from public.user_role_assignments ura
    join public.roles r on r.id = ura.role_id
    join public.role_permissions rp on rp.role_id = r.id
    join public.permissions p on p.id = rp.permission_id
    where ura.user_id = p_actor_user_id
      and ura.scope_type = 'platform'
      and ura.scope_id is null
      and (ura.expires_at is null or ura.expires_at > now())
      and r.scope = 'platform'
      and p.key = 'partner.organization.manage'
  ) then
    raise exception using errcode = '42501', message = 'ADMIN_PERMISSION_DENIED';
  end if;

  select * into v_partner
  from public.partner_organizations
  where id = p_partner_id
  for update;

  if not found then
    raise exception using errcode = 'P0002', message = 'PARTNER_NOT_FOUND';
  end if;

  v_next_status := case p_decision
    when 'approve' then 'active'
    when 'reject' then 'rejected'
    when 'suspend' then 'suspended'
  end;

  if v_partner.status = v_next_status then
    return jsonb_build_object('partner', to_jsonb(v_partner), 'replayed', true);
  end if;

  if (p_decision in ('approve', 'reject') and v_partner.status <> 'pending')
    or (p_decision = 'suspend' and v_partner.status <> 'active') then
    raise exception using errcode = '55000', message = 'PARTNER_STATUS_TRANSITION_INVALID';
  end if;

  update public.partner_organizations
  set status = v_next_status, updated_at = now()
  where id = p_partner_id
  returning * into v_partner;

  update public.partner_members
  set status = case when p_decision = 'approve' then 'active' else 'suspended' end
  where partner_id = p_partner_id;

  insert into public.admin_audit_logs(
    actor_user_id, action, resource_type, resource_id, scope_type, scope_id,
    correlation_id, outcome, metadata
  ) values (
    p_actor_user_id, 'partner.application.' || p_decision, 'partner_organization',
    p_partner_id::text, 'partner', p_partner_id, v_correlation, 'success',
    jsonb_build_object('previous_status', case when p_decision in ('approve','reject') then 'pending' else 'active' end,
      'new_status', v_next_status, 'reason', p_reason)
  );

  return jsonb_build_object('partner', to_jsonb(v_partner), 'replayed', false);
end;

declare
  v_partner public.partner_organizations%rowtype;
  v_member public.partner_members%rowtype;
  v_count integer;
  v_correlation text := coalesce(nullif(p_correlation_id, ''), gen_random_uuid()::text);
begin
  if p_user_id is null or length(trim(coalesce(p_legal_name, ''))) < 2
    or length(trim(coalesce(p_legal_name, ''))) > 160
    or length(trim(coalesce(p_display_name, ''))) < 2
    or length(trim(coalesce(p_display_name, ''))) > 120 then
    raise exception using errcode = '22023', message = 'PARTNER_APPLICATION_INVALID';
  end if;

  perform pg_advisory_xact_lock(hashtextextended(p_user_id::text, 0));
  select count(*) into v_count from public.partner_members where user_id = p_user_id;
  if v_count > 1 then
    raise exception using errcode = '23505', message = 'PARTNER_CONTEXT_AMBIGUOUS';
  elsif v_count = 1 then
    select po.* into v_partner from public.partner_members pm
      join public.partner_organizations po on po.id = pm.partner_id
      where pm.user_id = p_user_id limit 1;
    select pm.* into v_member from public.partner_members pm where pm.user_id = p_user_id limit 1;
    return jsonb_build_object('partner', to_jsonb(v_partner), 'membership', to_jsonb(v_member), 'replayed', true);
  end if;

  insert into public.partner_organizations(legal_name, display_name, status, created_by)
  values(trim(p_legal_name), trim(p_display_name), 'pending', p_user_id) returning * into v_partner;
  insert into public.partner_members(partner_id, user_id, role_key, location_id, status)
  values(v_partner.id, p_user_id, 'partner_owner', null, 'active') returning * into v_member;
  insert into public.admin_audit_logs(actor_user_id, action, resource_type, resource_id, scope_type, scope_id, correlation_id, outcome, metadata)
  values(p_user_id, 'partner.application.submitted', 'partner_organization', v_partner.id::text, 'partner', v_partner.id, v_correlation, 'success',
    jsonb_build_object('legal_name', v_partner.legal_name, 'display_name', v_partner.display_name));
  return jsonb_build_object('partner', to_jsonb(v_partner), 'membership', to_jsonb(v_member), 'replayed', false);
end;

declare v_provider public.llm_providers%rowtype; v_action text;
begin
  if p_actor_user_id is null or p_key not in ('google','openai','anthropic')
    or length(trim(coalesce(p_display_name,'')))<2 or length(trim(coalesce(p_display_name,'')))>120 then
    raise exception using errcode='22023',message='LLM_PROVIDER_INVALID';
  end if;
  if not exists(
    select 1 from public.user_role_assignments ura
    join public.roles r on r.id=ura.role_id
    join public.role_permissions rp on rp.role_id=r.id
    join public.permissions p on p.id=rp.permission_id
    where ura.user_id=p_actor_user_id and ura.scope_type='platform' and ura.scope_id is null
      and (ura.expires_at is null or ura.expires_at>now()) and r.scope='platform'
      and p.key='platform.models.manage'
  ) then raise exception using errcode='42501',message='ADMIN_PERMISSION_DENIED'; end if;
  if p_enabled and not coalesce(p_credentials_ready,false) then
    raise exception using errcode='55000',message='PROVIDER_CREDENTIALS_NOT_CONFIGURED';
  end if;
  if p_provider_id is null then
    insert into public.llm_providers(key,display_name,enabled,config)
    values(p_key,trim(p_display_name),p_enabled,'{}'::jsonb) returning * into v_provider;
    v_action:='llm.provider.create';
  else
    select * into v_provider from public.llm_providers where id=p_provider_id for update;
    if not found then raise exception using errcode='P0002',message='LLM_PROVIDER_NOT_FOUND'; end if;
    if v_provider.key<>p_key then raise exception using errcode='22023',message='LLM_PROVIDER_KEY_IMMUTABLE'; end if;
    update public.llm_providers set display_name=trim(p_display_name),enabled=p_enabled,updated_at=now()
      where id=p_provider_id returning * into v_provider;
    v_action:='llm.provider.update';
  end if;
  insert into public.admin_audit_logs(actor_user_id,action,resource_type,resource_id,scope_type,correlation_id,outcome,metadata)
  values(p_actor_user_id,v_action,'llm_provider',v_provider.id::text,'platform',
    coalesce(nullif(p_correlation_id,''),gen_random_uuid()::text),'success',
    jsonb_build_object('key',v_provider.key,'display_name',v_provider.display_name,'enabled',v_provider.enabled,'credentials_ready',coalesce(p_credentials_ready,false)));
  return jsonb_build_object('id',v_provider.id,'key',v_provider.key,'display_name',v_provider.display_name,'enabled',v_provider.enabled);
end;

declare v_model public.llm_models%rowtype; v_provider public.llm_providers%rowtype; v_action text;
begin
  if p_actor_user_id is null or p_provider_id is null or length(trim(coalesce(p_key,'')))<1
    or length(trim(coalesce(p_key,'')))>160 or length(trim(coalesce(p_display_name,'')))<2
    or length(trim(coalesce(p_display_name,'')))>160
    or p_input_cost_per_million<0 or p_output_cost_per_million<0
    or (p_max_input_tokens is not null and p_max_input_tokens<1)
    or (p_max_output_tokens is not null and p_max_output_tokens<1) then
    raise exception using errcode='22023',message='LLM_MODEL_INVALID';
  end if;
  if not exists(
    select 1 from public.user_role_assignments ura join public.roles r on r.id=ura.role_id
    join public.role_permissions rp on rp.role_id=r.id join public.permissions p on p.id=rp.permission_id
    where ura.user_id=p_actor_user_id and ura.scope_type='platform' and ura.scope_id is null
      and (ura.expires_at is null or ura.expires_at>now()) and r.scope='platform' and p.key='platform.models.manage'
  ) then raise exception using errcode='42501',message='ADMIN_PERMISSION_DENIED'; end if;
  select * into v_provider from public.llm_providers where id=p_provider_id for share;
  if not found then raise exception using errcode='P0002',message='LLM_PROVIDER_NOT_FOUND'; end if;
  if p_enabled and not v_provider.enabled then raise exception using errcode='55000',message='LLM_PROVIDER_DISABLED'; end if;
  if p_model_id is null then
    insert into public.llm_models(provider_id,key,display_name,input_cost_per_million,output_cost_per_million,
      max_input_tokens,max_output_tokens,capabilities,enabled)
    values(p_provider_id,trim(p_key),trim(p_display_name),p_input_cost_per_million,p_output_cost_per_million,
      p_max_input_tokens,p_max_output_tokens,coalesce(p_capabilities,'{}'::text[]),p_enabled)
    returning * into v_model;
    v_action:='llm.model.create';
  else
    select * into v_model from public.llm_models where id=p_model_id for update;
    if not found then raise exception using errcode='P0002',message='LLM_MODEL_NOT_FOUND'; end if;
    update public.llm_models set provider_id=p_provider_id,key=trim(p_key),display_name=trim(p_display_name),
      input_cost_per_million=p_input_cost_per_million,output_cost_per_million=p_output_cost_per_million,
      max_input_tokens=p_max_input_tokens,max_output_tokens=p_max_output_tokens,
      capabilities=coalesce(p_capabilities,'{}'::text[]),enabled=p_enabled,updated_at=now()
      where id=p_model_id returning * into v_model;
    v_action:='llm.model.update';
  end if;
  insert into public.admin_audit_logs(actor_user_id,action,resource_type,resource_id,scope_type,correlation_id,outcome,metadata)
  values(p_actor_user_id,v_action,'llm_model',v_model.id::text,'platform',
    coalesce(nullif(p_correlation_id,''),gen_random_uuid()::text),'success',
    jsonb_build_object('provider_id',v_model.provider_id,'key',v_model.key,'display_name',v_model.display_name,
      'enabled',v_model.enabled,'input_cost_per_million',v_model.input_cost_per_million,
      'output_cost_per_million',v_model.output_cost_per_million,'capabilities',v_model.capabilities));
  return jsonb_build_object('id',v_model.id,'provider_id',v_model.provider_id,'key',v_model.key,
    'display_name',v_model.display_name,'enabled',v_model.enabled,'input_cost_per_million',v_model.input_cost_per_million,
    'output_cost_per_million',v_model.output_cost_per_million,'max_input_tokens',v_model.max_input_tokens,
    'max_output_tokens',v_model.max_output_tokens,'capabilities',v_model.capabilities);
end;

declare v_policy public.llm_routing_policies%rowtype; v_action text;
begin
  if p_actor_user_id is null or p_task_type<>'general' or p_model_id is null or p_priority<0 then
    raise exception using errcode='22023',message='LLM_ROUTE_INVALID';
  end if;
  if not exists(
    select 1 from public.user_role_assignments ura join public.roles r on r.id=ura.role_id
    join public.role_permissions rp on rp.role_id=r.id join public.permissions p on p.id=rp.permission_id
    where ura.user_id=p_actor_user_id and ura.scope_type='platform' and ura.scope_id is null
      and (ura.expires_at is null or ura.expires_at>now()) and r.scope='platform' and p.key='platform.models.manage'
  ) then raise exception using errcode='42501',message='ADMIN_PERMISSION_DENIED'; end if;
  if p_enabled and not exists(
    select 1 from public.llm_models m join public.llm_providers pr on pr.id=m.provider_id
    where m.id=p_model_id and m.enabled=true and pr.enabled=true
  ) then raise exception using errcode='55000',message='LLM_PRIMARY_MODEL_NOT_READY'; end if;
  if p_enabled and p_fallback_model_id is not null and not exists(
    select 1 from public.llm_models m join public.llm_providers pr on pr.id=m.provider_id
    where m.id=p_fallback_model_id and m.enabled=true and pr.enabled=true
  ) then raise exception using errcode='55000',message='LLM_FALLBACK_MODEL_NOT_READY'; end if;
  if p_policy_id is null then
    insert into public.llm_routing_policies(scope_type,scope_id,task_type,model_id,priority,fallback_model_id,enabled)
    values('platform',null,p_task_type,p_model_id,p_priority,p_fallback_model_id,p_enabled) returning * into v_policy;
    v_action:='llm.routing.create';
  else
    select * into v_policy from public.llm_routing_policies where id=p_policy_id and scope_type='platform' and scope_id is null for update;
    if not found then raise exception using errcode='P0002',message='LLM_ROUTE_NOT_FOUND'; end if;
    update public.llm_routing_policies set task_type=p_task_type,model_id=p_model_id,priority=p_priority,
      fallback_model_id=p_fallback_model_id,enabled=p_enabled where id=p_policy_id returning * into v_policy;
    v_action:='llm.routing.update';
  end if;
  insert into public.admin_audit_logs(actor_user_id,action,resource_type,resource_id,scope_type,correlation_id,outcome,metadata)
  values(p_actor_user_id,v_action,'llm_routing_policy',v_policy.id::text,'platform',
    coalesce(nullif(p_correlation_id,''),gen_random_uuid()::text),'success',
    jsonb_build_object('task_type',v_policy.task_type,'model_id',v_policy.model_id,
      'fallback_model_id',v_policy.fallback_model_id,'priority',v_policy.priority,'enabled',v_policy.enabled));
  return jsonb_build_object('id',v_policy.id,'task_type',v_policy.task_type,'model_id',v_policy.model_id,
    'fallback_model_id',v_policy.fallback_model_id,'priority',v_policy.priority,'enabled',v_policy.enabled);
end;

declare v_role public.roles%rowtype; v_assignment public.user_role_assignments%rowtype; v_correlation text:=coalesce(nullif(p_correlation_id,''),gen_random_uuid()::text);
begin
 if p_actor_user_id is null or p_target_user_id is null or p_role_key is null then
  raise exception using errcode='22023',message='ROLE_ASSIGNMENT_INVALID';
 end if;
 if not exists(select 1 from public.user_role_assignments ura join public.roles r on r.id=ura.role_id join public.role_permissions rp on rp.role_id=r.id join public.permissions p on p.id=rp.permission_id
