declare v_policy public.llm_routing_policies%rowtype; v_action text;
begin
 if p_actor_user_id is null or p_task_type<>'general' or p_model_id is null or p_priority<0 then raise exception using errcode='22023',message='LLM_ROUTE_INVALID'; end if;
 if not exists(select 1 from public.user_role_assignments ura join public.roles r on r.id=ura.role_id join public.role_permissions rp on rp.role_id=r.id join public.permissions p on p.id=rp.permission_id
  where ura.user_id=p_actor_user_id and ura.scope_type='platform' and ura.scope_id is null and (ura.expires_at is null or ura.expires_at>now()) and r.scope='platform' and p.key='platform.models.manage') then
  raise exception using errcode='42501',message='ADMIN_PERMISSION_DENIED';
 end if;
 if p_enabled and not exists(select 1 from public.llm_models m join public.llm_providers pr on pr.id=m.provider_id where m.id=p_model_id and m.enabled=true and pr.enabled=true) then
  raise exception using errcode='55000',message='LLM_PRIMARY_MODEL_NOT_READY';
 end if;
 if p_enabled and p_fallback_model_id is not null and not exists(select 1 from public.llm_models m join public.llm_providers pr on pr.id=m.provider_id where m.id=p_fallback_model_id and m.enabled=true and pr.enabled=true) then
  raise exception using errcode='55000',message='LLM_FALLBACK_MODEL_NOT_READY';
 end if;
 if p_policy_id is null then
  insert into public.llm_routing_policies(scope_type,scope_id,task_type,model_id,priority,fallback_model_id,enabled)
  values('platform',null,p_task_type,p_model_id,p_priority,p_fallback_model_id,p_enabled) returning * into v_policy;
  v_action:='llm.routing.create';
 else
  select * into v_policy from public.llm_routing_policies where id=p_policy_id and scope_type='platform' and scope_id is null for update;
  if not found then raise exception using errcode='P0002',message='LLM_ROUTE_NOT_FOUND'; end if;
  update public.llm_routing_policies set task_type=p_task_type,model_id=p_model_id,priority=p_priority,fallback_model_id=p_fallback_model_id,enabled=p_enabled
   where id=p_policy_id returning * into v_policy;
  v_action:='llm.routing.update';
 end if;
 insert into public.admin_audit_logs(actor_user_id,action,resource_type,resource_id,scope_type,correlation_id,outcome,metadata)
 values(p_actor_user_id,v_action,'llm_routing_policy',v_policy.id::text,'platform',coalesce(nullif(p_correlation_id,''),gen_random_uuid()::text),'success',
  jsonb_build_object('task_type',v_policy.task_type,'model_id',v_policy.model_id,'fallback_model_id',v_policy.fallback_model_id,'priority',v_policy.priority,'enabled',v_policy.enabled));
 return jsonb_build_object('id',v_policy.id,'task_type',v_policy.task_type,'model_id',v_policy.model_id,'fallback_model_id',v_policy.fallback_model_id,'priority',v_policy.priority,'enabled',v_policy.enabled);
end;

declare v_role public.roles%rowtype; v_assignment public.user_role_assignments%rowtype; v_correlation text:=coalesce(nullif(p_correlation_id,''),gen_random_uuid()::text);
begin
 if p_actor_user_id is null or p_target_user_id is null or p_role_key is null then raise exception using errcode='22023',message='ROLE_ASSIGNMENT_INVALID'; end if;
 if not exists(select 1 from public.user_role_assignments ura join public.roles r on r.id=ura.role_id join public.role_permissions rp on rp.role_id=r.id join public.permissions p on p.id=rp.permission_id
  where ura.user_id=p_actor_user_id and ura.scope_type='platform' and ura.scope_id is null and (ura.expires_at is null or ura.expires_at>now()) and r.scope='platform' and r.key='super_admin' and p.key='platform.roles.assign') then
  raise exception using errcode='42501',message='ADMIN_PERMISSION_DENIED'; end if;
 if p_expires_at is not null and p_expires_at<=now() then raise exception using errcode='22023',message='ROLE_EXPIRY_MUST_BE_FUTURE'; end if;
 select * into v_role from public.roles where key=p_role_key and scope='platform';
 if not found then raise exception using errcode='P0002',message='PLATFORM_ROLE_NOT_FOUND'; end if;
 perform pg_advisory_xact_lock(hashtextextended(p_target_user_id::text||':'||v_role.id::text,0));
 select * into v_assignment from public.user_role_assignments where user_id=p_target_user_id and role_id=v_role.id and scope_type='platform' and scope_id is null
  order by created_at desc limit 1 for update;
 if found then
  if v_assignment.expires_at is null or v_assignment.expires_at>now() then return jsonb_build_object('assignment',to_jsonb(v_assignment),'role_key',v_role.key,'replayed',true); end if;
  update public.user_role_assignments set assigned_by=p_actor_user_id,expires_at=p_expires_at where id=v_assignment.id returning * into v_assignment;
 else
  insert into public.user_role_assignments(user_id,role_id,scope_type,scope_id,assigned_by,expires_at) values(p_target_user_id,v_role.id,'platform',null,p_actor_user_id,p_expires_at) returning * into v_assignment;
 end if;
 insert into public.admin_audit_logs(actor_user_id,action,resource_type,resource_id,scope_type,correlation_id,outcome,metadata)
 values(p_actor_user_id,'rbac.role.assign','user_role_assignment',v_assignment.id::text,'platform',v_correlation,'success',jsonb_build_object('target_user_id',p_target_user_id,'role_key',v_role.key,'expires_at',v_assignment.expires_at));
 return jsonb_build_object('assignment',to_jsonb(v_assignment),'role_key',v_role.key,'replayed',false);
end;

declare v_assignment public.user_role_assignments%rowtype; v_role public.roles%rowtype; v_super_admin_count integer; v_correlation text:=coalesce(nullif(p_correlation_id,''),gen_random_uuid()::text);
begin
 if p_actor_user_id is null or p_assignment_id is null or length(coalesce(p_reason,''))>500 then raise exception using errcode='22023',message='ROLE_REVOCATION_INVALID'; end if;
 if not exists(select 1 from public.user_role_assignments ura join public.roles r on r.id=ura.role_id join public.role_permissions rp on rp.role_id=r.id join public.permissions p on p.id=rp.permission_id
  where ura.user_id=p_actor_user_id and ura.scope_type='platform' and ura.scope_id is null and (ura.expires_at is null or ura.expires_at>now()) and r.scope='platform' and r.key='super_admin' and p.key='platform.roles.assign') then
  raise exception using errcode='42501',message='ADMIN_PERMISSION_DENIED'; end if;
 select * into v_assignment from public.user_role_assignments where id=p_assignment_id and scope_type='platform' and scope_id is null for update;
 if not found then raise exception using errcode='P0002',message='ROLE_ASSIGNMENT_NOT_FOUND'; end if;
 select * into v_role from public.roles where id=v_assignment.role_id;
 if v_role.key='super_admin' and (v_assignment.expires_at is null or v_assignment.expires_at>now()) then
  perform pg_advisory_xact_lock(hashtextextended('moreai:super_admin_revocation',0));
  select count(*) into v_super_admin_count from public.user_role_assignments ura join public.roles r on r.id=ura.role_id
   where r.key='super_admin' and ura.scope_type='platform' and ura.scope_id is null and (ura.expires_at is null or ura.expires_at>now());
  if v_super_admin_count<=1 then raise exception using errcode='55000',message='LAST_SUPER_ADMIN_CANNOT_BE_REVOKED'; end if;
 end if;
 delete from public.user_role_assignments where id=p_assignment_id;
 insert into public.admin_audit_logs(actor_user_id,action,resource_type,resource_id,scope_type,correlation_id,outcome,metadata)
 values(p_actor_user_id,'rbac.role.revoke','user_role_assignment',p_assignment_id::text,'platform',v_correlation,'success',jsonb_build_object('target_user_id',v_assignment.user_id,'role_key',v_role.key,'reason',p_reason));
 return jsonb_build_object('assignment_id',p_assignment_id,'revoked',true);
end;

declare v_code public.partner_access_codes%rowtype; v_verification public.network_verification_sessions%rowtype; v_redemption public.partner_access_code_redemptions%rowtype; v_now timestamptz := now();
begin
 if p_code_hash !~ '^[0-9a-f]{64}$' or length(p_idempotency_key) not between 8 and 160 then raise exception using errcode='22023',message='ACCESS_CODE_INVALID'; end if;
 select * into v_verification from public.network_verification_sessions where id=p_verification_session_id and user_id=p_user_id and network_id=p_network_id and status='verified' and expires_at>v_now and ended_at is null;
 if not found then raise exception using errcode='42501',message='NETWORK_VERIFICATION_REQUIRED'; end if;
 select * into v_code from public.partner_access_codes where code_hash=p_code_hash for update;
 if not found or v_code.status<>'active' then raise exception using errcode='P0002',message='ACCESS_CODE_NOT_AVAILABLE'; end if;
 if v_code.expires_at<=v_now then update public.partner_access_codes set status='expired' where id=v_code.id; raise exception using errcode='P0002',message='ACCESS_CODE_EXPIRED'; end if;
 if v_code.redemption_count>=v_code.max_redemptions then update public.partner_access_codes set status='exhausted' where id=v_code.id; raise exception using errcode='P0002',message='ACCESS_CODE_EXHAUSTED'; end if;
 if v_code.network_id is not null and v_code.network_id<>p_network_id then raise exception using errcode='42501',message='ACCESS_CODE_NETWORK_MISMATCH'; end if;
 if v_code.location_id is not null and not exists(select 1 from public.partner_networks n where n.id=p_network_id and n.location_id=v_code.location_id and n.partner_id=v_code.partner_id) then raise exception using errcode='42501',message='ACCESS_CODE_SCOPE_MISMATCH'; end if;
 select * into v_redemption from public.partner_access_code_redemptions where user_id=p_user_id and idempotency_key=p_idempotency_key;
 if found then if v_redemption.access_code_id<>v_code.id then raise exception using errcode='23505',message='IDEMPOTENCY_KEY_CONFLICT'; end if; return jsonb_build_object('redemption_id',v_redemption.id,'replayed',true,'redeemed_at',v_redemption.redeemed_at); end if;
 insert into public.partner_access_code_redemptions(access_code_id,user_id,network_id,verification_session_id,idempotency_key) values(v_code.id,p_user_id,p_network_id,p_verification_session_id,p_idempotency_key) returning * into v_redemption;
 update public.partner_access_codes set redemption_count=redemption_count+1,status=case when redemption_count+1>=max_redemptions then 'exhausted' else 'active' end where id=v_code.id;
 if v_code.reward_id is not null then update public.campaign_rewards set quantity_claimed=quantity_claimed+1 where id=v_code.reward_id and (quantity_limit is null or quantity_claimed<quantity_limit); if not found then raise exception using errcode='P0001',message='REWARD_QUOTA_EXHAUSTED'; end if; end if;
 insert into public.admin_audit_logs(actor_user_id,action,resource_type,resource_id,scope_type,scope_id,outcome,metadata) values(p_user_id,'partner.access_code.redeemed','partner_access_code',v_code.id,'partner',v_code.partner_id,'success',jsonb_build_object('network_id',p_network_id,'redemption_id',v_redemption.id));
 return jsonb_build_object('redemption_id',v_redemption.id,'replayed',false,'redeemed_at',v_redemption.redeemed_at,'reward_id',v_code.reward_id,'partner_entitlement_activated',false,'message','Access code redeemed; entitlement activation remains separate.');
end;

declare
    v_conversation public.conversations%rowtype;
    v_message public.conversation_messages%rowtype;
    v_run public.agent_runs%rowtype;
begin
    if p_user_id is null
       or p_conversation_id is null
       or p_content is null
       or length(btrim(p_content)) = 0
       or length(p_content) > 100000
       or p_agent_key is null
       or p_idempotency_key is null
       or length(p_idempotency_key) < 12
       or length(p_idempotency_key) > 128
       or p_agent_key not in ('manus', 'planning') then
        raise exception 'invalid chat enqueue request' using errcode = '22023';
    end if;

    select *
      into v_conversation
      from public.conversations
     where id = p_conversation_id
       and user_id = p_user_id
     for update;

    if not found then
        raise exception 'conversation not found' using errcode = '42501';
    end if;

    select *
      into v_run
      from public.agent_runs
     where user_id = p_user_id
       and idempotency_key = p_idempotency_key;

    if found then
        return pg_catalog.jsonb_build_object(
            'run', pg_catalog.to_jsonb(v_run),
            'message', null,
            'replayed', true
        );
    end if;

    insert into public.conversation_messages (
        conversation_id, user_id, role, content, metadata
    ) values (
        p_conversation_id, p_user_id, 'user', p_content, '{}'::jsonb
    )
    returning * into v_message;

    insert into public.agent_runs (
        user_id, workspace_id, conversation_id, status,
        idempotency_key, input, max_attempts
    ) values (
        p_user_id,
        v_conversation.workspace_id,
        p_conversation_id,
        'queued',
        p_idempotency_key,
        pg_catalog.jsonb_build_object(
            'prompt', p_content,
            'agent_key', p_agent_key,
            'conversation_id', p_conversation_id,
            'message_id', v_message.id
        ),
        3
    )
    returning * into v_run;

    update public.conversation_messages
       set run_id = v_run.id
     where id = v_message.id
       and user_id = p_user_id;
    v_message.run_id := v_run.id;

    return pg_catalog.jsonb_build_object(
        'run', pg_catalog.to_jsonb(v_run),
        'message', pg_catalog.to_jsonb(v_message),
        'replayed', false
    );
end;

declare
    v_request public.llm_request_records%rowtype;
    v_entitlement public.user_entitlements%rowtype;
    v_policy public.quota_policies%rowtype;
    v_usage public.quota_usage%rowtype;
    v_window_start timestamptz;
    v_reservation jsonb;
    v_applied jsonb := '[]'::jsonb;
begin
    if p_request_id is null
       or p_user_id is null
       or p_wallet_id is null
       or p_credit_amount <= 0
       or p_estimated_cost < 0
       or p_quota_amount <= 0
       or p_reservation_key is null
       or p_entitlement_key is null
       or p_quota_metric_key is null then
        raise exception 'invalid llm reserve request' using errcode = '22023';
    end if;

    select *
      into v_request
      from public.llm_request_records
     where id = p_request_id
       and user_id = p_user_id
       and (run_id is not distinct from p_run_id)
       and status = 'processing'
     for update;

    if not found then
        raise exception 'llm request is not claimable' using errcode = '55000';
    end if;

    select *
      into v_entitlement
      from public.user_entitlements
     where user_id = p_user_id
       and entitlement_key = p_entitlement_key
       and status = 'active'
       and starts_at <= now()
       and (expires_at is null or expires_at > now())
     order by starts_at desc
     limit 1
     for share;

    if not found then
        raise exception 'required entitlement is not active' using errcode = '42501';
    end if;

    for v_policy in
        select *
          from public.quota_policies q
         where q.metric_key = p_quota_metric_key
           and q.enabled = true
           and (
                (q.scope_type in ('platform', 'global') and q.scope_id is null)
             or (q.scope_type = 'user' and q.scope_id = p_user_id)
             or (q.scope_type = 'workspace' and p_workspace_id is not null and q.scope_id = p_workspace_id)
             or (q.scope_type = 'partner' and p_partner_id is not null and q.scope_id = p_partner_id)
           )
         order by q.id
         for update
    loop
        v_window_start := pg_catalog.to_timestamp(
            (pg_catalog.floor(extract(epoch from now()) / v_policy.window_seconds)
            * v_policy.window_seconds)::double precision
        );

        -- Serialize creation/update for the same policy window, including platform scope_id NULL.
        perform pg_catalog.pg_advisory_xact_lock(
            pg_catalog.hashtext(v_policy.id::text),
            pg_catalog.hashtext(v_window_start::text)
        );

        select *
          into v_usage
          from public.quota_usage
         where policy_id = v_policy.id
           and scope_type = v_policy.scope_type
           and scope_id is not distinct from v_policy.scope_id
           and metric_key = v_policy.metric_key
           and window_start = v_window_start
         for update;

        if not found then
            insert into public.quota_usage (
                policy_id, scope_type, scope_id, metric_key, window_start, used_value
            ) values (
                v_policy.id, v_policy.scope_type, v_policy.scope_id,
                v_policy.metric_key, v_window_start, 0
            )
            returning * into v_usage;
        end if;

        if v_usage.used_value + p_quota_amount > v_policy.limit_value then
            raise exception 'quota exceeded for metric %', p_quota_metric_key using errcode = '54000';
        end if;

        update public.quota_usage
           set used_value = used_value + p_quota_amount,
               updated_at = now()
         where id = v_usage.id;

        v_applied := v_applied || pg_catalog.jsonb_build_array(
            pg_catalog.jsonb_build_object(
                'policy_id', v_policy.id,
                'scope_type', v_policy.scope_type,
                'metric_key', v_policy.metric_key,
                'window_start', v_window_start,
                'limit_value', v_policy.limit_value,
                'used_value', v_usage.used_value + p_quota_amount
            )
        );
    end loop;

    if pg_catalog.jsonb_array_length(v_applied) = 0 then
        raise exception 'no applicable quota policy' using errcode = '55000';
    end if;

    v_reservation := public.moreai_credit_reserve(
        p_wallet_id,
        p_user_id,
        p_credit_amount,
        p_reservation_key,
        p_run_id,
        900
    );

    perform public.moreai_llm_set_reservation(
        p_request_id,
        (v_reservation ->> 'reservation_id')::uuid,
        p_estimated_cost
    );

    return pg_catalog.jsonb_build_object(
        'request_id', p_request_id,
        'reservation_id', v_reservation ->> 'reservation_id',
        'quota', v_applied,
        'status', 'reserved'
    );
end;

