                'scope_type', v_policy.scope_type,
                'scope_id', v_policy.scope_id,
                'metric_key', v_policy.metric_key,
                'window_start', v_window_start,
                'limit_value', v_policy.limit_value,
                'used_value', v_usage.used_value + p_quota_amount,
                'reserved_amount', p_quota_amount
            )
        );
    end loop;

    if pg_catalog.jsonb_array_length(v_applied) = 0 then
        raise exception 'no applicable quota policy' using errcode = '55000';
    end if;

    update public.llm_request_records
       set quota_reservation = v_applied, updated_at = now()
     where id = p_request_id;

    v_reservation := public.moreai_credit_reserve(
        p_wallet_id,
        p_user_id,
        p_credit_amount,
        p_reservation_key,
        p_run_id,
        900
    );

    perform public.moreai_llm_set_reservation(
        p_request_id,
        (v_reservation ->> 'reservation_id')::uuid,
        p_estimated_cost
    );

    return pg_catalog.jsonb_build_object(
        'request_id', p_request_id,
        'reservation_id', v_reservation ->> 'reservation_id',
        'quota', v_applied,
        'status', 'reserved'
    );
end;

declare
    r public.llm_request_records%rowtype;
    v_item jsonb;
    v_usage public.quota_usage%rowtype;
    v_limit numeric;
    v_reserved numeric;
    v_new_used numeric;
begin
    if p_actual_credits is null or p_actual_credits < 0 then
        raise exception 'invalid actual credits' using errcode = '22023';
    end if;

    select * into r from public.llm_request_records where id = p_request_id for update;
    if not found then raise exception 'llm request not found'; end if;
    if r.status = 'succeeded' then
        return pg_catalog.jsonb_build_object('id', r.id, 'status', 'succeeded', 'response_text', r.response_text);
    end if;
    if r.status <> 'provider_succeeded' or r.reservation_id is null then
        raise exception 'llm request is not ready for settlement';
    end if;

    -- Reconcile reserved quota to actual billable credits within each original policy window.
    for v_item in select value from pg_catalog.jsonb_array_elements(coalesce(r.quota_reservation, '[]'::jsonb))
    loop
        v_reserved := (v_item ->> 'reserved_amount')::numeric;
        select * into v_usage
          from public.quota_usage
         where policy_id = (v_item ->> 'policy_id')::uuid
           and scope_type = v_item ->> 'scope_type'
           and scope_id is not distinct from (v_item ->> 'scope_id')::uuid
           and metric_key = v_item ->> 'metric_key'
           and window_start = (v_item ->> 'window_start')::timestamptz
         for update;
        if not found then raise exception 'reserved quota usage row missing'; end if;
        select limit_value into v_limit
          from public.quota_policies
         where id = (v_item ->> 'policy_id')::uuid
         for share;
        if not found then raise exception 'quota policy missing during settlement'; end if;
        v_new_used := v_usage.used_value - v_reserved + p_actual_credits;
        if v_new_used < 0 or v_new_used > v_limit then
            raise exception 'actual usage exceeds reserved quota or policy limit' using errcode = '54000';
        end if;
        update public.quota_usage set used_value = v_new_used, updated_at = now() where id = v_usage.id;
    end loop;

    perform public.moreai_credit_settle(r.reservation_id, p_actual_credits, p_settlement_key);

    insert into public.llm_usage(
        user_id, run_id, provider_key, model_key, request_id, input_tokens, output_tokens,
        estimated_cost, actual_cost, status, idempotency_key, latency_ms, reservation_id, provider_response_id
    )
    values(
        r.user_id, r.run_id, r.provider_key, r.model_key, r.id::text, r.input_tokens, r.output_tokens,
        r.estimated_cost, r.actual_cost, 'succeeded', r.idempotency_key, r.latency_ms, r.reservation_id, p_provider_response_id
    )
    on conflict(user_id, idempotency_key) do nothing;

    update public.llm_request_records set status = 'succeeded', updated_at = now() where id = r.id;
    return pg_catalog.jsonb_build_object('id', r.id, 'status', 'succeeded', 'response_text', r.response_text);
end;

declare
    r public.llm_request_records%rowtype;
    v_item jsonb;
    v_usage public.quota_usage%rowtype;
    v_reserved numeric;
begin
    select * into r from public.llm_request_records where id = p_request_id for update;
    if not found then raise exception 'llm request not found'; end if;
    if r.status in ('succeeded', 'failed') then
        return pg_catalog.jsonb_build_object('id', r.id, 'status', r.status);
    end if;

    if p_release then
        if r.reservation_id is not null then
            perform public.moreai_credit_release(r.reservation_id, coalesce(p_release_key, 'llm-release:' || r.id::text));
        end if;
        for v_item in select value from pg_catalog.jsonb_array_elements(coalesce(r.quota_reservation, '[]'::jsonb))
        loop
            v_reserved := (v_item ->> 'reserved_amount')::numeric;
            select * into v_usage
              from public.quota_usage
             where policy_id = (v_item ->> 'policy_id')::uuid
               and scope_type = v_item ->> 'scope_type'
               and scope_id is not distinct from (v_item ->> 'scope_id')::uuid
               and metric_key = v_item ->> 'metric_key'
               and window_start = (v_item ->> 'window_start')::timestamptz
             for update;
            if found then
                update public.quota_usage
                   set used_value = case when used_value >= v_reserved then used_value - v_reserved else 0 end,
                       updated_at = now()
                 where id = v_usage.id;
            end if;
        end loop;
        update public.llm_request_records set status = 'failed', error_code = p_error_code, updated_at = now() where id = r.id;
    else
        -- Unknown provider outcome retains the reservation to prevent duplicate free execution.
        update public.llm_request_records set status = 'unknown', error_code = p_error_code, updated_at = now() where id = r.id;
    end if;
    return pg_catalog.jsonb_build_object('id', r.id, 'status', case when p_release then 'failed' else 'unknown' end);
end;

declare v_id uuid;
begin
  if p_tool_key not in ('bash','python_execute','browser','file_read','file_write','file_edit')
     or p_arguments_hash !~ '^[0-9a-f]{64}$'
     or p_expires_in_seconds < 60 or p_expires_in_seconds > 3600
     or char_length(p_summary) not between 1 and 1000 then
    raise exception 'invalid_tool_approval_request' using errcode = '22023';
  end if;
  if not exists (select 1 from public.agent_runs r where r.id=p_run_id and r.user_id=p_user_id) then
    raise exception 'approval_run_owner_mismatch' using errcode = '42501';
  end if;
  update public.agent_tool_approvals
     set status='expired'
   where run_id=p_run_id and tool_key=p_tool_key and arguments_hash=p_arguments_hash
     and status in ('pending','approved') and expires_at <= now();
  select id into v_id from public.agent_tool_approvals
   where run_id=p_run_id and tool_key=p_tool_key and arguments_hash=p_arguments_hash
     and status in ('pending','approved') and expires_at > now()
   order by requested_at desc
   limit 1;
  if v_id is not null then return v_id; end if;
  insert into public.agent_tool_approvals(run_id,user_id,tool_key,arguments_hash,summary,expires_at)
  values(p_run_id,p_user_id,p_tool_key,p_arguments_hash,p_summary,now()+make_interval(secs=>p_expires_in_seconds))
  returning id into v_id;
  return v_id;
end;

declare v_row public.agent_tool_approvals;
begin
  if p_decision not in ('approved','denied') then
    raise exception 'invalid_approval_decision' using errcode='22023';
  end if;
  update public.agent_tool_approvals
     set status=case when expires_at <= now() then 'expired' else p_decision end,
         decided_at=now(), decided_by=p_user_id
   where id=p_approval_id and user_id=p_user_id and status='pending'
   returning * into v_row;
  if not found then
    select * into v_row from public.agent_tool_approvals where id=p_approval_id and user_id=p_user_id;
    if not found then raise exception 'approval_not_found' using errcode='P0002'; end if;
    raise exception 'approval_not_pending' using errcode='55000';
  end if;
  return jsonb_build_object('id',v_row.id,'run_id',v_row.run_id,'tool_key',v_row.tool_key,
    'status',v_row.status,'decided_at',v_row.decided_at,'expires_at',v_row.expires_at);
end;

declare v_id uuid;
begin
  update public.agent_tool_approvals
     set status='consumed', consumed_at=now()
   where id = (
     select id from public.agent_tool_approvals
      where run_id=p_run_id and user_id=p_user_id and tool_key=p_tool_key
        and arguments_hash=p_arguments_hash and status='approved' and expires_at > now()
      order by decided_at desc limit 1 for update skip locked
   )
   returning id into v_id;
  return v_id is not null;
end;

declare
  v_payload jsonb;
  v_request public.admin_mutation_requests;
  v_old_status text;
  v_partner public.partner_organizations;
  v_result jsonb;
begin
  if p_actor_user_id is null or p_partner_id is null
     or p_status not in ('pending','active','suspended','rejected','closed')
     or p_idempotency_key is null or char_length(p_idempotency_key) not between 12 and 128 then
    raise exception 'invalid_partner_status_mutation' using errcode='22023';
  end if;

  if not exists (
    select 1
    from public.user_role_assignments ura
    join public.roles r on r.id=ura.role_id and r.scope='platform'
    join public.role_permissions rp on rp.role_id=r.id
    join public.permissions p on p.id=rp.permission_id and p.key='partner.organization.manage'
    where ura.user_id=p_actor_user_id
      and ura.scope_type='platform'
      and ura.scope_id is null
      and (ura.expires_at is null or ura.expires_at > now())
  ) then
    raise exception 'missing_permission_partner_organization_manage' using errcode='42501';
  end if;

  v_payload := jsonb_build_object('partner_id',p_partner_id,'status',p_status);
  insert into public.admin_mutation_requests(actor_user_id,idempotency_key,action,payload)
  values(p_actor_user_id,p_idempotency_key,'partner.organization.status.update',v_payload)
  on conflict(actor_user_id,idempotency_key) do nothing;

  select * into v_request
  from public.admin_mutation_requests
  where actor_user_id=p_actor_user_id and idempotency_key=p_idempotency_key
  for update;

  if v_request.action <> 'partner.organization.status.update' or v_request.payload <> v_payload then
    raise exception 'idempotency_key_reused_with_different_payload' using errcode='22023';
  end if;
  if v_request.response is not null then
    return v_request.response;
  end if;

  select * into v_partner from public.partner_organizations where id=p_partner_id for update;
  if not found then
    raise exception 'partner_not_found' using errcode='P0002';
  end if;
  v_old_status := v_partner.status;

  update public.partner_organizations
  set status=p_status, updated_at=now()
  where id=p_partner_id
  returning * into v_partner;

  insert into public.admin_audit_logs(
    actor_user_id,action,resource_type,resource_id,scope_type,scope_id,
    correlation_id,outcome,metadata
  ) values (
    p_actor_user_id,'partner.organization.status.update','partner_organization',p_partner_id::text,
    'platform',null,left(p_correlation_id,128),'success',
    jsonb_build_object('previous_status',v_old_status,'new_status',p_status,'idempotency_key',p_idempotency_key)
  );

  v_result := jsonb_build_object(
    'partner_id',v_partner.id,'status',v_partner.status,
    'previous_status',v_old_status,'updated_at',v_partner.updated_at
  );
  update public.admin_mutation_requests set response=v_result
  where id=v_request.id;
  return v_result;
end;

declare
  v_existing public.outbox_events;
  v_sequence bigint;
  v_event_id uuid := gen_random_uuid();
  v_payload jsonb := coalesce(p_payload,'{}'::jsonb);
begin
  if p_run_id is null or p_event_key is null or char_length(p_event_key) not between 1 and 200
     or p_event_type is null or p_event_type !~ '^[a-z][a-z0-9_.-]{0,79}$'
     or jsonb_typeof(v_payload) <> 'object' or octet_length(v_payload::text) > 16384 then
    raise exception 'invalid_run_event' using errcode='22023';
  end if;
  if p_worker_id is null or not exists(
    select 1 from public.agent_runs
    where id=p_run_id and status='running' and lease_owner=p_worker_id and lease_expires_at>now()
  ) then
    raise exception 'worker_lease_not_held' using errcode='42501';
  end if;
  insert into public.agent_run_event_counters(run_id,last_sequence)
  values(p_run_id,coalesce((select max(sequence) from public.agent_run_events where run_id=p_run_id),0))
  on conflict(run_id) do nothing;
  perform 1 from public.agent_run_event_counters where run_id=p_run_id for update;

  select * into v_existing from public.outbox_events
    where aggregate_type='agent_run' and aggregate_id=p_run_id and event_key=p_event_key;
  if found then
    if v_existing.payload->>'event_type' <> p_event_type
       or v_existing.payload->'event_payload' <> v_payload then
      raise exception 'run_event_idempotency_conflict' using errcode='22023';
    end if;
    return jsonb_build_object(
      'event_id',v_existing.id,'sequence',v_existing.run_sequence,'duplicate',true
    );
  end if;

  update public.agent_run_event_counters
    set last_sequence=last_sequence+1,updated_at=now()
    where run_id=p_run_id returning last_sequence into v_sequence;

  insert into public.agent_run_events(id,run_id,event_type,sequence,payload,created_at)
    values(v_event_id,p_run_id,p_event_type,v_sequence,v_payload,now());

  insert into public.outbox_events(
    id,aggregate_type,aggregate_id,event_type,payload,status,attempts,available_at,
    created_at,event_key,run_sequence
  ) values(
    v_event_id,'agent_run',p_run_id,'run.event',
    jsonb_build_object(
      'run_id',p_run_id,'event_id',v_event_id,'sequence',v_sequence,
      'event_type',p_event_type,'event_payload',v_payload,'created_at',now()
    ),
    'pending',0,now(),now(),p_event_key,v_sequence
  );

  return jsonb_build_object('event_id',v_event_id,'sequence',v_sequence,'duplicate',false);
end;

declare v_event jsonb;
begin
  if p_checkpoint_key is null or char_length(p_checkpoint_key) not between 1 and 200
     or jsonb_typeof(p_state) <> 'object' then
    raise exception 'invalid_checkpoint' using errcode='22023';
  end if;
  if not exists(select 1 from public.agent_runs where id=p_run_id and status='running'
      and lease_owner=p_worker_id and lease_expires_at>now()) then
    raise exception 'worker_lease_not_held' using errcode='42501';
  end if;
  insert into public.agent_run_checkpoints(run_id,checkpoint_key,state)
    values(p_run_id,p_checkpoint_key,p_state)
    on conflict(run_id,checkpoint_key) do update
      set state=excluded.state,created_at=now();
  update public.agent_runs set last_checkpoint_key=p_checkpoint_key,updated_at=now()
    where id=p_run_id;
  v_event := public.moreai_worker_append_run_event(
    p_run_id,p_worker_id,'worker.checkpoint:'||p_checkpoint_key,
    'worker.checkpoint',jsonb_build_object('checkpoint_key',p_checkpoint_key)
  );
  return jsonb_build_object(
    'run_id',p_run_id,'checkpoint_key',p_checkpoint_key,
    'sequence',(v_event->>'sequence')::bigint
  );
end;

declare
  r public.agent_runs%rowtype;
  next_status text;
  dead boolean := false;
  event_type text;
  event_key text;
begin
  if p_status not in ('succeeded','failed','cancelled') then
    raise exception 'invalid terminal status';
  end if;
  select * into r from public.agent_runs where id=p_run_id for update;
  if not found then raise exception 'run not found'; end if;
  if r.status in ('succeeded','failed','cancelled') then
    return jsonb_build_object('run_id',r.id,'status',r.status);
  end if;
  if r.lease_owner is distinct from p_worker_id or r.lease_expires_at <= now() then
    raise exception 'worker lease mismatch';
  end if;
  if r.cancel_requested_at is not null then
    next_status := 'cancelled';
  elsif p_status='failed' and r.attempt<r.max_attempts then
    next_status := 'queued';
  elsif p_status='failed' then
    next_status := 'failed'; dead := true;
  else
    next_status := p_status;
  end if;
  event_type := case when dead then 'worker.dead_lettered' else 'worker.'||next_status end;
  event_key := 'worker.finish:'||r.attempt::text||':'||next_status;
  perform public.moreai_worker_append_run_event(
    p_run_id,p_worker_id,event_key,event_type,
    jsonb_build_object('attempt',r.attempt,'error_code',
      case when p_error is null then null else coalesce(p_error->>'code','execution_failed') end)
  );
  if next_status='queued' then
    update public.agent_runs set status=next_status,error=p_error,
      available_at=now()+make_interval(secs=>greatest(1,least(p_retry_delay_seconds,3600))),
      lease_owner=null,lease_expires_at=null,heartbeat_at=null,updated_at=now()
      where id=r.id;
  else
    update public.agent_runs set status=next_status,output=p_output,error=p_error,
      finished_at=now(),dead_lettered_at=case when dead then now() else dead_lettered_at end,
      lease_owner=null,lease_expires_at=null,heartbeat_at=null,updated_at=now()
      where id=r.id;
  end if;
  return jsonb_build_object('run_id',r.id,'status',next_status,'attempt',r.attempt,'dead_lettered',dead);
end;

declare v_count integer;
begin
  update public.outbox_events
    set status='published',published_at=now(),worker_id=null,lease_expires_at=null,last_error=null
    where id=p_event_id and status='processing' and worker_id=p_worker_id
      and lease_expires_at > now();
  get diagnostics v_count=row_count;
  return v_count=1;
end;

declare v_state text;
begin
  update public.outbox_events
    set attempts=attempts+1,
        status=case when attempts+1 >= 12 then 'dead_letter' else 'failed' end,
        available_at=now()+make_interval(secs=>least(3600,power(2,least(attempts,10))::integer)),
        worker_id=null,lease_expires_at=null,last_error=left(coalesce(p_error_code,'publish_failed'),200)
    where id=p_event_id and status='processing' and worker_id=p_worker_id
    returning status into v_state;
  if not found then raise exception 'outbox_lease_lost' using errcode='40001'; end if;
  return v_state;
end;

declare v_state text;
begin
  update public.outbox_events
    set attempts=attempts+1,
        status=case when attempts+1 >= 12 then 'dead_letter' else 'failed' end,
        available_at=now()+make_interval(secs=>least(3600,power(2,least(attempts,10))::integer)),
        worker_id=null,lease_expires_at=null,last_error=left(coalesce(p_error_code,'publish_failed'),200)
    where id=p_event_id and status='processing' and worker_id=p_worker_id
      and lease_expires_at > now();
  if not found then raise exception 'outbox_lease_lost' using errcode='40001'; end if;
  return (select status from public.outbox_events where id=p_event_id);
end;

declare r public.agent_runs%rowtype; a_id uuid; p public.agent_run_approval_pauses%rowtype; v_key text; v_state jsonb;
begin
 select * into r from public.agent_runs where id=p_run_id for update;
 if not found or r.user_id is distinct from p_user_id then raise exception 'approval_run_owner_mismatch' using errcode='42501'; end if;
 if r.status<>'running' or r.lease_owner is distinct from p_worker_id or r.lease_expires_at<=now() then raise exception 'worker_lease_not_held' using errcode='42501'; end if;
 select * into p from public.agent_run_approval_pauses where run_id=p_run_id and tool_key=p_tool_key and arguments_hash=p_arguments_hash for update;
 if found then
  if p.status in ('approved','denied','expired','consumed') then return jsonb_build_object('approval_id',p.approval_id,'status',p.status,'resumed',true); end if;
  if p.status='pending' then raise exception 'approval_already_pending' using errcode='55000'; end if;
 end if;
 a_id:=public.moreai_request_tool_approval(p_run_id,p_user_id,p_tool_key,p_arguments_hash,p_summary,p_expires_in_seconds);
 v_key:='approval.pause.'||a_id::text;
 insert into public.agent_run_approval_pauses(run_id,approval_id,user_id,tool_key,arguments_hash,status,checkpoint_key)
 values(p_run_id,a_id,p_user_id,p_tool_key,p_arguments_hash,'pending',v_key)
 on conflict(run_id,tool_key,arguments_hash) do update set approval_id=excluded.approval_id,status='pending',checkpoint_key=excluded.checkpoint_key,created_at=now(),decided_at=null,resumed_at=null returning * into p;
 v_state:=jsonb_build_object('approval_id',a_id,'tool_key',p_tool_key,'arguments_hash',p_arguments_hash,'status','pending','attempt',r.attempt,'checkpoint_key',v_key);
 insert into public.agent_run_checkpoints(run_id,checkpoint_key,state) values(p_run_id,v_key,v_state)
 on conflict(run_id,checkpoint_key) do update set state=excluded.state,created_at=now();
 update public.agent_runs set status='waiting_approval',last_checkpoint_key=v_key,lease_owner=null,lease_expires_at=null,heartbeat_at=null,updated_at=now()
 where id=p_run_id and status='running' and lease_owner=p_worker_id;
 return jsonb_build_object('approval_id',a_id,'status','pending','checkpoint_key',v_key);
end;

declare a public.agent_tool_approvals%rowtype; p public.agent_run_approval_pauses%rowtype; v_status text; v_run_status text;
begin
 if p_decision not in ('approved','denied') then raise exception 'invalid_approval_decision' using errcode='22023'; end if;
 select * into a from public.agent_tool_approvals where id=p_approval_id and user_id=p_user_id for update;
 if not found then raise exception 'approval_not_found' using errcode='P0002'; end if;
 select * into p from public.agent_run_approval_pauses where approval_id=p_approval_id for update;
 if not found then
  if a.status in ('approved','denied','expired','consumed') then return jsonb_build_object('id',a.id,'run_id',a.run_id,'status',a.status,'resumed',false); end if;
  update public.agent_tool_approvals set status=case when expires_at<=now() then 'expired' else p_decision end,decided_at=now(),decided_by=p_user_id where id=p_approval_id returning * into a;
  return jsonb_build_object('id',a.id,'run_id',a.run_id,'status',a.status,'resumed',false);
 end if;
 if a.status='pending' then
  v_status:=case when a.expires_at<=now() then 'expired' else p_decision end;
  update public.agent_tool_approvals set status=v_status,decided_at=now(),decided_by=p_user_id where id=a.id returning * into a;
  update public.agent_run_approval_pauses set status=v_status,decided_at=now() where id=p.id returning * into p;
 else
  v_status:=a.status;
  if p.status<>v_status then raise exception 'approval_pause_state_conflict' using errcode='40001'; end if;
 end if;
 update public.agent_runs set status='queued',resume_pending=true,available_at=now(),updated_at=now()
 where id=p.run_id and status='waiting_approval' returning status into v_run_status;
 update public.agent_run_checkpoints set state=state||jsonb_build_object('status',v_status,'decided_at',a.decided_at,'resume_pending',true),created_at=now()
 where run_id=p.run_id and checkpoint_key=p.checkpoint_key;
 return jsonb_build_object('id',a.id,'run_id',a.run_id,'status',v_status,'resumed',coalesce(v_run_status='queued',false));
end;

declare r public.agent_runs%rowtype; seq bigint; d record; v_was_resume boolean;
begin
 if p_worker_id is null or length(p_worker_id)<8 or length(p_worker_id)>128 or p_lease_seconds not between 15 and 900 then raise exception 'invalid worker claim'; end if;
 for d in select p.id,p.run_id,p.approval_id,p.checkpoint_key from public.agent_run_approval_pauses p join public.agent_tool_approvals a on a.id=p.approval_id
  where p.status='pending' and a.expires_at<=now() for update of p,a skip locked
 loop
  update public.agent_tool_approvals set status='expired',decided_at=now() where id=d.approval_id and status='pending';
  update public.agent_run_approval_pauses set status='expired',decided_at=now() where id=d.id and status='pending';
  update public.agent_runs set status=case when cancel_requested_at is not null then 'cancelled' else 'queued' end,
   resume_pending=(cancel_requested_at is null),finished_at=case when cancel_requested_at is not null then now() else finished_at end,available_at=now(),updated_at=now()
   where id=d.run_id and status='waiting_approval';
  update public.agent_run_checkpoints set state=state||jsonb_build_object('status','expired','resume_pending',true),created_at=now()
   where run_id=d.run_id and checkpoint_key=d.checkpoint_key;
 end loop;
 for d in update public.agent_runs set status='failed',finished_at=now(),dead_lettered_at=now(),lease_owner=null,lease_expires_at=null,updated_at=now()
  where status='running' and lease_expires_at<now() and attempt>=max_attempts returning id
 loop
  select coalesce(max(sequence),0)+1 into seq from public.agent_run_events where run_id=d.id;
  insert into public.agent_run_events(run_id,event_type,sequence,payload) values(d.id,'worker.dead_lettered',seq,'{"reason":"lease_expired_max_attempts"}'::jsonb);
 end loop;
 select * into r from public.agent_runs where ((status='queued' and available_at<=now()) or (status='running' and lease_expires_at<now()))
  and attempt<max_attempts and cancel_requested_at is null
  and not exists(select 1 from public.agent_run_approval_pauses p where p.run_id=agent_runs.id and p.status='pending')
  order by available_at,created_at for update skip locked limit 1;
 if not found then return null; end if;
 v_was_resume:=r.resume_pending;
 update public.agent_runs set status='running',attempt=attempt+case when resume_pending then 0 else 1 end,resume_pending=false,
  lease_owner=p_worker_id,lease_expires_at=now()+make_interval(secs=>p_lease_seconds),heartbeat_at=now(),
  started_at=coalesce(started_at,now()),updated_at=now() where id=r.id returning * into r;
 update public.agent_run_approval_pauses set resumed_at=coalesce(resumed_at,now()) where run_id=r.id and status in ('approved','denied','expired');
 select coalesce(max(sequence),0)+1 into seq from public.agent_run_events where run_id=r.id;
 insert into public.agent_run_events(run_id,event_type,sequence,payload) values(r.id,'worker.claimed',seq,
  jsonb_build_object('worker_id',p_worker_id,'attempt',r.attempt,'lease_seconds',p_lease_seconds,'approval_resume',v_was_resume));
 return jsonb_build_object('id',r.id,'user_id',r.user_id,'workspace_id',r.workspace_id,'conversation_id',r.conversation_id,
  'agent_definition_id',r.agent_definition_id,'status',r.status,'attempt',r.attempt,'max_attempts',r.max_attempts,
  'input',r.input,'lease_owner',r.lease_owner,'lease_expires_at',r.lease_expires_at);
end;

declare r public.agent_runs%rowtype; f public.agent_workspace_files%rowtype; v_token uuid; v_version bigint;
begin
 if p_path is null or length(p_path) not between 1 and 512 or p_expected_version<0 then raise exception 'workspace_write_arguments_invalid' using errcode='22023'; end if;
 select * into r from public.agent_runs where id=p_run_id for update;
 if not found or r.user_id<>p_user_id or r.workspace_id is distinct from p_workspace_id
  or r.status<>'running' or r.lease_owner is distinct from p_worker_id or r.lease_expires_at<=now()
 then raise exception 'workspace_run_scope_or_lease_invalid' using errcode='42501'; end if;
 if not exists(select 1 from public.workspaces w where w.id=p_workspace_id and w.status='active'
  and (w.owner_user_id=p_user_id or exists(select 1 from public.workspace_members m where m.workspace_id=w.id and m.user_id=p_user_id and m.status='active')))
 then raise exception 'workspace_membership_required' using errcode='42501'; end if;
 select * into f from public.agent_workspace_files where workspace_id=p_workspace_id and path=p_path for update;
 if not found then
  if p_expected_version<>0 then raise exception 'workspace_version_conflict' using errcode='40001'; end if;
  insert into public.agent_workspace_files(workspace_id,user_id,path) values(p_workspace_id,p_user_id,p_path) returning * into f;
 end if;
 if f.version<>p_expected_version then raise exception 'workspace_version_conflict' using errcode='40001'; end if;
 if f.pending_token is not null then raise exception 'workspace_write_in_progress' using errcode='40001'; end if;
 v_token:=gen_random_uuid(); v_version:=f.version+1;
 update public.agent_workspace_files set pending_version=v_version,pending_token=v_token,pending_run_id=p_run_id,updated_at=now()
 where id=f.id returning * into f;
 return jsonb_build_object('version',v_version,'token',v_token,'current_version',f.version,'storage_path',
  p_user_id::text||'/workspaces/'||p_workspace_id::text||'/versions/'||v_version::text||'/'||p_path);
end;

