declare
  v_workspace public.workspaces%rowtype;
  v_file public.agent_workspace_files%rowtype;
  v_intent public.customer_workspace_upload_idempotency%rowtype;
  v_next_version bigint;
  v_expected_storage_path text;
  v_result jsonb;
begin
  if p_user_id is null or p_workspace_id is null
     or p_path is null or length(p_path) not between 1 and 512
     or p_expected_version is null or p_expected_version < 0
     or p_idempotency_key is null or length(p_idempotency_key) not between 12 and 128
     or p_sha256 is null or p_sha256 !~ '^[0-9a-f]{64}$'
     or p_size_bytes is null or p_size_bytes not between 1 and 2000000 then
    raise exception 'workspace_upload_arguments_invalid' using errcode = '22023';
  end if;

  select * into v_workspace
    from public.workspaces
   where id = p_workspace_id and status = 'active'
     and (owner_user_id = p_user_id or exists (
       select 1 from public.workspace_members m
        where m.workspace_id = p_workspace_id
          and m.user_id = p_user_id and m.status = 'active'
     ));
  if not found then
    raise exception 'workspace_membership_required' using errcode = '42501';
  end if;

  v_next_version := p_expected_version + 1;
  v_expected_storage_path := p_user_id::text || '/workspaces/' ||
    p_workspace_id::text || '/versions/' || v_next_version::text || '/' || p_path;
  if p_storage_path is distinct from v_expected_storage_path then
    raise exception 'workspace_upload_storage_path_invalid' using errcode = '22023';
  end if;

  insert into public.customer_workspace_upload_idempotency (
    user_id, idempotency_key, workspace_id, path, expected_version,
    storage_path, sha256, size_bytes
  ) values (
    p_user_id, p_idempotency_key, p_workspace_id, p_path, p_expected_version,
    p_storage_path, p_sha256, p_size_bytes
  ) on conflict (user_id, idempotency_key) do nothing;

  select * into v_intent
    from public.customer_workspace_upload_idempotency
   where user_id = p_user_id and idempotency_key = p_idempotency_key
   for update;

  if v_intent.workspace_id <> p_workspace_id
     or v_intent.path <> p_path
     or v_intent.expected_version <> p_expected_version
     or v_intent.storage_path <> p_storage_path
     or v_intent.sha256 <> p_sha256
     or v_intent.size_bytes <> p_size_bytes then
    raise exception 'workspace_upload_idempotency_key_reused' using errcode = '22023';
  end if;

  if v_intent.committed_at is not null then
    return coalesce(v_intent.result, '{}'::jsonb) || jsonb_build_object('replayed', true);
  end if;

  insert into public.agent_workspace_files (workspace_id, user_id, path, version)
  values (p_workspace_id, p_user_id, p_path, 0)
  on conflict (workspace_id, path) do nothing;

  update public.agent_workspace_files
     set version = v_next_version,
         storage_path = p_storage_path,
         sha256 = p_sha256,
         size_bytes = p_size_bytes,
         updated_at = now()
   where workspace_id = p_workspace_id
     and path = p_path
     and version = p_expected_version
     and pending_token is null
     and pending_version is null
     and pending_run_id is null
     and deleted_at is null
  returning * into v_file;

  if not found then
    raise exception 'workspace_version_conflict_or_write_in_progress' using errcode = '40001';
  end if;

  v_result := jsonb_build_object(
    'workspace_id', p_workspace_id,
    'file_id', v_file.id,
    'path', v_file.path,
    'version', v_file.version,
    'storage_path', v_file.storage_path,
    'sha256', v_file.sha256,
    'size_bytes', v_file.size_bytes,
    'updated_at', v_file.updated_at,
    'replayed', false
  );

  update public.customer_workspace_upload_idempotency
     set result = v_result, committed_at = now()
   where user_id = p_user_id and idempotency_key = p_idempotency_key;

  return v_result;
end;

declare
    v_conversation public.conversations%rowtype;
    v_message public.conversation_messages%rowtype;
    v_run public.agent_runs%rowtype;
begin
    if p_user_id is null
       or p_conversation_id is null
       or p_content is null
       or length(btrim(p_content)) = 0
       or length(p_content) > 100000
       or p_agent_key is null
       or p_idempotency_key is null
       or length(p_idempotency_key) < 12
       or length(p_idempotency_key) > 128
       or p_agent_key not in ('manus', 'planning', 'toolcall') then
        raise exception 'invalid chat enqueue request' using errcode = '22023';
    end if;

    select *
      into v_conversation
      from public.conversations
     where id = p_conversation_id
       and user_id = p_user_id
     for update;

    if not found then
        raise exception 'conversation not found' using errcode = '42501';
    end if;

    select *
      into v_run
      from public.agent_runs
     where user_id = p_user_id
       and idempotency_key = p_idempotency_key;

    if found then
        return pg_catalog.jsonb_build_object(
            'run', pg_catalog.to_jsonb(v_run),
            'message', null,
            'replayed', true
        );
    end if;

    insert into public.conversation_messages (
        conversation_id, user_id, role, content, metadata
    ) values (
        p_conversation_id, p_user_id, 'user', p_content, '{}'::jsonb
    )
    returning * into v_message;

    insert into public.agent_runs (
        user_id, workspace_id, conversation_id, status,
        idempotency_key, input, max_attempts
    ) values (
        p_user_id,
        v_conversation.workspace_id,
        p_conversation_id,
        'queued',
        p_idempotency_key,
        pg_catalog.jsonb_build_object(
            'prompt', p_content,
            'agent_key', p_agent_key,
            'conversation_id', p_conversation_id,
            'message_id', v_message.id
        ),
        3
    )
    returning * into v_run;

    update public.conversation_messages
       set run_id = v_run.id
     where id = v_message.id
       and user_id = p_user_id;
    v_message.run_id := v_run.id;

    return pg_catalog.jsonb_build_object(
        'run', pg_catalog.to_jsonb(v_run),
        'message', pg_catalog.to_jsonb(v_message),
        'replayed', false
    );
end;

declare
  r public.agent_runs%rowtype;
  f public.agent_workspace_files%rowtype;
  item jsonb;
  v_path text;
  v_storage_path text;
  v_expected bigint;
  v_next bigint;
  v_size bigint;
  v_sha text;
  v_saved jsonb := '[]'::jsonb;
  v_deleted jsonb := '[]'::jsonb;
  v_result jsonb;
  v_count integer;
  v_distinct integer;
begin
  if p_run_id is null or p_user_id is null or p_workspace_id is null
     or p_worker_id is null or length(p_worker_id) not between 8 and 128
     or p_bucket is null or length(p_bucket) not between 1 and 100
     or p_operation_key is null or p_operation_key !~ '^[0-9a-f]{64}$'
     or p_changes is null or jsonb_typeof(p_changes) is distinct from 'array'
     or p_deletes is null or jsonb_typeof(p_deletes) is distinct from 'array'
     or jsonb_array_length(p_changes) > 200
     or jsonb_array_length(p_deletes) > 200
     or jsonb_array_length(p_changes) + jsonb_array_length(p_deletes) > 200 then
    raise exception 'workspace_execution_commit_arguments_invalid' using errcode='22023';
  end if;

  select * into r from public.agent_runs where id=p_run_id for update;
  if not found or r.user_id<>p_user_id or r.workspace_id is distinct from p_workspace_id then
    raise exception 'workspace_run_scope_invalid' using errcode='42501';
  end if;

  -- A retry after a lost HTTP response returns the already committed result.
  select result into v_result
    from public.agent_workspace_execution_commits
    where run_id=p_run_id and operation_key=p_operation_key
      and user_id=p_user_id and workspace_id=p_workspace_id;
  if found then
    return v_result;
  end if;

  if r.status<>'running' or r.lease_owner is distinct from p_worker_id
     or r.lease_expires_at is null or r.lease_expires_at<=now() then
    raise exception 'workspace_run_scope_or_lease_invalid' using errcode='42501';
  end if;
  if not exists (
    select 1 from public.workspaces w
    where w.id=p_workspace_id and w.status='active'
      and (w.owner_user_id=p_user_id or exists (
        select 1 from public.workspace_members m
        where m.workspace_id=w.id and m.user_id=p_user_id and m.status='active'
      ))
  ) then
    raise exception 'workspace_membership_required' using errcode='42501';
  end if;
  if not exists(select 1 from storage.buckets b where b.id=p_bucket and b.public=false) then
    raise exception 'workspace_bucket_must_be_private' using errcode='42501';
  end if;

  select count(*), count(distinct x.path)
    into v_count, v_distinct
    from (
      select value->>'path' as path from jsonb_array_elements(p_changes)
      union all
      select value->>'path' as path from jsonb_array_elements(p_deletes)
    ) x;
  if v_count <> v_distinct then
    raise exception 'workspace_execution_duplicate_path' using errcode='22023';
  end if;

  -- Deterministic path ordering reduces lock-order inversions between runs.
  for item in
    select value from jsonb_array_elements(p_changes)
    order by value->>'path'
  loop
    v_path := item->>'path';
    if v_path is null or length(v_path) not between 1 and 512
       or position(chr(92) in v_path)>0
       or v_path ~ '(^/|//|(^|/)\.\.?(/|$))'
       or v_path !~ '^[A-Za-z0-9._ -]+(/[A-Za-z0-9._ -]+)*$'
       or coalesce(item->>'expected_version','') !~ '^(0|[1-9][0-9]{0,18})$'
       or coalesce(item->>'size_bytes','') !~ '^(0|[1-9][0-9]{0,6})$'
       or coalesce(item->>'sha256','') !~ '^[0-9a-f]{64}$' then
      raise exception 'workspace_execution_change_invalid' using errcode='22023';
    end if;
    v_expected := (item->>'expected_version')::bigint;
    v_size := (item->>'size_bytes')::bigint;
    v_sha := item->>'sha256';
    if v_expected >= 9223372036854775807 or v_size > 2000000 then
      raise exception 'workspace_execution_change_limit_exceeded' using errcode='22023';
    end if;
    v_next := v_expected + 1;
    v_storage_path := p_user_id::text||'/workspaces/'||p_workspace_id::text
      ||'/versions/'||v_next::text||'/'||v_path;
    if item->>'storage_path' is distinct from v_storage_path then
      raise exception 'workspace_execution_storage_path_invalid' using errcode='22023';
    end if;
    if not exists(select 1 from storage.objects o where o.bucket_id=p_bucket and o.name=v_storage_path) then
      raise exception 'workspace_execution_object_missing' using errcode='P0002';
    end if;

    select * into f from public.agent_workspace_files
      where workspace_id=p_workspace_id and path=v_path for update;
    if not found then
      if v_expected<>0 then
        raise exception 'workspace_version_conflict' using errcode='40001';
      end if;
      insert into public.agent_workspace_files(
        workspace_id,user_id,path,version,storage_path,sha256,size_bytes,updated_at
      ) values (
        p_workspace_id,p_user_id,v_path,1,v_storage_path,v_sha,v_size,now()
      );
    else
      if f.user_id<>p_user_id or f.deleted_at is not null then
        raise exception 'workspace_execution_path_not_active' using errcode='40001';
      end if;
      if f.version<>v_expected or f.pending_token is not null then
        raise exception 'workspace_version_conflict' using errcode='40001';
      end if;
      update public.agent_workspace_files
        set version=v_next,storage_path=v_storage_path,sha256=v_sha,
            size_bytes=v_size,updated_at=now()
        where id=f.id and version=v_expected and pending_token is null;
      if not found then
        raise exception 'workspace_execution_write_fence_lost' using errcode='40001';
      end if;
    end if;
    v_saved := v_saved || jsonb_build_array(jsonb_build_object(
      'path',v_path,'version',v_next,'sha256',v_sha,'size_bytes',v_size
    ));
  end loop;

  for item in
    select value from jsonb_array_elements(p_deletes)
    order by value->>'path'
  loop
    v_path := item->>'path';
    if v_path is null or length(v_path) not between 1 and 512
       or position(chr(92) in v_path)>0
       or v_path ~ '(^/|//|(^|/)\.\.?(/|$))'
       or v_path !~ '^[A-Za-z0-9._ -]+(/[A-Za-z0-9._ -]+)*$'
       or coalesce(item->>'expected_version','') !~ '^[1-9][0-9]{0,18}$' then
      raise exception 'workspace_execution_delete_invalid' using errcode='22023';
    end if;
    v_expected := (item->>'expected_version')::bigint;
    select * into f from public.agent_workspace_files
      where workspace_id=p_workspace_id and path=v_path for update;
    if not found or f.user_id<>p_user_id or f.deleted_at is not null
       or f.version<>v_expected or f.pending_token is not null
       or f.storage_path is null or f.sha256 is null or f.size_bytes is null then
      raise exception 'workspace_execution_delete_conflict' using errcode='40001';
    end if;
    insert into public.agent_workspace_file_versions(
      workspace_id,user_id,path,version,storage_path,sha256,size_bytes,committed_at
    ) values (
      f.workspace_id,f.user_id,f.path,f.version,f.storage_path,f.sha256,f.size_bytes,f.updated_at
    ) on conflict(workspace_id,path,version) do nothing;
    update public.agent_workspace_files
      set deleted_at=now(),updated_at=now()
      where id=f.id and version=v_expected and deleted_at is null and pending_token is null;
    if not found then
      raise exception 'workspace_execution_delete_fence_lost' using errcode='40001';
    end if;
    v_deleted := v_deleted || jsonb_build_array(jsonb_build_object(
      'path',v_path,'version',v_expected,'deleted',true
    ));
  end loop;

  v_result := jsonb_build_object(
    'saved',v_saved,'deleted',v_deleted,
    'saved_count',jsonb_array_length(v_saved),
    'deleted_count',jsonb_array_length(v_deleted),
    'atomic',true
  );
  insert into public.agent_workspace_execution_commits(
    run_id,operation_key,user_id,workspace_id,result
  ) values (p_run_id,p_operation_key,p_user_id,p_workspace_id,v_result);
  return v_result;
end;

declare
  v_conversation public.conversations%rowtype;
  v_message public.conversation_messages%rowtype;
  v_run public.agent_runs%rowtype;
  v_attachment_ids uuid[];
  v_attachment_count integer;
begin
  if p_user_id is null or p_conversation_id is null
     or p_content is null or length(btrim(p_content)) = 0 or length(p_content) > 100000
     or p_agent_key is null or p_agent_key not in ('manus','planning','toolcall')
     or p_idempotency_key is null or length(p_idempotency_key) not between 12 and 128
     or coalesce(cardinality(p_attachment_ids),0) > 10 then
    raise exception 'invalid_chat_enqueue_request' using errcode = '22023';
  end if;

  select coalesce(array_agg(x order by x), '{}'::uuid[])
    into v_attachment_ids
    from (select distinct unnest(coalesce(p_attachment_ids, '{}'::uuid[])) as x) q;
  if cardinality(v_attachment_ids) <> coalesce(cardinality(p_attachment_ids),0) then
    raise exception 'duplicate_chat_attachment_id' using errcode = '22023';
  end if;

  select * into v_conversation
    from public.conversations
   where id = p_conversation_id and user_id = p_user_id and status = 'active'
   for update;
  if not found then
    raise exception 'conversation_not_found_or_inactive' using errcode = '42501';
  end if;

  if cardinality(v_attachment_ids) > 0 then
    select count(*) into v_attachment_count
      from public.artifacts a
     where a.id = any(v_attachment_ids)
       and a.user_id = p_user_id
       and a.metadata->>'purpose' = 'chat_attachment'
       and a.metadata->>'conversation_id' = p_conversation_id::text
       and a.size_bytes between 1 and 2000000
       and a.mime_type in (
         'text/plain','text/markdown','text/csv','application/json',
         'application/pdf','image/jpeg','image/png','image/webp'
       );
    if v_attachment_count <> cardinality(v_attachment_ids) then
      raise exception 'chat_attachment_not_owned_or_not_available' using errcode = '42501';
    end if;
  end if;

  select * into v_run
    from public.agent_runs
   where user_id = p_user_id and idempotency_key = p_idempotency_key;
  if found then
    if v_run.input->>'prompt' is distinct from p_content
       or v_run.input->>'agent_key' is distinct from p_agent_key
       or coalesce(v_run.input->'attachment_ids','[]'::jsonb) is distinct from to_jsonb(v_attachment_ids) then
      raise exception 'chat_idempotency_key_payload_conflict' using errcode = '22023';
    end if;
    return pg_catalog.jsonb_build_object('run',pg_catalog.to_jsonb(v_run),'message',null,'replayed',true);
  end if;

  insert into public.conversation_messages (conversation_id,user_id,role,content,metadata)
  values (p_conversation_id,p_user_id,'user',p_content,'{}'::jsonb)
  returning * into v_message;

  insert into public.agent_runs (
    user_id,workspace_id,conversation_id,status,idempotency_key,input,max_attempts
  ) values (
    p_user_id,v_conversation.workspace_id,p_conversation_id,'queued',p_idempotency_key,
    pg_catalog.jsonb_build_object(
      'prompt',p_content,'agent_key',p_agent_key,'conversation_id',p_conversation_id,
      'message_id',v_message.id,'attachment_ids',to_jsonb(v_attachment_ids)
    ),3
  ) returning * into v_run;

  update public.conversation_messages
     set run_id = v_run.id
   where id = v_message.id and user_id = p_user_id;
  v_message.run_id := v_run.id;

  if cardinality(v_attachment_ids) > 0 then
    insert into public.conversation_message_attachments (
      user_id,conversation_id,message_id,run_id,artifact_id
    )
    select p_user_id,p_conversation_id,v_message.id,v_run.id,x
      from unnest(v_attachment_ids) as x;
  end if;

  return pg_catalog.jsonb_build_object('run',pg_catalog.to_jsonb(v_run),'message',pg_catalog.to_jsonb(v_message),'replayed',false);
end;

declare
  v_file public.agent_workspace_files%rowtype;
begin
  if p_user_id is null or p_workspace_id is null or p_file_id is null
     or p_expected_version is null or p_expected_version < 0 then
    raise exception 'workspace_file_delete_arguments_invalid' using errcode = '22023';
  end if;

  if not exists (
    select 1 from public.workspaces w
    where w.id = p_workspace_id and w.status = 'active'
      and (w.owner_user_id = p_user_id or exists (
        select 1 from public.workspace_members m
        where m.workspace_id = w.id and m.user_id = p_user_id and m.status = 'active'
      ))
  ) then
    raise exception 'workspace_membership_required' using errcode = '42501';
  end if;

  select * into v_file
  from public.agent_workspace_files
  where id = p_file_id and workspace_id = p_workspace_id
  for update;

  if not found then
    raise exception 'workspace_file_not_found' using errcode = 'P0002';
  end if;
  if v_file.version <> p_expected_version then
    raise exception 'workspace_version_conflict' using errcode = '40001';
  end if;
  if v_file.pending_token is not null then
    raise exception 'workspace_write_in_progress' using errcode = '40001';
  end if;
  if v_file.deleted_at is null then
    update public.agent_workspace_files
       set deleted_at = now(), updated_at = now()
     where id = p_file_id and workspace_id = p_workspace_id
       and version = p_expected_version and pending_token is null
     returning * into v_file;
    if not found then
      raise exception 'workspace_file_delete_fence_lost' using errcode = '40001';
    end if;
  end if;

  return jsonb_build_object(
    'id', v_file.id, 'workspace_id', v_file.workspace_id,
    'path', v_file.path, 'version', v_file.version,
    'deleted_at', v_file.deleted_at, 'status', 'deleted'
  );
end;

declare
  v_file public.agent_workspace_files%rowtype;
begin
  if p_user_id is null or p_workspace_id is null or p_file_id is null
     or p_expected_version is null or p_expected_version < 1 then
    raise exception 'workspace_file_restore_arguments_invalid' using errcode = '22023';
  end if;

  if not exists (
    select 1 from public.workspaces w
    where w.id = p_workspace_id and w.status = 'active'
      and (w.owner_user_id = p_user_id or exists (
        select 1 from public.workspace_members m
        where m.workspace_id = w.id and m.user_id = p_user_id and m.status = 'active'
      ))
  ) then
    raise exception 'workspace_membership_required' using errcode = '42501';
  end if;

  select * into v_file
  from public.agent_workspace_files
  where id = p_file_id and workspace_id = p_workspace_id
  for update;

  if not found then
    raise exception 'workspace_file_not_found' using errcode = 'P0002';
  end if;
  if v_file.version <> p_expected_version then
    raise exception 'workspace_version_conflict' using errcode = '40001';
  end if;
  if v_file.deleted_at is null then
    raise exception 'workspace_file_not_deleted' using errcode = '22023';
  end if;
  if v_file.pending_token is not null or v_file.storage_path is null
     or v_file.sha256 is null or v_file.size_bytes is null then
    raise exception 'workspace_file_not_committed_or_write_in_progress' using errcode = '40001';
  end if;

  update public.agent_workspace_files
     set deleted_at = null, version = version + 1, updated_at = now()
   where id = p_file_id and workspace_id = p_workspace_id
     and version = p_expected_version and deleted_at is not null
     and pending_token is null
   returning * into v_file;

  if not found then
    raise exception 'workspace_file_restore_fence_lost' using errcode = '40001';
  end if;

  return jsonb_build_object(
    'id', v_file.id, 'workspace_id', v_file.workspace_id,
    'path', v_file.path, 'version', v_file.version,
    'deleted_at', v_file.deleted_at, 'status', 'restored'
  );
end;

declare
  v_file public.agent_workspace_files%rowtype;
  v_expected_storage_path text;
begin
  if p_user_id is null or p_workspace_id is null or p_file_id is null
     or p_expected_version is null or p_expected_version < 1
     or p_sha256 is null or p_sha256 !~ '^[0-9a-f]{64}$'
     or p_size_bytes is null or p_size_bytes not between 1 and 2000000
     or p_bucket is null or length(p_bucket) not between 1 and 100 then
    raise exception 'workspace_file_restore_arguments_invalid' using errcode = '22023';
  end if;

  if not exists (
    select 1 from public.workspaces w
    where w.id = p_workspace_id and w.status = 'active'
      and (w.owner_user_id = p_user_id or exists (
        select 1 from public.workspace_members m
        where m.workspace_id = w.id and m.user_id = p_user_id and m.status = 'active'
      ))
  ) then
    raise exception 'workspace_membership_required' using errcode = '42501';
  end if;

  select * into v_file
  from public.agent_workspace_files
  where id = p_file_id and workspace_id = p_workspace_id
  for update;

  if not found then
    raise exception 'workspace_file_not_found' using errcode = 'P0002';
  end if;
  if v_file.version <> p_expected_version then
    raise exception 'workspace_version_conflict' using errcode = '40001';
  end if;
  if v_file.deleted_at is null then
    raise exception 'workspace_file_not_deleted' using errcode = '22023';
  end if;
  if v_file.pending_token is not null or v_file.storage_path is null
     or v_file.sha256 is null or v_file.size_bytes is null then
    raise exception 'workspace_file_not_committed_or_write_in_progress' using errcode = '40001';
  end if;
  if p_sha256 is distinct from v_file.sha256 or p_size_bytes is distinct from v_file.size_bytes then
    raise exception 'workspace_restore_integrity_mismatch' using errcode = '22000';
  end if;

  v_expected_storage_path := v_file.user_id::text || '/workspaces/' ||
    p_workspace_id::text || '/versions/' || (p_expected_version + 1)::text || '/' || v_file.path;
  if p_storage_path is distinct from v_expected_storage_path then
    raise exception 'workspace_restore_storage_path_invalid' using errcode = '22023';
  end if;
  if not exists (select 1 from storage.buckets b where b.id = p_bucket and b.public = false)
     or not exists (select 1 from storage.objects o where o.bucket_id = p_bucket and o.name = p_storage_path) then
    raise exception 'workspace_restore_object_missing_or_bucket_not_private' using errcode = 'P0002';
  end if;

  update public.agent_workspace_files
     set deleted_at = null,
         version = version + 1,
         storage_path = p_storage_path,
         sha256 = p_sha256,
         size_bytes = p_size_bytes,
         updated_at = now()
   where id = p_file_id and workspace_id = p_workspace_id
     and version = p_expected_version and deleted_at is not null
     and pending_token is null
   returning * into v_file;

  if not found then
    raise exception 'workspace_file_restore_fence_lost' using errcode = '40001';
  end if;

  return jsonb_build_object(
    'id', v_file.id, 'workspace_id', v_file.workspace_id,
    'path', v_file.path, 'version', v_file.version,
    'deleted_at', v_file.deleted_at, 'status', 'restored',
    'storage_path', v_file.storage_path, 'sha256', v_file.sha256,
    'size_bytes', v_file.size_bytes
  );
end;

declare
  v_file public.agent_workspace_files%rowtype;
begin
  if p_user_id is null or p_workspace_id is null or p_file_id is null
     or p_expected_version is null or p_expected_version < 0 then
    raise exception 'workspace_file_delete_arguments_invalid' using errcode = '22023';
  end if;
  if not exists (
    select 1 from public.workspaces w where w.id = p_workspace_id and w.status = 'active'
      and (w.owner_user_id = p_user_id or exists (
        select 1 from public.workspace_members m where m.workspace_id = w.id
          and m.user_id = p_user_id and m.status = 'active'
      ))
  ) then raise exception 'workspace_membership_required' using errcode = '42501'; end if;

  select * into v_file from public.agent_workspace_files
    where id = p_file_id and workspace_id = p_workspace_id for update;
  if not found then raise exception 'workspace_file_not_found' using errcode = 'P0002'; end if;
  if v_file.version <> p_expected_version then raise exception 'workspace_version_conflict' using errcode = '40001'; end if;
  if v_file.pending_token is not null then raise exception 'workspace_write_in_progress' using errcode = '40001'; end if;

  if v_file.deleted_at is null then
    if v_file.version > 0 and v_file.storage_path is not null
       and v_file.sha256 is not null and v_file.size_bytes is not null then
      insert into public.agent_workspace_file_versions(
        workspace_id,user_id,path,version,storage_path,sha256,size_bytes,committed_at
      ) values (
        v_file.workspace_id,v_file.user_id,v_file.path,v_file.version,
        v_file.storage_path,v_file.sha256,v_file.size_bytes,v_file.updated_at
      ) on conflict (workspace_id,path,version) do nothing;
    end if;
    update public.agent_workspace_files set deleted_at = now(), updated_at = now()
      where id = p_file_id and workspace_id = p_workspace_id
        and version = p_expected_version and pending_token is null
      returning * into v_file;
    if not found then raise exception 'workspace_file_delete_fence_lost' using errcode = '40001'; end if;
  end if;

  return jsonb_build_object('id',v_file.id,'workspace_id',v_file.workspace_id,'path',v_file.path,
    'version',v_file.version,'deleted_at',v_file.deleted_at,'status','deleted');
end;

declare
  r public.agent_runs%rowtype;
  f public.agent_workspace_files%rowtype;
  v_expected_storage_path text;
begin
  if p_run_id is null or p_worker_id is null or length(p_worker_id) not between 8 and 128
     or p_user_id is null or p_workspace_id is null
     or p_path is null or length(p_path) not between 1 and 512
     or position(chr(92) in p_path) > 0
     or p_path ~ '(^/|//|(^|/)\.\.?(/|$))'
     or p_path !~ '^[A-Za-z0-9._ -]+(/[A-Za-z0-9._ -]+)*$'
     or p_expected_version is null or p_expected_version < 1
     or p_sha256 is null or p_sha256 !~ '^[0-9a-f]{64}$'
     or p_size_bytes is null or p_size_bytes not between 0 and 2000000
     or p_bucket is null or length(p_bucket) not between 1 and 100 then
    raise exception 'workspace_restore_deleted_arguments_invalid' using errcode = '22023';
  end if;

  select * into r from public.agent_runs where id = p_run_id for update;
  if not found or r.user_id <> p_user_id or r.workspace_id is distinct from p_workspace_id
     or r.status <> 'running' or r.lease_owner is distinct from p_worker_id
     or r.lease_expires_at is null or r.lease_expires_at <= now() then
    raise exception 'workspace_run_scope_or_lease_invalid' using errcode = '42501';
  end if;

  if not exists (
    select 1 from public.workspaces w where w.id = p_workspace_id and w.status = 'active'
      and (w.owner_user_id = p_user_id or exists (
        select 1 from public.workspace_members m where m.workspace_id = w.id
          and m.user_id = p_user_id and m.status = 'active'
      ))
  ) then raise exception 'workspace_membership_required' using errcode = '42501'; end if;

  select * into f from public.agent_workspace_files
    where workspace_id = p_workspace_id and path = p_path and deleted_at is not null
    for update;
  if not found then raise exception 'workspace_deleted_file_not_found' using errcode = 'P0002'; end if;
  if f.user_id <> p_user_id then raise exception 'workspace_file_owner_mismatch' using errcode = '42501'; end if;
  if f.version <> p_expected_version then raise exception 'workspace_version_conflict' using errcode = '40001'; end if;
  if f.pending_token is not null or f.storage_path is null or f.sha256 is null or f.size_bytes is null then
    raise exception 'workspace_file_not_committed_or_write_in_progress' using errcode = '40001';
  end if;
  if p_sha256 is distinct from f.sha256 or p_size_bytes is distinct from f.size_bytes then
    raise exception 'workspace_restore_integrity_mismatch' using errcode = '22000';
  end if;

  v_expected_storage_path := p_user_id::text || '/workspaces/' || p_workspace_id::text
    || '/versions/' || (p_expected_version + 1)::text || '/' || p_path;
  if p_storage_path is distinct from v_expected_storage_path then
    raise exception 'workspace_restore_storage_path_invalid' using errcode = '22023';
  end if;
  if not exists (select 1 from storage.buckets b where b.id = p_bucket and b.public = false)
     or not exists (select 1 from storage.objects o where o.bucket_id = p_bucket and o.name = p_storage_path) then
    raise exception 'workspace_restore_object_missing_or_bucket_not_private' using errcode = 'P0002';
  end if;

  update public.agent_workspace_files
     set deleted_at = null, version = version + 1, storage_path = p_storage_path,
         sha256 = p_sha256, size_bytes = p_size_bytes, updated_at = now()
   where id = f.id and version = p_expected_version and deleted_at is not null
     and pending_token is null
   returning * into f;
  if not found then raise exception 'workspace_restore_fence_lost' using errcode = '40001'; end if;

  return jsonb_build_object(
    'workspace_id', p_workspace_id, 'path', f.path, 'version', f.version,
    'restored', true, 'storage_path', f.storage_path,
    'sha256', f.sha256, 'size_bytes', f.size_bytes
  );
end;

declare v_file public.agent_workspace_files%rowtype; v_expected_storage_path text;
begin
  if p_user_id is null or p_workspace_id is null or p_file_id is null
     or p_expected_version is null or p_expected_version < 1
     or p_sha256 is null or p_sha256 !~ '^[0-9a-f]{64}$'
     or p_size_bytes is null or p_size_bytes not between 0 and 2000000
     or p_bucket is null or length(p_bucket) not between 1 and 100 then
    raise exception 'workspace_file_restore_arguments_invalid' using errcode='22023';
  end if;
  if not exists(select 1 from public.workspaces w where w.id=p_workspace_id and w.status='active'
    and (w.owner_user_id=p_user_id or exists(select 1 from public.workspace_members m
      where m.workspace_id=w.id and m.user_id=p_user_id and m.status='active'))) then
    raise exception 'workspace_membership_required' using errcode='42501';
  end if;
  select * into v_file from public.agent_workspace_files
    where id=p_file_id and workspace_id=p_workspace_id for update;
  if not found then raise exception 'workspace_file_not_found' using errcode='P0002'; end if;
  if v_file.version<>p_expected_version then raise exception 'workspace_version_conflict' using errcode='40001'; end if;
  if v_file.deleted_at is null then raise exception 'workspace_file_not_deleted' using errcode='22023'; end if;
  if v_file.pending_token is not null or v_file.storage_path is null or v_file.sha256 is null or v_file.size_bytes is null then
    raise exception 'workspace_file_not_committed_or_write_in_progress' using errcode='40001';
  end if;
  if p_sha256 is distinct from v_file.sha256 or p_size_bytes is distinct from v_file.size_bytes then
    raise exception 'workspace_restore_integrity_mismatch' using errcode='22000';
  end if;
  v_expected_storage_path:=v_file.user_id::text||'/workspaces/'||p_workspace_id::text
    ||'/versions/'||(p_expected_version+1)::text||'/'||v_file.path;
  if p_storage_path is distinct from v_expected_storage_path then
    raise exception 'workspace_restore_storage_path_invalid' using errcode='22023';
  end if;
  if not exists(select 1 from storage.buckets b where b.id=p_bucket and b.public=false)
     or not exists(select 1 from storage.objects o where o.bucket_id=p_bucket and o.name=p_storage_path) then
    raise exception 'workspace_restore_object_missing_or_bucket_not_private' using errcode='P0002';
  end if;
  update public.agent_workspace_files set deleted_at=null,version=version+1,
    storage_path=p_storage_path,sha256=p_sha256,size_bytes=p_size_bytes,updated_at=now()
    where id=p_file_id and workspace_id=p_workspace_id and version=p_expected_version
      and deleted_at is not null and pending_token is null returning * into v_file;
  if not found then raise exception 'workspace_file_restore_fence_lost' using errcode='40001'; end if;
  return jsonb_build_object('id',v_file.id,'workspace_id',v_file.workspace_id,'path',v_file.path,
    'version',v_file.version,'deleted_at',v_file.deleted_at,'status','restored',
    'storage_path',v_file.storage_path,'sha256',v_file.sha256,'size_bytes',v_file.size_bytes);
end;

declare
  v_count bigint;
begin
  if p_user_id is null or p_document_id is null then
    raise exception 'knowledge_chunk_count_arguments_invalid' using errcode = '22023';
  end if;
  if not exists (
    select 1 from public.knowledge_documents d
    where d.id = p_document_id and d.owner_user_id = p_user_id
  ) then
    raise exception 'knowledge_document_not_found_or_not_owned' using errcode = '42501';
  end if;
  select count(*)::bigint into v_count
  from public.knowledge_chunks c
  where c.document_id = p_document_id and c.owner_user_id = p_user_id;
  return v_count;
end;

declare
  v_existing public.outbox_events;
  v_sequence bigint;
  v_event_id uuid := gen_random_uuid();
  v_created_at timestamptz := now();
begin
  if p_run_id is null or p_event_key is null or char_length(p_event_key) not between 1 and 200
     or p_event_type is null or p_event_type !~ '^[a-z][a-z0-9_.-]{0,79}$'
     or jsonb_typeof(coalesce(p_payload,'{}'::jsonb)) <> 'object'
     or octet_length(coalesce(p_payload,'{}'::jsonb)::text) > 16384 then
    raise exception 'invalid_approval_lifecycle_event' using errcode='22023';
  end if;

  select * into v_existing
    from public.outbox_events
   where aggregate_type='agent_run' and aggregate_id=p_run_id and event_key=p_event_key;
  if found then
    if v_existing.payload->>'event_type' <> p_event_type
       or v_existing.payload->'event_payload' <> coalesce(p_payload,'{}'::jsonb) then
      raise exception 'approval_event_idempotency_conflict' using errcode='22023';
    end if;
    return v_existing.run_sequence;
  end if;

  insert into public.agent_run_event_counters(run_id,last_sequence)
  values(p_run_id,coalesce((select max(sequence) from public.agent_run_events where run_id=p_run_id),0))
  on conflict(run_id) do nothing;
  perform 1 from public.agent_run_event_counters where run_id=p_run_id for update;

  -- Re-check after taking the per-run counter lock to serialize concurrent
  -- decision requests and preserve the existing unique event-key invariant.
  select * into v_existing
    from public.outbox_events
   where aggregate_type='agent_run' and aggregate_id=p_run_id and event_key=p_event_key;
  if found then
    if v_existing.payload->>'event_type' <> p_event_type
       or v_existing.payload->'event_payload' <> coalesce(p_payload,'{}'::jsonb) then
      raise exception 'approval_event_idempotency_conflict' using errcode='22023';
    end if;
    return v_existing.run_sequence;
  end if;

  update public.agent_run_event_counters
     set last_sequence=last_sequence+1,updated_at=v_created_at
   where run_id=p_run_id returning last_sequence into v_sequence;

  insert into public.agent_run_events(id,run_id,event_type,sequence,payload,created_at)
  values(v_event_id,p_run_id,p_event_type,v_sequence,coalesce(p_payload,'{}'::jsonb),v_created_at);

  insert into public.outbox_events(
    id,aggregate_type,aggregate_id,event_type,payload,status,attempts,available_at,
    created_at,event_key,run_sequence
  ) values(
    v_event_id,'agent_run',p_run_id,'run.event',
    jsonb_build_object(
      'run_id',p_run_id,'event_id',v_event_id,'sequence',v_sequence,
      'event_type',p_event_type,'event_payload',coalesce(p_payload,'{}'::jsonb),
      'created_at',v_created_at
    ),
    'pending',0,v_created_at,v_created_at,p_event_key,v_sequence
  );
  return v_sequence;
end;

declare
  a public.agent_tool_approvals%rowtype;
  p public.agent_run_approval_pauses%rowtype;
  v_status text;
  v_run_status text;
  v_event_type text;
  v_event_payload jsonb;
begin
  if p_decision not in ('approved','denied') then
    raise exception 'invalid_approval_decision' using errcode='22023';
  end if;

  select * into a
    from public.agent_tool_approvals
   where id=p_approval_id and user_id=p_user_id
   for update;
  if not found then
    raise exception 'approval_not_found' using errcode='P0002';
  end if;

  select * into p
    from public.agent_run_approval_pauses
   where approval_id=p_approval_id
   for update;

  if not found then
    if a.status in ('approved','denied','expired','consumed') then
      v_status:=a.status;
    else
      update public.agent_tool_approvals
         set status=case when expires_at<=now() then 'expired' else p_decision end,
             decided_at=now(),decided_by=p_user_id
       where id=p_approval_id
       returning * into a;
      v_status:=a.status;
    end if;

    v_event_type:=case v_status
      when 'approved' then 'tool.approval_granted'
      when 'denied' then 'tool.approval_denied'
      when 'expired' then 'tool.approval_expired'
      else null end;
    if v_event_type is not null then
      v_event_payload:=jsonb_build_object(
        'approval_id',a.id,'tool',a.tool_key,'status',v_status,
        'arguments_hash',a.arguments_hash,'decided_at',a.decided_at
      );
      perform public.moreai_append_approval_lifecycle_event(
        a.run_id,'approval.decision:'||a.id::text||':'||v_status,
        v_event_type,v_event_payload
      );
    end if;

    return jsonb_build_object(
      'id',a.id,'run_id',a.run_id,'status',v_status,'resumed',false
    );
  end if;

  if a.status='pending' then
    v_status:=case when a.expires_at<=now() then 'expired' else p_decision end;
    update public.agent_tool_approvals
       set status=v_status,decided_at=now(),decided_by=p_user_id
     where id=a.id
     returning * into a;
    update public.agent_run_approval_pauses
       set status=v_status,decided_at=now()
     where id=p.id
     returning * into p;
  else
    v_status:=a.status;
    if p.status<>v_status then
      raise exception 'approval_pause_state_conflict' using errcode='40001';
    end if;
  end if;

  v_event_type:=case v_status
    when 'approved' then 'tool.approval_granted'
    when 'denied' then 'tool.approval_denied'
    when 'expired' then 'tool.approval_expired'
    else null end;
  if v_event_type is not null then
    v_event_payload:=jsonb_build_object(
      'approval_id',a.id,'tool',a.tool_key,'status',v_status,
      'arguments_hash',a.arguments_hash,'decided_at',a.decided_at,
      'checkpoint_key',p.checkpoint_key
    );
    perform public.moreai_append_approval_lifecycle_event(
      a.run_id,'approval.decision:'||a.id::text||':'||v_status,
      v_event_type,v_event_payload
    );
  end if;

  update public.agent_runs
     set status='queued',resume_pending=true,available_at=now(),updated_at=now()
   where id=p.run_id and status='waiting_approval'
   returning status into v_run_status;

  update public.agent_run_checkpoints
     set state=state||jsonb_build_object(
       'status',v_status,'decided_at',a.decided_at,'resume_pending',true
     ),created_at=now()
   where run_id=p.run_id and checkpoint_key=p.checkpoint_key;

  if coalesce(v_run_status='queued',false) then
    perform public.moreai_append_approval_lifecycle_event(
      p.run_id,'approval.resume_queued:'||a.id::text,
      'run.resume_queued',
      jsonb_build_object(
        'approval_id',a.id,'status',v_status,
        'checkpoint_key',p.checkpoint_key,'resume_pending',true
      )
    );
  end if;

  return jsonb_build_object(
    'id',a.id,'run_id',a.run_id,'status',v_status,
    'resumed',coalesce(v_run_status='queued',false)
  );
end;

declare v_row public.moreai_customer_memory_preferences%rowtype;
begin
  if p_user_id is null or p_enabled is null or p_consent_version is null
     or length(p_consent_version) not between 1 and 40 then
    raise exception 'memory_consent_arguments_invalid' using errcode = '22023';
  end if;
  insert into public.moreai_customer_memory_preferences (
    user_id, enabled, consent_version, consented_at, disabled_at, updated_at
  ) values (
    p_user_id, p_enabled, p_consent_version,
    case when p_enabled then now() else null end,
    case when p_enabled then null else now() end,
    now()
  )
  on conflict (user_id) do update set
    enabled = excluded.enabled,
    consent_version = excluded.consent_version,
    consented_at = case when excluded.enabled then now()
                        else public.moreai_customer_memory_preferences.consented_at end,
    disabled_at = case when excluded.enabled then null else now() end,
    updated_at = now()
  returning * into v_row;
  return v_row;
end;

declare v_deleted bigint;
begin
  if p_user_id is null then
    raise exception 'memory_clear_user_required' using errcode = '22023';
  end if;
  update public.moreai_customer_memory_preferences
     set enabled = false, disabled_at = now(), updated_at = now()
   where user_id = p_user_id;
  delete from public.moreai_customer_memories where user_id = p_user_id;
  get diagnostics v_deleted = row_count;
  return v_deleted;
end;

declare v_deleted bigint;
begin
  delete from public.moreai_customer_memories
   where expires_at <= now();
  get diagnostics v_deleted = row_count;
  return v_deleted;
end;

declare v_row public.moreai_worker_capability_snapshots%rowtype;
begin
    if p_worker_id is null or length(p_worker_id) < 8 or length(p_worker_id) > 128
       or p_runtime_keys is null or p_capabilities is null
       or jsonb_typeof(p_capabilities) <> 'object'
       or p_status not in ('healthy', 'degraded') then
        raise exception 'invalid worker capability heartbeat' using errcode = '22023';
    end if;
    insert into public.moreai_worker_capability_snapshots(
        worker_id, runtime_keys, capabilities, status, last_seen_at, updated_at
    ) values (p_worker_id, p_runtime_keys, p_capabilities, p_status, now(), now())
    on conflict (worker_id) do update set
        runtime_keys = excluded.runtime_keys, capabilities = excluded.capabilities,
        status = excluded.status, last_seen_at = now(), updated_at = now()
    returning * into v_row;
    return jsonb_build_object(
        'worker_id', v_row.worker_id, 'runtime_keys', to_jsonb(v_row.runtime_keys),
        'status', v_row.status, 'last_seen_at', v_row.last_seen_at
    );
end;

declare
    v_conversation public.conversations%rowtype;
    v_message public.conversation_messages%rowtype;
    v_run public.agent_runs%rowtype;
    v_config public.moreai_customer_agent_configs%rowtype;
begin
    if p_user_id is null or p_conversation_id is null
       or p_content is null or length(btrim(p_content)) = 0 or length(p_content) > 100000
       or p_agent_key not in ('manus', 'toolcall')
       or p_idempotency_key is null or length(p_idempotency_key) < 12 or length(p_idempotency_key) > 128
       or p_agent_config_id is null then
        raise exception 'invalid configured chat enqueue request' using errcode = '22023';
    end if;
    select * into v_config from public.moreai_customer_agent_configs
     where id = p_agent_config_id and user_id = p_user_id and enabled = true for share;
    if not found or v_config.runtime_key <> p_agent_key then
        raise exception 'agent configuration not found or runtime mismatch' using errcode = '42501';
    end if;
    select * into v_conversation from public.conversations
     where id = p_conversation_id and user_id = p_user_id for update;
    if not found then raise exception 'conversation not found' using errcode = '42501'; end if;
    select * into v_run from public.agent_runs
     where user_id = p_user_id and idempotency_key = p_idempotency_key;
    if found then
        return jsonb_build_object('run', to_jsonb(v_run), 'message', null, 'replayed', true);
    end if;
    insert into public.conversation_messages(conversation_id, user_id, role, content, metadata)
    values (p_conversation_id, p_user_id, 'user', p_content, '{}'::jsonb)
    returning * into v_message;
    insert into public.agent_runs(
        user_id, workspace_id, conversation_id, status, idempotency_key, input, max_attempts
    ) values (
        p_user_id, v_conversation.workspace_id, p_conversation_id, 'queued',
        p_idempotency_key,
        jsonb_build_object(
            'prompt', p_content, 'agent_key', p_agent_key,
            'agent_config', jsonb_build_object(
                'id', v_config.id, 'runtime_key', v_config.runtime_key,
                'name', v_config.name, 'system_prompt', v_config.system_prompt,
                'tool_keys', to_jsonb(v_config.tool_keys), 'version', v_config.version
            ),
            'conversation_id', p_conversation_id, 'message_id', v_message.id
        ),
        3
    ) returning * into v_run;
    update public.conversation_messages set run_id = v_run.id
     where id = v_message.id and user_id = p_user_id;
    v_message.run_id := v_run.id;
    return jsonb_build_object('run', to_jsonb(v_run), 'message', to_jsonb(v_message), 'replayed', false);
end;

declare
    v_conversation public.conversations%rowtype;
    v_message public.conversation_messages%rowtype;
    v_run public.agent_runs%rowtype;
    v_config public.moreai_customer_agent_configs%rowtype;
    v_attachment_ids uuid[];
    v_attachment_count integer;
begin
    if p_user_id is null or p_conversation_id is null
       or p_content is null or length(btrim(p_content)) = 0 or length(p_content) > 100000
       or p_agent_key is null or p_agent_key not in ('manus','toolcall')
       or p_idempotency_key is null or length(p_idempotency_key) not between 12 and 128
       or p_agent_config_id is null or coalesce(cardinality(p_attachment_ids),0) > 10 then
        raise exception 'invalid_configured_chat_enqueue_request' using errcode = '22023';
    end if;
    select * into v_config from public.moreai_customer_agent_configs
     where id = p_agent_config_id and user_id = p_user_id and enabled = true for share;
    if not found or v_config.runtime_key <> p_agent_key then
        raise exception 'agent_configuration_not_found_or_runtime_mismatch' using errcode = '42501';
    end if;
    select coalesce(array_agg(x order by x), '{}'::uuid[])
      into v_attachment_ids
      from (select distinct unnest(coalesce(p_attachment_ids, '{}'::uuid[])) as x) q;
    if cardinality(v_attachment_ids) <> coalesce(cardinality(p_attachment_ids),0) then
        raise exception 'duplicate_chat_attachment_id' using errcode = '22023';
    end if;
    select * into v_conversation from public.conversations
     where id = p_conversation_id and user_id = p_user_id and status = 'active' for update;
    if not found then raise exception 'conversation_not_found_or_inactive' using errcode = '42501'; end if;
    if cardinality(v_attachment_ids) > 0 then
        select count(*) into v_attachment_count from public.artifacts a
         where a.id = any(v_attachment_ids)
           and a.user_id = p_user_id
           and a.metadata->>'purpose' = 'chat_attachment'
           and a.metadata->>'conversation_id' = p_conversation_id::text
           and a.size_bytes between 1 and 2000000
           and a.mime_type in ('text/plain','text/markdown','text/csv','application/json',
             'application/pdf','image/jpeg','image/png','image/webp');
        if v_attachment_count <> cardinality(v_attachment_ids) then
            raise exception 'chat_attachment_not_owned_or_not_available' using errcode = '42501';
        end if;
    end if;
    select * into v_run from public.agent_runs
     where user_id = p_user_id and idempotency_key = p_idempotency_key;
    if found then
        if v_run.input->>'prompt' is distinct from p_content
           or v_run.input->>'agent_key' is distinct from p_agent_key
           or v_run.input->'agent_config'->>'id' is distinct from p_agent_config_id::text
           or coalesce(v_run.input->'attachment_ids','[]'::jsonb) is distinct from to_jsonb(v_attachment_ids) then
            raise exception 'chat_idempotency_key_payload_conflict' using errcode = '22023';
        end if;
        return jsonb_build_object('run',to_jsonb(v_run),'message',null,'replayed',true);
    end if;
    insert into public.conversation_messages(conversation_id,user_id,role,content,metadata)
    values(p_conversation_id,p_user_id,'user',p_content,'{}'::jsonb) returning * into v_message;
    insert into public.agent_runs(user_id,workspace_id,conversation_id,status,idempotency_key,input,max_attempts)
    values(
        p_user_id,v_conversation.workspace_id,p_conversation_id,'queued',p_idempotency_key,
        jsonb_build_object(
            'prompt',p_content,'agent_key',p_agent_key,'conversation_id',p_conversation_id,
            'message_id',v_message.id,'attachment_ids',to_jsonb(v_attachment_ids),
            'agent_config',jsonb_build_object(
                'id',v_config.id,'runtime_key',v_config.runtime_key,'name',v_config.name,
                'system_prompt',v_config.system_prompt,'tool_keys',to_jsonb(v_config.tool_keys),
                'version',v_config.version
            )
        ),3
    ) returning * into v_run;
    update public.conversation_messages set run_id = v_run.id
     where id = v_message.id and user_id = p_user_id;
    v_message.run_id := v_run.id;
    if cardinality(v_attachment_ids) > 0 then
        insert into public.conversation_message_attachments(user_id,conversation_id,message_id,run_id,artifact_id)
        select p_user_id,p_conversation_id,v_message.id,v_run.id,x from unnest(v_attachment_ids) as x;
    end if;
    return jsonb_build_object('run',to_jsonb(v_run),'message',to_jsonb(v_message),'replayed',false);
end;

declare
    v_source_run public.agent_runs%rowtype;
    v_conversation public.conversations%rowtype;
    v_message public.conversation_messages%rowtype;
    v_run public.agent_runs%rowtype;
    v_attachment_ids uuid[];
    v_attachment_count integer;
begin
    if p_user_id is null or p_source_run_id is null or p_conversation_id is null
       or p_content is null or length(btrim(p_content)) = 0 or length(p_content) > 100000
       or p_agent_key not in ('manus','toolcall')
       or p_idempotency_key is null or length(p_idempotency_key) not between 12 and 128
       or p_agent_config_snapshot is null or jsonb_typeof(p_agent_config_snapshot) <> 'object'
       or p_agent_config_snapshot->>'runtime_key' is distinct from p_agent_key
       or jsonb_typeof(p_agent_config_snapshot->'tool_keys') <> 'array'
       or coalesce(cardinality(p_attachment_ids),0) > 10 then
        raise exception 'invalid_saved_agent_retry_request' using errcode = '22023';
    end if;
    select * into v_source_run from public.agent_runs
     where id = p_source_run_id and user_id = p_user_id for share;
    if not found
       or v_source_run.status not in ('failed','timed_out','expired')
       or v_source_run.conversation_id is distinct from p_conversation_id
       or v_source_run.input->>'prompt' is distinct from p_content
       or v_source_run.input->>'agent_key' is distinct from p_agent_key
       or v_source_run.input->'agent_config' is distinct from p_agent_config_snapshot then
        raise exception 'saved_agent_retry_source_mismatch' using errcode = '42501';
    end if;
    if exists (
        select 1 from public.agent_run_events e
         where e.run_id = p_source_run_id
           and e.event_type like 'tool.%'
           and coalesce(e.payload->>'tool','') not in (
               'create_chat_completion','knowledge_search','google_search',
               'planning','workspace_read_file','terminate'
           )
    ) then
        raise exception 'saved_agent_retry_has_side_effects' using errcode = '22023';
    end if;
    select coalesce(array_agg(x order by x), '{}'::uuid[])
      into v_attachment_ids
      from (select distinct unnest(coalesce(p_attachment_ids, '{}'::uuid[])) as x) q;
    if cardinality(v_attachment_ids) <> coalesce(cardinality(p_attachment_ids),0)
       or coalesce(v_source_run.input->'attachment_ids','[]'::jsonb) is distinct from to_jsonb(v_attachment_ids) then
        raise exception 'saved_agent_retry_attachment_mismatch' using errcode = '22023';
    end if;
    select * into v_conversation from public.conversations
     where id = p_conversation_id and user_id = p_user_id and status = 'active' for update;
    if not found then raise exception 'conversation_not_found_or_inactive' using errcode = '42501'; end if;
    if cardinality(v_attachment_ids) > 0 then
        select count(*) into v_attachment_count from public.artifacts a
         where a.id = any(v_attachment_ids)
           and a.user_id = p_user_id
           and a.metadata->>'purpose' = 'chat_attachment'
           and a.metadata->>'conversation_id' = p_conversation_id::text
           and a.size_bytes between 1 and 2000000
           and a.mime_type in ('text/plain','text/markdown','text/csv','application/json',
             'application/pdf','image/jpeg','image/png','image/webp');
        if v_attachment_count <> cardinality(v_attachment_ids) then
            raise exception 'chat_attachment_not_owned_or_not_available' using errcode = '42501';
        end if;
    end if;
    select * into v_run from public.agent_runs
     where user_id = p_user_id and idempotency_key = p_idempotency_key;
    if found then
        if v_run.input->>'prompt' is distinct from p_content
           or v_run.input->>'agent_key' is distinct from p_agent_key
           or v_run.input->'agent_config' is distinct from p_agent_config_snapshot
           or coalesce(v_run.input->'attachment_ids','[]'::jsonb) is distinct from to_jsonb(v_attachment_ids) then
            raise exception 'chat_idempotency_key_payload_conflict' using errcode = '22023';
        end if;
        return jsonb_build_object('run',to_jsonb(v_run),'message',null,'replayed',true);
    end if;
    insert into public.conversation_messages(conversation_id,user_id,role,content,metadata)
    values(p_conversation_id,p_user_id,'user',p_content,'{}'::jsonb) returning * into v_message;
    insert into public.agent_runs(user_id,workspace_id,conversation_id,status,idempotency_key,input,max_attempts)
    values(
        p_user_id,v_conversation.workspace_id,p_conversation_id,'queued',p_idempotency_key,
        jsonb_build_object(
            'prompt',p_content,'agent_key',p_agent_key,'conversation_id',p_conversation_id,
            'message_id',v_message.id,'attachment_ids',to_jsonb(v_attachment_ids),
            'agent_config',p_agent_config_snapshot,'retry_of_run_id',p_source_run_id
        ),3
    ) returning * into v_run;
    update public.conversation_messages set run_id = v_run.id
     where id = v_message.id and user_id = p_user_id;
    v_message.run_id := v_run.id;
    if cardinality(v_attachment_ids) > 0 then
        insert into public.conversation_message_attachments(user_id,conversation_id,message_id,run_id,artifact_id)
        select p_user_id,p_conversation_id,v_message.id,v_run.id,x from unnest(v_attachment_ids) as x;
    end if;
    return jsonb_build_object('run',to_jsonb(v_run),'message',to_jsonb(v_message),'replayed',false);
end;

declare
  v_path public.learning_paths%rowtype;
