    raise exception 'learning_progress_status_invalid' using errcode='22023';
  end if;
  select * into v_lesson from public.learning_lessons where id=p_lesson_id and owner_user_id=p_user_id;
  if not found then raise exception 'learning_lesson_not_found' using errcode='P0002'; end if;

  insert into public.learning_enrollments(path_id,user_id,status)
  values(v_lesson.path_id,p_user_id,'active')
  on conflict(path_id,user_id) do update set status='active',completed_at=null,updated_at=now();

  insert into public.learning_progress(user_id,path_id,module_id,lesson_id,status,progress_percent,last_run_id,started_at,completed_at,updated_at)
  values(p_user_id,v_lesson.path_id,v_lesson.module_id,v_lesson.id,p_status,case when p_status='completed' then 100 else 1 end,p_run_id,now(),case when p_status='completed' then now() else null end,now())
  on conflict(user_id,lesson_id) do update set status=excluded.status,progress_percent=excluded.progress_percent,last_run_id=excluded.last_run_id,
    started_at=coalesce(public.learning_progress.started_at,now()),completed_at=case when excluded.status='completed' then now() else null end,updated_at=now()
  returning * into v_progress;

  select count(*),count(*) filter (where p.status='completed')
    into v_total,v_completed
    from public.learning_lessons l
    left join public.learning_progress p on p.lesson_id=l.id and p.user_id=p_user_id
   where l.path_id=v_lesson.path_id and l.owner_user_id=p_user_id;
  v_percent := case when v_total=0 then 0 else round((v_completed::numeric / v_total::numeric) * 100, 2) end;
  v_path_status := case when v_total>0 and v_completed=v_total then 'completed' else 'active' end;

  update public.learning_enrollments
     set status=case when v_path_status='completed' then 'completed' else 'active' end,
         completed_at=case when v_path_status='completed' then coalesce(completed_at,now()) else null end,
         updated_at=now()
   where path_id=v_lesson.path_id and user_id=p_user_id;
  update public.learning_paths set status=v_path_status,updated_at=now()
   where id=v_lesson.path_id and owner_user_id=p_user_id;

  insert into public.learning_run_artifacts(user_id,run_id,artifact_type,resource_id,payload)
  values(p_user_id,p_run_id,'progress',v_progress.id,jsonb_build_object(
    'lesson_id',v_lesson.id,'status',p_status,'progress_percent',v_progress.progress_percent,
    'path_progress_percent',v_percent,'completed_lessons',v_completed,'total_lessons',v_total
  ))
  on conflict(run_id,artifact_type,resource_id) do update set payload=excluded.payload;
  return jsonb_build_object(
    'progress_id',v_progress.id,'lesson_id',v_lesson.id,'status',v_progress.status,
    'progress_percent',v_progress.progress_percent,'path_status',v_path_status,
    'path_progress_percent',v_percent,'completed_lessons',v_completed,'total_lessons',v_total
  );
end

declare
  v_conversation public.conversations%rowtype;
  v_message public.conversation_messages%rowtype;
  v_run public.agent_runs%rowtype;
  v_attachment_ids uuid[];
  v_attachment_count integer;
  v_skill_ids uuid[];
begin
  if p_user_id is null or p_conversation_id is null
     or p_content is null or length(btrim(p_content)) = 0 or length(p_content) > 100000
     or p_agent_key is null or p_agent_key not in ('manus','planning','toolcall')
     or p_idempotency_key is null or length(p_idempotency_key) not between 12 and 128
     or coalesce(cardinality(p_attachment_ids),0) > 10
     or coalesce(cardinality(p_skill_ids),0) > 10 then
    raise exception 'invalid_chat_enqueue_request' using errcode = '22023';
  end if;

  select coalesce(array_agg(x order by x), '{}'::uuid[])
    into v_attachment_ids
    from (select distinct unnest(coalesce(p_attachment_ids, '{}'::uuid[])) as x) q;
  if cardinality(v_attachment_ids) <> coalesce(cardinality(p_attachment_ids),0) then
    raise exception 'duplicate_chat_attachment_id' using errcode = '22023';
  end if;

  select coalesce(array_agg(x order by x), '{}'::uuid[]) into v_skill_ids
    from (select distinct unnest(coalesce(p_skill_ids, '{}'::uuid[])) as x) q;
  if cardinality(v_skill_ids) <> coalesce(cardinality(p_skill_ids),0) then
    raise exception 'duplicate_skill_id' using errcode = '22023';
  end if;
  if cardinality(v_skill_ids) > 0 and (
    select count(*) from public.moreai_skill_packages p
    join public.moreai_skill_installs i on i.skill_package_id=p.id and i.owner_user_id=p_user_id
    where p.id = any(v_skill_ids) and p.owner_user_id=p_user_id
      and p.validation_status='validated' and p.license_status='approved' and p.publication_status='published'
      and i.status='installed' and i.permission_status='approved' and i.execution_enabled=true
  ) <> cardinality(v_skill_ids) then
    raise exception 'selected_skill_not_authorized' using errcode = '42501';
  end if;
  select * into v_conversation
    from public.conversations
   where id = p_conversation_id and user_id = p_user_id and status = 'active'
   for update;
  if not found then
    raise exception 'conversation_not_found_or_inactive' using errcode = '42501';
  end if;

  if cardinality(v_attachment_ids) > 0 then
    select count(*) into v_attachment_count
      from public.artifacts a
     where a.id = any(v_attachment_ids)
       and a.user_id = p_user_id
       and a.metadata->>'purpose' = 'chat_attachment'
       and a.metadata->>'conversation_id' = p_conversation_id::text
       and a.size_bytes between 1 and 2000000
       and a.mime_type in (
         'text/plain','text/markdown','text/csv','application/json',
         'application/pdf','image/jpeg','image/png','image/webp'
       );
    if v_attachment_count <> cardinality(v_attachment_ids) then
      raise exception 'chat_attachment_not_owned_or_not_available' using errcode = '42501';
    end if;
  end if;

  select * into v_run
    from public.agent_runs
   where user_id = p_user_id and idempotency_key = p_idempotency_key;
  if found then
    if v_run.input->>'prompt' is distinct from p_content
       or v_run.input->>'agent_key' is distinct from p_agent_key
       or coalesce(v_run.input->'attachment_ids','[]'::jsonb) is distinct from to_jsonb(v_attachment_ids)
       or coalesce(v_run.input->'skill_ids','[]'::jsonb) is distinct from to_jsonb(v_skill_ids) then
      raise exception 'chat_idempotency_key_payload_conflict' using errcode = '22023';
    end if;
    return pg_catalog.jsonb_build_object('run',pg_catalog.to_jsonb(v_run),'message',null,'replayed',true);
  end if;

  insert into public.conversation_messages (conversation_id,user_id,role,content,metadata)
  values (p_conversation_id,p_user_id,'user',p_content,'{}'::jsonb)
  returning * into v_message;

  insert into public.agent_runs (
    user_id,workspace_id,conversation_id,status,idempotency_key,input,max_attempts
  ) values (
    p_user_id,v_conversation.workspace_id,p_conversation_id,'queued',p_idempotency_key,
    pg_catalog.jsonb_build_object(
      'prompt',p_content,'agent_key',p_agent_key,'conversation_id',p_conversation_id,
      'message_id',v_message.id,'attachment_ids',to_jsonb(v_attachment_ids),
      'skill_ids',to_jsonb(v_skill_ids)
    ),3
  ) returning * into v_run;

  update public.conversation_messages
     set run_id = v_run.id
   where id = v_message.id and user_id = p_user_id;
  v_message.run_id := v_run.id;

  if cardinality(v_attachment_ids) > 0 then
    insert into public.conversation_message_attachments (
      user_id,conversation_id,message_id,run_id,artifact_id
    )
    select p_user_id,p_conversation_id,v_message.id,v_run.id,x
      from unnest(v_attachment_ids) as x;
  end if;

  return pg_catalog.jsonb_build_object('run',pg_catalog.to_jsonb(v_run),'message',pg_catalog.to_jsonb(v_message),'replayed',false);
end;

declare
    v_conversation public.conversations%rowtype;
    v_message public.conversation_messages%rowtype;
    v_run public.agent_runs%rowtype;
    v_config public.moreai_customer_agent_configs%rowtype;
    v_attachment_ids uuid[];
    v_attachment_count integer;
    v_skill_ids uuid[];
begin
    if p_user_id is null or p_conversation_id is null
       or p_content is null or length(btrim(p_content)) = 0 or length(p_content) > 100000
       or p_agent_key is null or p_agent_key not in ('manus','toolcall')
       or p_idempotency_key is null or length(p_idempotency_key) not between 12 and 128
       or p_agent_config_id is null or coalesce(cardinality(p_attachment_ids),0) > 10
       or coalesce(cardinality(p_skill_ids),0) > 10 then
        raise exception 'invalid_configured_chat_enqueue_request' using errcode = '22023';
    end if;
    select * into v_config from public.moreai_customer_agent_configs
     where id = p_agent_config_id and user_id = p_user_id and enabled = true for share;
    if not found or v_config.runtime_key <> p_agent_key then
        raise exception 'agent_configuration_not_found_or_runtime_mismatch' using errcode = '42501';
    end if;
    select coalesce(array_agg(x order by x), '{}'::uuid[])
      into v_attachment_ids
      from (select distinct unnest(coalesce(p_attachment_ids, '{}'::uuid[])) as x) q;
    if cardinality(v_attachment_ids) <> coalesce(cardinality(p_attachment_ids),0) then
        raise exception 'duplicate_chat_attachment_id' using errcode = '22023';
    end if;
    select coalesce(array_agg(x order by x), '{}'::uuid[]) into v_skill_ids
      from (select distinct unnest(coalesce(p_skill_ids, '{}'::uuid[])) as x) q;
    if cardinality(v_skill_ids) <> coalesce(cardinality(p_skill_ids),0) then
        raise exception 'duplicate_skill_id' using errcode = '22023';
    end if;
    if cardinality(v_skill_ids) > 0 and (
        select count(*) from public.moreai_skill_packages p
        join public.moreai_skill_installs i on i.skill_package_id=p.id and i.owner_user_id=p_user_id
        where p.id = any(v_skill_ids) and p.owner_user_id=p_user_id
          and p.validation_status='validated' and p.license_status='approved' and p.publication_status='published'
          and i.status='installed' and i.permission_status='approved' and i.execution_enabled=true
    ) <> cardinality(v_skill_ids) then
        raise exception 'selected_skill_not_authorized' using errcode = '42501';
    end if;
    select * into v_conversation from public.conversations
     where id = p_conversation_id and user_id = p_user_id and status = 'active' for update;
    if not found then raise exception 'conversation_not_found_or_inactive' using errcode = '42501'; end if;
    if cardinality(v_attachment_ids) > 0 then
        select count(*) into v_attachment_count from public.artifacts a
         where a.id = any(v_attachment_ids)
           and a.user_id = p_user_id
           and a.metadata->>'purpose' = 'chat_attachment'
           and a.metadata->>'conversation_id' = p_conversation_id::text
           and a.size_bytes between 1 and 2000000
           and a.mime_type in ('text/plain','text/markdown','text/csv','application/json',
             'application/pdf','image/jpeg','image/png','image/webp');
        if v_attachment_count <> cardinality(v_attachment_ids) then
            raise exception 'chat_attachment_not_owned_or_not_available' using errcode = '42501';
        end if;
    end if;
    select * into v_run from public.agent_runs
     where user_id = p_user_id and idempotency_key = p_idempotency_key;
    if found then
        if v_run.input->>'prompt' is distinct from p_content
           or v_run.input->>'agent_key' is distinct from p_agent_key
           or v_run.input->'agent_config'->>'id' is distinct from p_agent_config_id::text
           or coalesce(v_run.input->'attachment_ids','[]'::jsonb) is distinct from to_jsonb(v_attachment_ids)
           or coalesce(v_run.input->'skill_ids','[]'::jsonb) is distinct from to_jsonb(v_skill_ids) then
            raise exception 'chat_idempotency_key_payload_conflict' using errcode = '22023';
        end if;
        return jsonb_build_object('run',to_jsonb(v_run),'message',null,'replayed',true);
    end if;
    insert into public.conversation_messages(conversation_id,user_id,role,content,metadata)
    values(p_conversation_id,p_user_id,'user',p_content,'{}'::jsonb) returning * into v_message;
    insert into public.agent_runs(user_id,workspace_id,conversation_id,status,idempotency_key,input,max_attempts)
    values(
        p_user_id,v_conversation.workspace_id,p_conversation_id,'queued',p_idempotency_key,
        jsonb_build_object(
            'prompt',p_content,'agent_key',p_agent_key,'conversation_id',p_conversation_id,
            'message_id',v_message.id,'attachment_ids',to_jsonb(v_attachment_ids),'skill_ids',to_jsonb(v_skill_ids),
            'agent_config',jsonb_build_object(
                'id',v_config.id,'runtime_key',v_config.runtime_key,'name',v_config.name,
                'system_prompt',v_config.system_prompt,'tool_keys',to_jsonb(v_config.tool_keys),
                'version',v_config.version
            )
        ),3
    ) returning * into v_run;
    update public.conversation_messages set run_id = v_run.id
     where id = v_message.id and user_id = p_user_id;
    v_message.run_id := v_run.id;
    if cardinality(v_attachment_ids) > 0 then
        insert into public.conversation_message_attachments(user_id,conversation_id,message_id,run_id,artifact_id)
        select p_user_id,p_conversation_id,v_message.id,v_run.id,x from unnest(v_attachment_ids) as x;
    end if;
    return jsonb_build_object('run',to_jsonb(v_run),'message',to_jsonb(v_message),'replayed',false);
end;

declare
  v_package public.moreai_skill_packages%rowtype;
  v_count integer;
  v_bytes bigint;
begin
  if p_skill_id is null or p_owner_user_id is null
     or jsonb_typeof(p_files)<>'array' or jsonb_array_length(p_files)<1
     or jsonb_array_length(p_files)>40 or jsonb_typeof(p_validation_report)<>'object' then
    raise exception 'skill_source_ingestion_payload_invalid' using errcode='22023';
  end if;
  select * into v_package from public.moreai_skill_packages
   where id=p_skill_id and owner_user_id=p_owner_user_id for update;
  if not found then raise exception 'skill_not_found' using errcode='42501'; end if;
  if exists(select 1 from public.moreai_skill_source_files where skill_package_id=p_skill_id) then
    raise exception 'skill_source_already_ingested_immutable' using errcode='23505';
  end if;
  select count(*),coalesce(sum((x->>'byte_size')::bigint),0)
    into v_count,v_bytes from jsonb_array_elements(p_files) x;
  if v_count<>jsonb_array_length(p_files) or v_bytes>5242880 then
    raise exception 'skill_source_package_size_limit_exceeded' using errcode='22023';
  end if;
  if exists(
    select 1 from jsonb_array_elements(p_files) x
    where coalesce(x->>'relative_path','')='' or x->>'relative_path' ~ '(^/|(^|/)\.\.(/|$))'
       or coalesce(x->>'git_blob_sha','') !~ '^[0-9a-f]{40}$'
       or coalesce(x->>'content_sha256','') !~ '^[0-9a-f]{64}$'
       or coalesce((x->>'byte_size')::integer,-1)<0
       or (x->>'byte_size')::integer>524288
       or ((x->>'text_content') is null) = ((x->>'binary_content_base64') is null)
  ) then raise exception 'skill_source_file_record_invalid' using errcode='22023'; end if;
  if (select count(distinct x->>'relative_path') from jsonb_array_elements(p_files) x)<>v_count then
    raise exception 'skill_source_duplicate_path' using errcode='22023';
  end if;
  insert into public.moreai_skill_source_files(
    skill_package_id,owner_user_id,relative_path,git_blob_sha,content_sha256,
    media_type,byte_size,text_content,binary_content_base64
  )
  select p_skill_id,p_owner_user_id,x->>'relative_path',x->>'git_blob_sha',x->>'content_sha256',
    x->>'media_type',(x->>'byte_size')::integer,x->>'text_content',x->>'binary_content_base64'
  from jsonb_array_elements(p_files) x;
  update public.moreai_skill_packages set
    validation_status='review_required',validation_report=p_validation_report,updated_at=now()
  where id=p_skill_id and owner_user_id=p_owner_user_id;
  insert into public.moreai_skill_registry_audit(
    skill_package_id,owner_user_id,event_type,event_detail
  ) values(
    p_skill_id,p_owner_user_id,'source_ingested',
    jsonb_build_object('file_count',v_count,'total_bytes',v_bytes,'source_commit',v_package.source_commit)
  );
  return jsonb_build_object('skill_id',p_skill_id,'file_count',v_count,'total_bytes',v_bytes,'integrity','verified');
end;

declare
  v_install public.moreai_skill_installs%rowtype;
  v_package public.moreai_skill_packages%rowtype;
  v_requested text[];
begin
  if p_decision not in ('approved','rejected') or p_granted_permissions is null
     or coalesce(cardinality(p_granted_permissions),0)>20 then
    raise exception 'skill_permission_review_payload_invalid' using errcode='22023';
  end if;
  select * into v_install from public.moreai_skill_installs
   where id=p_install_id and skill_package_id=p_skill_id for update;
  if not found then raise exception 'skill_install_not_found' using errcode='P0002'; end if;
  select * into v_package from public.moreai_skill_packages where id=p_skill_id for share;
  if not found then raise exception 'skill_not_found' using errcode='P0002'; end if;
  select coalesce(array_agg(value),'{}'::text[]) into v_requested
    from jsonb_array_elements_text(coalesce(v_install.permission_request,'[]'::jsonb)) as value;
  if p_decision='approved' and not (p_granted_permissions <@ v_requested) then
    raise exception 'granted_permissions_must_be_subset_of_requested' using errcode='22023';
  end if;
  update public.moreai_skill_installs set
    permission_status=p_decision,
    granted_permissions=case when p_decision='approved' then to_jsonb(p_granted_permissions) else '[]'::jsonb end,
    execution_enabled=(p_decision='approved' and p_execution_enabled
      and v_package.validation_status='validated' and v_package.license_status='approved'
      and v_package.publication_status='published'
      and exists(select 1 from public.moreai_skill_source_files sf
        where sf.skill_package_id=p_skill_id and sf.owner_user_id=v_install.owner_user_id)),
    updated_at=now()
  where id=p_install_id returning * into v_install;
  insert into public.moreai_skill_registry_audit(
    skill_package_id,skill_install_id,actor_user_id,owner_user_id,event_type,decision,
    permission_snapshot,event_detail
  ) values(
    p_skill_id,p_install_id,p_actor_user_id,v_install.owner_user_id,'permission_reviewed',
    p_decision,to_jsonb(v_install.granted_permissions),
    jsonb_build_object('review_note',left(coalesce(p_review_note,''),2000),
      'execution_enabled',v_install.execution_enabled,'requested_permissions',to_jsonb(v_requested))
  );
  return jsonb_build_object('install_id',v_install.id,'permission_status',v_install.permission_status,
    'granted_permissions',to_jsonb(v_install.granted_permissions),
    'execution_enabled',v_install.execution_enabled);
end;

declare v_package public.moreai_skill_packages%rowtype;
begin
  if p_license_status not in ('approved','rejected')
     or p_publication_status not in ('private','published','deprecated')
     or length(btrim(coalesce(p_review_note,'')))<3 then
    raise exception 'skill_package_review_payload_invalid' using errcode='22023';
  end if;
  select * into v_package from public.moreai_skill_packages where id=p_skill_id for update;
  if not found then raise exception 'skill_not_found' using errcode='P0002'; end if;
  if p_license_status='approved' and (
    coalesce(v_package.license_evidence,'')='' or v_package.validation_status<>'validated'
  ) then raise exception 'skill_requires_validation_and_license_evidence' using errcode='23514'; end if;
  if p_publication_status='published' and (
    p_license_status<>'approved' or v_package.manifest='{}'::jsonb
  ) then raise exception 'license_approval_and_manifest_required_before_publication' using errcode='23514'; end if;
  update public.moreai_skill_packages set
    license_status=p_license_status,publication_status=p_publication_status,
    validation_report=jsonb_set(
      coalesce(validation_report,'{}'::jsonb),'{review}',
      jsonb_build_object('reviewer_user_id',p_actor_user_id,'review_note',left(p_review_note,2000),'reviewed_at',now()),true
    ),updated_at=now()
  where id=p_skill_id returning * into v_package;
  insert into public.moreai_skill_registry_audit(
    skill_package_id,actor_user_id,owner_user_id,event_type,decision,event_detail
  ) values(
    p_skill_id,p_actor_user_id,v_package.owner_user_id,
    case when p_license_status='approved' then 'license_reviewed' else 'publication_reviewed' end,
    p_license_status,jsonb_build_object('publication_status',p_publication_status,'review_note',left(p_review_note,2000))
  );
  return jsonb_build_object('id',v_package.id,'license_status',v_package.license_status,
    'publication_status',v_package.publication_status,'validation_status',v_package.validation_status);
end;

declare v_state public.moreai_oauth_states%rowtype;
begin
  delete from public.moreai_oauth_states where state_hash=p_state_hash
    and provider='google' and expires_at>now()
    returning * into v_state;
  if not found then raise exception 'oauth_state_invalid_or_expired' using errcode='42501'; end if;
  return jsonb_build_object('user_id',v_state.user_id,'provider',v_state.provider,
    'scopes',v_state.scopes,'pkce_verifier_ciphertext',v_state.pkce_verifier_ciphertext,
    'redirect_uri',v_state.redirect_uri);
end;

declare v_connection public.moreai_connections%rowtype;
begin
  if p_user_id is null or coalesce(p_external_account_id,'')='' or
     jsonb_typeof(p_scopes)<>'array' or coalesce(p_credential_ciphertext,'')='' then
    raise exception 'google_connection_payload_invalid' using errcode='22023';
  end if;
  insert into public.moreai_connections(user_id,provider,external_account_id,display_name,scopes,status,
    credential_ciphertext,credential_key_version,access_token_expires_at,token_updated_at,last_error_code,updated_at)
  values(p_user_id,'google',p_external_account_id,left(p_display_name,240),p_scopes,'connected',
    p_credential_ciphertext,substring(split_part(p_credential_ciphertext,'.',1) from 2)::integer,p_expires_at,now(),null,now())
  on conflict(user_id,provider,external_account_id) do update set
    display_name=excluded.display_name,scopes=excluded.scopes,status='connected',
    credential_ciphertext=excluded.credential_ciphertext,credential_key_version=substring(split_part(excluded.credential_ciphertext,'.',1) from 2)::integer,
    access_token_expires_at=excluded.access_token_expires_at,token_updated_at=now(),
    last_error_code=null,updated_at=now()
  returning * into v_connection;
  insert into public.moreai_connection_audit(connection_id,user_id,provider,event_type,scopes,detail)
  values(v_connection.id,p_user_id,'google','connected',p_scopes,
    jsonb_build_object('identity_verified',true));
  return jsonb_build_object('id',v_connection.id,'provider',v_connection.provider,
    'display_name',v_connection.display_name,'scopes',v_connection.scopes,
    'status',v_connection.status,'access_token_expires_at',v_connection.access_token_expires_at);
end;

declare v_connection public.moreai_connections%rowtype;
begin
  update public.moreai_connections set status='revoked',credential_ciphertext='',
    last_error_code=null,updated_at=now()
  where id=p_connection_id and user_id=p_user_id and provider='google'
  returning * into v_connection;
  if not found then raise exception 'connection_not_found' using errcode='42501'; end if;
  insert into public.moreai_connection_audit(connection_id,user_id,provider,event_type,scopes,detail)
  values(v_connection.id,p_user_id,'google','revoked',v_connection.scopes,'{}'::jsonb);
  return jsonb_build_object('id',v_connection.id,'status',v_connection.status);
end;

declare v_action public.moreai_connection_actions%rowtype; v_inserted integer;
begin
 if p_action_type not in ('gmail.send','calendar.create') or
    p_idempotency_key is null or length(p_idempotency_key) not between 12 and 128 or
    p_payload_sha256 !~ '^[0-9a-f]{64}$' then
  raise exception 'connection_action_payload_invalid' using errcode='22023';
 end if;
 if not exists(select 1 from public.moreai_connections where id=p_connection_id and user_id=p_user_id and provider='google' and status='connected') then
  raise exception 'connection_not_found' using errcode='42501';
 end if;
 insert into public.moreai_connection_actions(user_id,connection_id,provider,action_type,idempotency_key,payload_sha256,status)
 values(p_user_id,p_connection_id,'google',p_action_type,p_idempotency_key,p_payload_sha256,'started')
 on conflict(user_id,idempotency_key) do nothing;
 get diagnostics v_inserted = row_count;
 select * into v_action from public.moreai_connection_actions
  where user_id=p_user_id and idempotency_key=p_idempotency_key for update;
 if v_action.connection_id<>p_connection_id or v_action.action_type<>p_action_type or v_action.payload_sha256<>p_payload_sha256 then
  raise exception 'connection_action_idempotency_conflict' using errcode='22023';
 end if;
 if v_inserted=0 or v_action.status<>'started' then
  return jsonb_build_object('action_id',v_action.id,'status',v_action.status,'replay',true,
   'provider_resource_id',v_action.provider_resource_id,'result_metadata',v_action.result_metadata);
 end if;
 return jsonb_build_object('action_id',v_action.id,'status',v_action.status,'replay',false);
end;

declare v_action public.moreai_connection_actions%rowtype;
begin
 if p_status not in ('completed','unknown','failed') or jsonb_typeof(p_result_metadata)<>'object' then
  raise exception 'connection_action_result_invalid' using errcode='22023';
 end if;
 update public.moreai_connection_actions set status=p_status,
  provider_resource_id=left(p_provider_resource_id,512),result_metadata=p_result_metadata,updated_at=now()
 where id=p_action_id and user_id=p_user_id and status='started'
 returning * into v_action;
 if not found then raise exception 'connection_action_not_pending' using errcode='40001'; end if;
 insert into public.moreai_connection_audit(connection_id,user_id,provider,event_type,scopes,detail)
 values(v_action.connection_id,p_user_id,'google',
  case when p_status='completed' then 'action_completed' when p_status='failed' then 'action_failed' else 'action_requested' end,
  '[]'::jsonb,jsonb_build_object('action_id',v_action.id,'action_type',v_action.action_type,'status',p_status));
 return jsonb_build_object('action_id',v_action.id,'status',v_action.status,'provider_resource_id',v_action.provider_resource_id);
end;

declare v_action public.moreai_connection_actions%rowtype; v_inserted integer;
begin
 if p_action_type not in ('gmail.send','calendar.create','calendar.update','calendar.delete') or
    p_idempotency_key is null or length(p_idempotency_key) not between 12 and 128 or
    p_payload_sha256 !~ '^[0-9a-f]{64}$' then
  raise exception 'connection_action_payload_invalid' using errcode='22023';
 end if;
 if not exists(
   select 1 from public.moreai_connections
   where id=p_connection_id and user_id=p_user_id and provider='google' and status='connected'
 ) then
  raise exception 'connection_not_found' using errcode='42501';
 end if;
 insert into public.moreai_connection_actions(
   user_id,connection_id,provider,action_type,idempotency_key,payload_sha256,status
 ) values(
   p_user_id,p_connection_id,'google',p_action_type,p_idempotency_key,p_payload_sha256,'started'
 )
 on conflict(user_id,idempotency_key) do nothing;
 get diagnostics v_inserted = row_count;
 select * into v_action from public.moreai_connection_actions
  where user_id=p_user_id and idempotency_key=p_idempotency_key for update;
 if v_action.connection_id<>p_connection_id or
    v_action.action_type<>p_action_type or
    v_action.payload_sha256<>p_payload_sha256 then
  raise exception 'connection_action_idempotency_conflict' using errcode='22023';
 end if;
 if v_inserted=0 or v_action.status<>'started' then
  return jsonb_build_object(
   'action_id',v_action.id,'status',v_action.status,'replay',true,
   'provider_resource_id',v_action.provider_resource_id,'result_metadata',v_action.result_metadata
  );
 end if;
 return jsonb_build_object('action_id',v_action.id,'status',v_action.status,'replay',false);
end;

declare
    v_conversation public.conversations%rowtype;
    v_message public.conversation_messages%rowtype;
    v_run public.agent_runs%rowtype;
    v_config public.moreai_customer_agent_configs%rowtype;
begin
    if p_user_id is null or p_conversation_id is null
       or p_content is null or length(btrim(p_content)) = 0 or length(p_content) > 100000
       or p_agent_key not in ('manus', 'toolcall')
       or p_idempotency_key is null or length(p_idempotency_key) < 12 or length(p_idempotency_key) > 128
       or p_agent_config_id is null then
        raise exception 'invalid configured chat enqueue request' using errcode = '22023';
    end if;
    select * into v_config from public.moreai_customer_agent_configs
     where id = p_agent_config_id and user_id = p_user_id and enabled = true for share;
    if not found or v_config.runtime_key <> p_agent_key then
        raise exception 'agent configuration not found or runtime mismatch' using errcode = '42501';
    end if;
    if v_config.preferred_model_id is not null and not exists (
        select 1 from public.llm_models m
        join public.llm_providers p on p.id = m.provider_id
        where m.id = v_config.preferred_model_id and m.enabled = true and p.enabled = true
    ) then
        raise exception 'configured_model_is_not_enabled' using errcode = '22023';
    end if;
    select * into v_conversation from public.conversations
     where id = p_conversation_id and user_id = p_user_id for update;
    if not found then raise exception 'conversation not found' using errcode = '42501'; end if;
    select * into v_run from public.agent_runs
     where user_id = p_user_id and idempotency_key = p_idempotency_key;
    if found then
        return jsonb_build_object('run', to_jsonb(v_run), 'message', null, 'replayed', true);
    end if;
    insert into public.conversation_messages(conversation_id, user_id, role, content, metadata)
    values (p_conversation_id, p_user_id, 'user', p_content, '{}'::jsonb)
    returning * into v_message;
    insert into public.agent_runs(
        user_id, workspace_id, conversation_id, status, idempotency_key, input, max_attempts
    ) values (
        p_user_id, v_conversation.workspace_id, p_conversation_id, 'queued',
        p_idempotency_key,
        jsonb_build_object(
            'prompt', p_content, 'agent_key', p_agent_key,
            'agent_config', jsonb_build_object(
                'id', v_config.id, 'runtime_key', v_config.runtime_key,
                'name', v_config.name, 'system_prompt', v_config.system_prompt,
                'tool_keys', to_jsonb(v_config.tool_keys),
                'preferred_model_id', v_config.preferred_model_id,
                'version', v_config.version
            ),
            'conversation_id', p_conversation_id, 'message_id', v_message.id
        ),
        3
    ) returning * into v_run;
    update public.conversation_messages set run_id = v_run.id
     where id = v_message.id and user_id = p_user_id;
    v_message.run_id := v_run.id;
    return jsonb_build_object('run', to_jsonb(v_run), 'message', to_jsonb(v_message), 'replayed', false);
end;

declare
    v_conversation public.conversations%rowtype;
    v_message public.conversation_messages%rowtype;
    v_run public.agent_runs%rowtype;
    v_config public.moreai_customer_agent_configs%rowtype;
    v_attachment_ids uuid[];
    v_attachment_count integer;
    v_agent_config_snapshot jsonb;
begin
    if p_user_id is null or p_conversation_id is null
       or p_content is null or length(btrim(p_content)) = 0 or length(p_content) > 100000
       or p_agent_key is null or p_agent_key not in ('manus','toolcall')
       or p_idempotency_key is null or length(p_idempotency_key) not between 12 and 128
       or p_agent_config_id is null or coalesce(cardinality(p_attachment_ids),0) > 10 then
        raise exception 'invalid_configured_chat_enqueue_request' using errcode = '22023';
    end if;

    select * into v_config from public.moreai_customer_agent_configs
     where id = p_agent_config_id and user_id = p_user_id and enabled = true for share;
    if not found or v_config.runtime_key <> p_agent_key then
        raise exception 'agent_configuration_not_found_or_runtime_mismatch' using errcode = '42501';
    end if;
    if v_config.preferred_model_id is not null and not exists (
        select 1 from public.llm_models m
        join public.llm_providers p on p.id = m.provider_id
        where m.id = v_config.preferred_model_id and m.enabled = true and p.enabled = true
    ) then
        raise exception 'configured_model_is_not_enabled' using errcode = '22023';
    end if;

    v_agent_config_snapshot := jsonb_build_object(
        'id', v_config.id,
        'runtime_key', v_config.runtime_key,
        'name', v_config.name,
        'system_prompt', v_config.system_prompt,
        'tool_keys', to_jsonb(v_config.tool_keys),
        'preferred_model_id', v_config.preferred_model_id,
        'version', v_config.version
    );

    select coalesce(array_agg(x order by x), '{}'::uuid[])
      into v_attachment_ids
      from (select distinct unnest(coalesce(p_attachment_ids, '{}'::uuid[])) as x) q;
    if cardinality(v_attachment_ids) <> coalesce(cardinality(p_attachment_ids),0) then
        raise exception 'duplicate_chat_attachment_id' using errcode = '22023';
    end if;

    select * into v_conversation from public.conversations
     where id = p_conversation_id and user_id = p_user_id and status = 'active' for update;
    if not found then raise exception 'conversation_not_found_or_inactive' using errcode = '42501'; end if;

    if cardinality(v_attachment_ids) > 0 then
        select count(*) into v_attachment_count from public.artifacts a
         where a.id = any(v_attachment_ids)
           and a.user_id = p_user_id
           and a.metadata->>'purpose' = 'chat_attachment'
           and a.metadata->>'conversation_id' = p_conversation_id::text
           and a.size_bytes between 1 and 2000000
           and a.mime_type in ('text/plain','text/markdown','text/csv','application/json',
             'application/pdf','image/jpeg','image/png','image/webp');
        if v_attachment_count <> cardinality(v_attachment_ids) then
            raise exception 'chat_attachment_not_owned_or_not_available' using errcode = '42501';
        end if;
    end if;

    select * into v_run from public.agent_runs
     where user_id = p_user_id and idempotency_key = p_idempotency_key;
    if found then
        if v_run.input->>'prompt' is distinct from p_content
           or v_run.input->>'agent_key' is distinct from p_agent_key
           or v_run.input->'agent_config' is distinct from v_agent_config_snapshot
           or coalesce(v_run.input->'attachment_ids','[]'::jsonb) is distinct from to_jsonb(v_attachment_ids) then
            raise exception 'chat_idempotency_key_payload_conflict' using errcode = '22023';
        end if;
        return jsonb_build_object('run',to_jsonb(v_run),'message',null,'replayed',true);
    end if;

    insert into public.conversation_messages(conversation_id,user_id,role,content,metadata)
    values(p_conversation_id,p_user_id,'user',p_content,'{}'::jsonb) returning * into v_message;
    insert into public.agent_runs(user_id,workspace_id,conversation_id,status,idempotency_key,input,max_attempts)
    values(
        p_user_id,v_conversation.workspace_id,p_conversation_id,'queued',p_idempotency_key,
        jsonb_build_object(
            'prompt',p_content,'agent_key',p_agent_key,'conversation_id',p_conversation_id,
            'message_id',v_message.id,'attachment_ids',to_jsonb(v_attachment_ids),
            'agent_config',v_agent_config_snapshot
        ),3
    ) returning * into v_run;
    update public.conversation_messages set run_id = v_run.id
     where id = v_message.id and user_id = p_user_id;
    v_message.run_id := v_run.id;
    if cardinality(v_attachment_ids) > 0 then
        insert into public.conversation_message_attachments(user_id,conversation_id,message_id,run_id,artifact_id)
        select p_user_id,p_conversation_id,v_message.id,v_run.id,x from unnest(v_attachment_ids) as x;
    end if;
    return jsonb_build_object('run',to_jsonb(v_run),'message',to_jsonb(v_message),'replayed',false);
end;

declare
 v_lesson public.learning_lessons%rowtype;
 v_progress public.learning_progress%rowtype;
 v_total integer;
 v_completed integer;
 v_percent numeric(5,2);
 v_path_status text;
begin
 if not exists(select 1 from public.agent_runs r where r.id=p_run_id and r.user_id=p_user_id) then
  raise exception 'learning_run_owner_mismatch' using errcode='42501';
 end if;
 if p_status <> 'in_progress' then
  raise exception 'learning_progress_completion_is_assessment_derived' using errcode='22023';
 end if;
 select * into v_lesson from public.learning_lessons where id=p_lesson_id and owner_user_id=p_user_id;
 if not found then raise exception 'learning_lesson_not_found' using errcode='P0002'; end if;

 insert into public.learning_enrollments(path_id,user_id,status)
 values(v_lesson.path_id,p_user_id,'active')
 on conflict(path_id,user_id) do update set
  status=case when public.learning_enrollments.status='completed' then 'completed' else 'active' end,
  updated_at=now();

 insert into public.learning_progress(
  user_id,path_id,module_id,lesson_id,status,progress_percent,last_run_id,started_at,completed_at,updated_at
 ) values(p_user_id,v_lesson.path_id,v_lesson.module_id,v_lesson.id,'in_progress',1,p_run_id,now(),null,now())
 on conflict(user_id,lesson_id) do update set
  status=case when public.learning_progress.status='completed' then 'completed' else 'in_progress' end,
  progress_percent=case when public.learning_progress.status='completed' then 100 else greatest(public.learning_progress.progress_percent,1) end,
  last_run_id=excluded.last_run_id,
  started_at=coalesce(public.learning_progress.started_at,now()),
  completed_at=case when public.learning_progress.status='completed' then public.learning_progress.completed_at else null end,
  updated_at=now()
 returning * into v_progress;

 select count(*),count(*) filter(where p.status='completed')
 into v_total,v_completed
 from public.learning_lessons l
 left join public.learning_progress p on p.lesson_id=l.id and p.user_id=p_user_id
 where l.path_id=v_lesson.path_id and l.owner_user_id=p_user_id;
 v_percent := case when v_total=0 then 0 else round((v_completed::numeric/v_total::numeric)*100,2) end;
 v_path_status := case when v_total>0 and v_completed=v_total then 'completed' else 'active' end;

 update public.learning_enrollments set
  status=case when v_path_status='completed' then 'completed' else 'active' end,
  completed_at=case when v_path_status='completed' then coalesce(completed_at,now()) else null end,
  updated_at=now()
 where path_id=v_lesson.path_id and user_id=p_user_id;
 update public.learning_paths set status=v_path_status,updated_at=now()
 where id=v_lesson.path_id and owner_user_id=p_user_id;

 insert into public.learning_run_artifacts(user_id,run_id,artifact_type,resource_id,payload)
 values(p_user_id,p_run_id,'progress',v_progress.id,jsonb_build_object(
  'lesson_id',v_lesson.id,'status',v_progress.status,'progress_percent',v_progress.progress_percent,
  'path_progress_percent',v_percent,'completed_lessons',v_completed,'total_lessons',v_total
 ))
 on conflict(run_id,artifact_type,resource_id) do update set payload=excluded.payload;

 return jsonb_build_object(
  'progress_id',v_progress.id,'lesson_id',v_lesson.id,'status',v_progress.status,
  'progress_percent',v_progress.progress_percent,'path_status',v_path_status,
  'path_progress_percent',v_percent,'completed_lessons',v_completed,'total_lessons',v_total
 );
end

declare
 v_quiz public.learning_quizzes%rowtype;
 v_attempt public.learning_quiz_attempts%rowtype;
 v_assessment public.learning_assessments%rowtype;
 v_all_passed boolean := false;
 v_progress public.learning_progress%rowtype;
 v_total integer := 0;
 v_completed integer := 0;
 v_remaining integer := 0;
 v_path_percent numeric(5,2) := 0;
begin
 if not exists(select 1 from public.agent_runs r where r.id=p_run_id and r.user_id=p_user_id) then
  raise exception 'learning_run_owner_mismatch' using errcode='42501';
 end if;
 select * into v_quiz from public.learning_quizzes where id=p_quiz_id and owner_user_id=p_user_id;
 if not found then raise exception 'learning_quiz_not_found' using errcode='P0002'; end if;
 if jsonb_typeof(p_answers) is distinct from 'array' then
  raise exception 'learning_answers_invalid' using errcode='22023';
 end if;

 insert into public.learning_quiz_attempts(quiz_id,user_id,run_id,answers,score,passed,feedback)
 values(v_quiz.id,p_user_id,p_run_id,p_answers,greatest(0,least(100,p_score)),p_score>=v_quiz.pass_score,coalesce(p_feedback,'{}'::jsonb))
 on conflict(run_id,quiz_id) do update set
  answers=excluded.answers,score=excluded.score,passed=excluded.passed,feedback=excluded.feedback
 returning * into v_attempt;

 insert into public.learning_assessments(
  user_id,path_id,module_id,lesson_id,quiz_id,run_id,assessment_type,score,rubric,feedback
 ) values(
  p_user_id,v_quiz.path_id,v_quiz.module_id,v_quiz.lesson_id,v_quiz.id,p_run_id,'quiz',
  v_attempt.score,coalesce(p_rubric,'[]'::jsonb),coalesce(p_feedback,'{}'::jsonb)
 )
 on conflict(run_id,quiz_id) where quiz_id is not null do update set
  score=excluded.score,rubric=excluded.rubric,feedback=excluded.feedback
 returning * into v_assessment;

 insert into public.learning_run_artifacts(user_id,run_id,artifact_type,resource_id,payload)
 values(p_user_id,p_run_id,'assessment',v_assessment.id,jsonb_build_object(
  'quiz_id',v_quiz.id,'attempt_id',v_attempt.id,'score',v_attempt.score,'passed',v_attempt.passed
 ))
 on conflict(run_id,artifact_type,resource_id) do update set payload=excluded.payload;

 if v_attempt.passed then
  select not exists(
   select 1 from public.learning_quizzes q
   where q.lesson_id=v_quiz.lesson_id and q.owner_user_id=p_user_id
     and not exists(
      select 1 from public.learning_quiz_attempts a
      where a.quiz_id=q.id and a.user_id=p_user_id and a.passed=true
     )
  ) into v_all_passed;

  if v_all_passed then
   insert into public.learning_progress(
    user_id,path_id,module_id,lesson_id,status,progress_percent,last_run_id,started_at,completed_at,updated_at
   ) values(
    p_user_id,v_quiz.path_id,v_quiz.module_id,v_quiz.lesson_id,'in_progress',1,p_run_id,now(),null,now()
   )
   on conflict(user_id,lesson_id) do update set
    last_run_id=excluded.last_run_id,
    started_at=coalesce(public.learning_progress.started_at,now()),
    updated_at=now()
   returning * into v_progress;

   update public.learning_progress set
    status='completed',progress_percent=100,
    completed_at=coalesce(completed_at,now()),last_run_id=p_run_id,updated_at=now()
   where user_id=p_user_id and lesson_id=v_quiz.lesson_id
   returning * into v_progress;

   insert into public.learning_run_artifacts(user_id,run_id,artifact_type,resource_id,payload)
   values(p_user_id,p_run_id,'progress',v_progress.id,jsonb_build_object(
    'lesson_id',v_quiz.lesson_id,'status','completed','progress_percent',100,
    'completion_source','all_required_quizzes_passed'
   ))
   on conflict(run_id,artifact_type,resource_id) do update set payload=excluded.payload;
  end if;
 end if;

 select count(*),count(*) filter(where p.status='completed')
 into v_total,v_completed
 from public.learning_lessons l
 left join public.learning_progress p on p.lesson_id=l.id and p.user_id=p_user_id
 where l.path_id=v_quiz.path_id and l.owner_user_id=p_user_id;
 v_remaining := greatest(v_total-v_completed,0);
 v_path_percent := case when v_total=0 then 0 else round((v_completed::numeric/v_total::numeric)*100,2) end;
 if v_total>0 and v_remaining=0 then
  update public.learning_enrollments set status='completed',
   completed_at=coalesce(completed_at,now()),updated_at=now()
  where path_id=v_quiz.path_id and user_id=p_user_id;
  update public.learning_paths set status='completed',updated_at=now()
  where id=v_quiz.path_id and owner_user_id=p_user_id;
 end if;

 return jsonb_build_object(
  'attempt_id',v_attempt.id,'assessment_id',v_assessment.id,
  'score',v_attempt.score,'passed',v_attempt.passed,
  'lesson_completed',coalesce(v_progress.status='completed',false),
  'path_progress_percent',v_path_percent,'completed_lessons',v_completed,'total_lessons',v_total
 );
end

declare
  v_policy public.llm_routing_policies%rowtype;
  v_action text;
begin
  if p_actor_user_id is null
    or p_task_type not in ('general', 'chat', 'planning')
    or p_model_id is null
    or p_priority < 0 then
    raise exception using errcode='22023', message='LLM_ROUTE_INVALID';
  end if;

  if not exists (
    select 1
    from public.user_role_assignments ura
    join public.roles r on r.id=ura.role_id
    join public.role_permissions rp on rp.role_id=r.id
    join public.permissions p on p.id=rp.permission_id
    where ura.user_id=p_actor_user_id
      and ura.scope_type='platform'
      and ura.scope_id is null
      and (ura.expires_at is null or ura.expires_at>now())
      and r.scope='platform'
      and p.key='platform.models.manage'
  ) then
    raise exception using errcode='42501', message='ADMIN_PERMISSION_DENIED';
  end if;

  if p_enabled and not exists (
    select 1 from public.llm_models m
    join public.llm_providers pr on pr.id=m.provider_id
    where m.id=p_model_id and m.enabled=true and pr.enabled=true
  ) then
    raise exception using errcode='55000', message='LLM_PRIMARY_MODEL_NOT_READY';
  end if;

  if p_enabled and p_fallback_model_id is not null and not exists (
    select 1 from public.llm_models m
    join public.llm_providers pr on pr.id=m.provider_id
    where m.id=p_fallback_model_id and m.enabled=true and pr.enabled=true
  ) then
    raise exception using errcode='55000', message='LLM_FALLBACK_MODEL_NOT_READY';
  end if;

  if p_policy_id is null then
    insert into public.llm_routing_policies(
      scope_type, scope_id, task_type, model_id, priority, fallback_model_id, enabled
    ) values ('platform', null, p_task_type, p_model_id, p_priority, p_fallback_model_id, p_enabled)
    returning * into v_policy;
    v_action := 'llm.routing.create';
  else
    select * into v_policy
    from public.llm_routing_policies
    where id=p_policy_id and scope_type='platform' and scope_id is null
    for update;
    if not found then
      raise exception using errcode='P0002', message='LLM_ROUTE_NOT_FOUND';
    end if;
    update public.llm_routing_policies
    set task_type=p_task_type, model_id=p_model_id, priority=p_priority,
        fallback_model_id=p_fallback_model_id, enabled=p_enabled
    where id=p_policy_id
    returning * into v_policy;
    v_action := 'llm.routing.update';
  end if;

  insert into public.admin_audit_logs(
    actor_user_id, action, resource_type, resource_id, scope_type,
    correlation_id, outcome, metadata
  ) values (
    p_actor_user_id, v_action, 'llm_routing_policy', v_policy.id::text, 'platform',
    coalesce(nullif(p_correlation_id,''), gen_random_uuid()::text), 'success',
    jsonb_build_object(
      'task_type',v_policy.task_type,'model_id',v_policy.model_id,
      'fallback_model_id',v_policy.fallback_model_id,
      'priority',v_policy.priority,'enabled',v_policy.enabled
    )
  );

  return jsonb_build_object(
    'id',v_policy.id,'task_type',v_policy.task_type,'model_id',v_policy.model_id,
    'fallback_model_id',v_policy.fallback_model_id,'priority',v_policy.priority,
    'enabled',v_policy.enabled
  );
end;

declare
  v_provider public.llm_providers%rowtype;
  v_host text;
begin
  if p_actor_user_id is null or p_provider_id is null
    or p_base_url is null
    or p_base_url !~* '^https://[a-z0-9.-]+(:[0-9]{1,5})?(/[a-z0-9._~!$&''()*+,;=:@%/-]*)?$'
    or p_secret_env_name is null
    or p_secret_env_name !~ '^MOREAI_PROVIDER_[A-Z0-9_]{1,100}$' then
    raise exception using errcode='22023', message='LLM_PROVIDER_CONFIG_INVALID';
  end if;

  v_host := lower(split_part(split_part(p_base_url, '://', 2), '/', 1));
  v_host := split_part(v_host, ':', 1);
  if v_host !~ '\.' or v_host in ('localhost','localhost.localdomain')
    or v_host ~ '^(127\.|10\.|192\.168\.|169\.254\.|0\.)'
    or v_host ~ '^172\.(1[6-9]|2[0-9]|3[01])\.' then
    raise exception using errcode='22023', message='LLM_PROVIDER_HOST_NOT_ALLOWED';
  end if;

  if not exists (
    select 1
    from public.user_role_assignments ura
    join public.roles r on r.id=ura.role_id
    join public.role_permissions rp on rp.role_id=r.id
    join public.permissions p on p.id=rp.permission_id
    where ura.user_id=p_actor_user_id
      and ura.scope_type='platform' and ura.scope_id is null
      and (ura.expires_at is null or ura.expires_at>now())
      and r.scope='platform' and p.key='platform.models.manage'
  ) then
    raise exception using errcode='42501', message='ADMIN_PERMISSION_DENIED';
  end if;

  select * into v_provider
  from public.llm_providers
  where id=p_provider_id
  for update;
  if not found then
    raise exception using errcode='P0002', message='LLM_PROVIDER_NOT_FOUND';
  end if;

  update public.llm_providers
  set config = jsonb_build_object(
        'base_url', rtrim(p_base_url, '/'),
        'secret_env_name', p_secret_env_name
      ),
      updated_at=now()
  where id=p_provider_id
  returning * into v_provider;

  insert into public.admin_audit_logs(
    actor_user_id, action, resource_type, resource_id, scope_type,
    correlation_id, outcome, metadata
  ) values (
    p_actor_user_id, 'llm.provider.configure', 'llm_provider',
    v_provider.id::text, 'platform',
    coalesce(nullif(p_correlation_id,''), gen_random_uuid()::text),
    'success',
    jsonb_build_object(
      'provider_key',v_provider.key,
      'base_url',rtrim(p_base_url,'/'),
      'secret_env_name',p_secret_env_name
    )
  );

  return jsonb_build_object(
    'id',v_provider.id,'key',v_provider.key,
    'configured',true,'enabled',v_provider.enabled
  );
end;

