declare
  v_grant public.moreai_browser_takeover_grants%rowtype;
begin
  if p_token_sha256 is null or p_token_sha256 !~ '^[0-9a-f]{64}$'
     or p_worker_id is null or p_worker_id !~ '^[A-Za-z0-9._:-]{8,128}$' then
    return jsonb_build_object('status', 'invalid');
  end if;

  update public.moreai_browser_takeover_grants g
     set consumed_at = pg_catalog.now(), consumed_by_worker = p_worker_id
   where g.token_sha256 = p_token_sha256
     and g.consumed_at is null and g.revoked_at is null
     and g.expires_at > pg_catalog.now()
     and exists (
       select 1 from public.moreai_browser_sessions s
        where s.id = g.session_id and s.user_id = g.user_id
          and s.status = 'active' and s.expires_at > pg_catalog.now()
     )
  returning g.* into v_grant;

  if not found then
    return jsonb_build_object('status', 'unavailable');
  end if;

  insert into public.moreai_browser_session_events(session_id,user_id,event_type,metadata)
  values (v_grant.session_id,v_grant.user_id,'takeover_grant_consumed',
    pg_catalog.jsonb_build_object('grant_id',v_grant.id,'worker_id',p_worker_id,'scopes',v_grant.scopes));

  return pg_catalog.jsonb_build_object(
    'status','consumed','grant_id',v_grant.id,'session_id',v_grant.session_id,
    'user_id',v_grant.user_id,'scopes',v_grant.scopes,'expires_at',v_grant.expires_at
  );
end;

declare v_count integer;
begin
  update public.moreai_browser_takeover_grants
     set revoked_at = pg_catalog.now()
   where session_id = p_session_id and user_id = p_user_id
     and consumed_at is null and revoked_at is null;
  get diagnostics v_count = row_count;
  insert into public.moreai_browser_session_events(session_id,user_id,event_type,metadata)
  values (p_session_id,p_user_id,'takeover_grants_revoked',pg_catalog.jsonb_build_object('count',v_count));
  return v_count;
end;

declare v_count integer;
begin
  if old.status = 'active' and new.status <> 'active' then
    update public.moreai_browser_takeover_grants
       set revoked_at = pg_catalog.now()
     where session_id = new.id and user_id = new.user_id
       and consumed_at is null and revoked_at is null;
    get diagnostics v_count = row_count;
    if v_count > 0 then
      insert into public.moreai_browser_session_events(session_id,user_id,event_type,metadata)
      values (new.id,new.user_id,'takeover_grants_revoked',
        pg_catalog.jsonb_build_object('reason','session_status_changed','count',v_count));
    end if;
  end if;
  return new;
end;

declare
  v_session record;
  v_count integer;
begin
  if new.status in ('succeeded','failed','cancelled','timed_out','expired')
     and old.status is distinct from new.status then
    for v_session in
      select s.id, s.user_id
        from public.moreai_browser_sessions s
       where s.user_id = new.user_id
         and (s.run_id = new.id or s.last_run_id = new.id)
    loop
      update public.moreai_browser_takeover_grants
         set revoked_at = pg_catalog.now()
       where session_id = v_session.id and user_id = v_session.user_id
         and consumed_at is null and revoked_at is null;
      get diagnostics v_count = row_count;
      if v_count > 0 then
        insert into public.moreai_browser_session_events(session_id,user_id,event_type,metadata)
        values (v_session.id,v_session.user_id,'takeover_grants_revoked',
          pg_catalog.jsonb_build_object('reason','agent_run_terminal','run_id',new.id,'count',v_count));
      end if;
    end loop;
  end if;
  return new;
end;

declare
  v_session record;
  v_total integer := 0;
  v_count integer;
begin
  if p_user_id is null then
    raise exception 'user_id_required' using errcode = '22023';
  end if;

  for v_session in
    select distinct g.session_id
      from public.moreai_browser_takeover_grants g
     where g.user_id = p_user_id
       and g.consumed_at is null and g.revoked_at is null
  loop
    update public.moreai_browser_takeover_grants
       set revoked_at = pg_catalog.now()
     where session_id = v_session.session_id and user_id = p_user_id
       and consumed_at is null and revoked_at is null;
    get diagnostics v_count = row_count;
    v_total := v_total + v_count;
    if v_count > 0 then
      insert into public.moreai_browser_session_events(session_id,user_id,event_type,metadata)
      values (v_session.session_id,p_user_id,'takeover_grants_revoked',
        pg_catalog.jsonb_build_object('reason','customer_logout','count',v_count));
    end if;
  end loop;
  return v_total;
end;

declare
  v_row public.moreai_browser_takeover_commands%rowtype;
begin
  if p_command_id is null
     or p_worker_id is null
     or p_worker_id !~ '^[A-Za-z0-9._:-]{8,128}$'
     or p_status not in ('succeeded','failed') then
    raise exception 'takeover_command_finish_payload_invalid' using errcode = '22023';
  end if;

  update public.moreai_browser_takeover_commands
     set status = p_status,
         result = case when p_status = 'succeeded'
                       then coalesce(p_result, '{}'::jsonb) else null end,
         error_code = case when p_status = 'failed'
                           then left(coalesce(p_error_code, 'takeover_input_failed'), 100) else null end,
         finished_at = pg_catalog.now(),
         lease_expires_at = null
   where id = p_command_id
     and status = 'processing'
     and claimed_by = p_worker_id
     and lease_expires_at > pg_catalog.now()
  returning * into v_row;

  if not found then
    raise exception 'takeover_command_worker_lease_lost' using errcode = '40001';
  end if;

  return pg_catalog.jsonb_build_object(
    'id', v_row.id, 'status', v_row.status, 'finished_at', v_row.finished_at
  );
end;

begin
  if new.revoked_at is not null and old.revoked_at is null then
    update public.moreai_browser_takeover_commands
       set status = 'expired',
           encrypted_command = '[revoked]',
           finished_at = pg_catalog.now(),
           lease_expires_at = null,
           error_code = 'takeover_grant_revoked'
     where grant_id = new.id
       and status in ('queued','processing');
  end if;
  return new;
end;

declare
  v_existing public.outbox_events;
  v_sequence bigint;
  v_event_id uuid := gen_random_uuid();
  v_payload jsonb := coalesce(p_payload,'{}'::jsonb);
begin
  if p_run_id is null or p_event_key is null or char_length(p_event_key) not between 1 and 200
     or p_event_type is null or p_event_type !~ '^[a-z][a-z0-9_.-]{0,79}$'
     or jsonb_typeof(v_payload) <> 'object' or octet_length(v_payload::text) > 16384 then
    raise exception 'invalid_run_event' using errcode='22023';
  end if;
  if p_worker_id is null or not exists(
    select 1 from public.agent_runs
    where id=p_run_id and status='running' and lease_owner=p_worker_id and lease_expires_at>now()
  ) then
    raise exception 'worker_lease_not_held' using errcode='42501';
  end if;
  insert into public.agent_run_event_counters(run_id,last_sequence)
  values(p_run_id,coalesce((select max(sequence) from public.agent_run_events where run_id=p_run_id),0))
  on conflict(run_id) do nothing;
  perform 1 from public.agent_run_event_counters where run_id=p_run_id for update;

  select * into v_existing from public.outbox_events
    where aggregate_type='agent_run' and aggregate_id=p_run_id and event_key=p_event_key;
  if found then
    if v_existing.payload->>'event_type' <> p_event_type
       or v_existing.payload->'event_payload' <> v_payload then
      raise exception 'run_event_idempotency_conflict' using errcode='22023';
    end if;
    return jsonb_build_object(
      'event_id',v_existing.id,'sequence',v_existing.run_sequence,'duplicate',true
    );
  end if;

  update public.agent_run_event_counters
    set last_sequence=last_sequence+1,updated_at=now()
    where run_id=p_run_id returning last_sequence into v_sequence;

  insert into public.agent_run_events(id,run_id,event_type,sequence,payload,created_at)
    values(v_event_id,p_run_id,p_event_type,v_sequence,v_payload,now());

  insert into public.outbox_events(
    id,aggregate_type,aggregate_id,event_type,payload,status,attempts,available_at,
    created_at,event_key,run_sequence
  ) values(
    v_event_id,'agent_run',p_run_id,'run.event',
    jsonb_build_object(
      'run_id',p_run_id,'event_id',v_event_id,'sequence',v_sequence,
      'event_type',p_event_type,'event_payload',v_payload,'created_at',now()
    ),
    'pending',0,now(),now(),p_event_key,v_sequence
  );

  return jsonb_build_object('event_id',v_event_id,'sequence',v_sequence,'duplicate',false);
end;

declare v_event jsonb;
begin
  if p_checkpoint_key is null or char_length(p_checkpoint_key) not between 1 and 200
     or jsonb_typeof(p_state) <> 'object' then
    raise exception 'invalid_checkpoint' using errcode='22023';
  end if;
  if not exists(select 1 from public.agent_runs where id=p_run_id and status='running'
      and lease_owner=p_worker_id and lease_expires_at>now()) then
    raise exception 'worker_lease_not_held' using errcode='42501';
  end if;
  insert into public.agent_run_checkpoints(run_id,checkpoint_key,state)
    values(p_run_id,p_checkpoint_key,p_state)
    on conflict(run_id,checkpoint_key) do update
      set state=excluded.state,created_at=now();
  update public.agent_runs set last_checkpoint_key=p_checkpoint_key,updated_at=now()
    where id=p_run_id;
  v_event := public.moreai_worker_append_run_event(
    p_run_id,p_worker_id,'worker.checkpoint:'||p_checkpoint_key,
    'worker.checkpoint',jsonb_build_object('checkpoint_key',p_checkpoint_key)
  );
  return jsonb_build_object(
    'run_id',p_run_id,'checkpoint_key',p_checkpoint_key,
    'sequence',(v_event->>'sequence')::bigint
  );
end;

declare
  r public.agent_runs%rowtype;
  next_status text;
  dead boolean := false;
  event_type text;
  event_key text;
begin
  if p_status not in ('succeeded','failed','cancelled') then
    raise exception 'invalid terminal status';
  end if;
  select * into r from public.agent_runs where id=p_run_id for update;
  if not found then raise exception 'run not found'; end if;
  if r.status in ('succeeded','failed','cancelled') then
    return jsonb_build_object('run_id',r.id,'status',r.status);
  end if;
  if r.lease_owner is distinct from p_worker_id or r.lease_expires_at <= now() then
    raise exception 'worker lease mismatch';
  end if;
  if r.cancel_requested_at is not null then
    next_status := 'cancelled';
  elsif p_status='failed' and r.attempt<r.max_attempts then
    next_status := 'queued';
  elsif p_status='failed' then
    next_status := 'failed'; dead := true;
  else
    next_status := p_status;
  end if;
  event_type := case when dead then 'worker.dead_lettered' else 'worker.'||next_status end;
  event_key := 'worker.finish:'||r.attempt::text||':'||next_status;
  perform public.moreai_worker_append_run_event(
    p_run_id,p_worker_id,event_key,event_type,
    jsonb_build_object('attempt',r.attempt,'error_code',
      case when p_error is null then null else coalesce(p_error->>'code','execution_failed') end)
  );
  if next_status='queued' then
    update public.agent_runs set status=next_status,error=p_error,
      available_at=now()+make_interval(secs=>greatest(1,least(p_retry_delay_seconds,3600))),
      lease_owner=null,lease_expires_at=null,heartbeat_at=null,updated_at=now()
      where id=r.id;
  else
    update public.agent_runs set status=next_status,output=p_output,error=p_error,
      finished_at=now(),dead_lettered_at=case when dead then now() else dead_lettered_at end,
      lease_owner=null,lease_expires_at=null,heartbeat_at=null,updated_at=now()
      where id=r.id;
  end if;
  return jsonb_build_object('run_id',r.id,'status',next_status,'attempt',r.attempt,'dead_lettered',dead);
end;

declare v_count integer;
begin
  update public.outbox_events
    set status='published',published_at=now(),worker_id=null,lease_expires_at=null,last_error=null
    where id=p_event_id and status='processing' and worker_id=p_worker_id
      and lease_expires_at > now();
  get diagnostics v_count=row_count;
  return v_count=1;
end;

declare v_state text;
begin
  update public.outbox_events
    set attempts=attempts+1,
        status=case when attempts+1 >= 12 then 'dead_letter' else 'failed' end,
        available_at=now()+make_interval(secs=>least(3600,power(2,least(attempts,10))::integer)),
        worker_id=null,lease_expires_at=null,last_error=left(coalesce(p_error_code,'publish_failed'),200)
    where id=p_event_id and status='processing' and worker_id=p_worker_id
    returning status into v_state;
  if not found then raise exception 'outbox_lease_lost' using errcode='40001'; end if;
  return v_state;
end;

declare
    v_conversation public.conversations%rowtype;
    v_message public.conversation_messages%rowtype;
    v_run public.agent_runs%rowtype;
    v_config public.moreai_customer_agent_configs%rowtype;
begin
    if p_user_id is null or p_conversation_id is null
       or p_content is null or length(btrim(p_content)) = 0 or length(p_content) > 100000
       or p_agent_key not in ('manus', 'toolcall')
       or p_idempotency_key is null or length(p_idempotency_key) < 12 or length(p_idempotency_key) > 128
       or p_agent_config_id is null then
        raise exception 'invalid configured chat enqueue request' using errcode = '22023';
    end if;
    select * into v_config from public.moreai_customer_agent_configs
     where id = p_agent_config_id and user_id = p_user_id and enabled = true for share;
    if not found or v_config.runtime_key <> p_agent_key then
        raise exception 'agent configuration not found or runtime mismatch' using errcode = '42501';
    end if;
    if v_config.preferred_model_id is not null and not exists (
        select 1 from public.llm_models m
        join public.llm_providers p on p.id = m.provider_id
        where m.id = v_config.preferred_model_id and m.enabled = true and p.enabled = true
    ) then
        raise exception 'configured_model_is_not_enabled' using errcode = '22023';
    end if;
    select * into v_conversation from public.conversations
     where id = p_conversation_id and user_id = p_user_id for update;
    if not found then raise exception 'conversation not found' using errcode = '42501'; end if;
    select * into v_run from public.agent_runs
     where user_id = p_user_id and idempotency_key = p_idempotency_key;
    if found then
        return jsonb_build_object('run', to_jsonb(v_run), 'message', null, 'replayed', true);
    end if;
    insert into public.conversation_messages(conversation_id, user_id, role, content, metadata)
    values (p_conversation_id, p_user_id, 'user', p_content, '{}'::jsonb)
    returning * into v_message;
    insert into public.agent_runs(
        user_id, workspace_id, conversation_id, status, idempotency_key, input, max_attempts
    ) values (
        p_user_id, v_conversation.workspace_id, p_conversation_id, 'queued',
        p_idempotency_key,
        jsonb_build_object(
            'prompt', p_content, 'agent_key', p_agent_key,
            'agent_config', jsonb_build_object(
                'id', v_config.id, 'runtime_key', v_config.runtime_key,
                'name', v_config.name, 'system_prompt', v_config.system_prompt,
                'tool_keys', to_jsonb(v_config.tool_keys),
                'preferred_model_id', v_config.preferred_model_id,
                'version', v_config.version
            ),
            'conversation_id', p_conversation_id, 'message_id', v_message.id
        ),
        3
    ) returning * into v_run;
    update public.conversation_messages set run_id = v_run.id
     where id = v_message.id and user_id = p_user_id;
    v_message.run_id := v_run.id;
    return jsonb_build_object('run', to_jsonb(v_run), 'message', to_jsonb(v_message), 'replayed', false);
end;

declare
    v_conversation public.conversations%rowtype;
    v_message public.conversation_messages%rowtype;
    v_run public.agent_runs%rowtype;
    v_config public.moreai_customer_agent_configs%rowtype;
    v_attachment_ids uuid[];
    v_attachment_count integer;
    v_agent_config_snapshot jsonb;
begin
    if p_user_id is null or p_conversation_id is null
       or p_content is null or length(btrim(p_content)) = 0 or length(p_content) > 100000
       or p_agent_key is null or p_agent_key not in ('manus','toolcall')
       or p_idempotency_key is null or length(p_idempotency_key) not between 12 and 128
       or p_agent_config_id is null or coalesce(cardinality(p_attachment_ids),0) > 10 then
        raise exception 'invalid_configured_chat_enqueue_request' using errcode = '22023';
    end if;

    select * into v_config from public.moreai_customer_agent_configs
     where id = p_agent_config_id and user_id = p_user_id and enabled = true for share;
    if not found or v_config.runtime_key <> p_agent_key then
        raise exception 'agent_configuration_not_found_or_runtime_mismatch' using errcode = '42501';
    end if;
    if v_config.preferred_model_id is not null and not exists (
        select 1 from public.llm_models m
        join public.llm_providers p on p.id = m.provider_id
        where m.id = v_config.preferred_model_id and m.enabled = true and p.enabled = true
    ) then
        raise exception 'configured_model_is_not_enabled' using errcode = '22023';
    end if;

    v_agent_config_snapshot := jsonb_build_object(
        'id', v_config.id,
        'runtime_key', v_config.runtime_key,
        'name', v_config.name,
        'system_prompt', v_config.system_prompt,
        'tool_keys', to_jsonb(v_config.tool_keys),
        'preferred_model_id', v_config.preferred_model_id,
        'version', v_config.version
    );

    select coalesce(array_agg(x order by x), '{}'::uuid[])
      into v_attachment_ids
      from (select distinct unnest(coalesce(p_attachment_ids, '{}'::uuid[])) as x) q;
    if cardinality(v_attachment_ids) <> coalesce(cardinality(p_attachment_ids),0) then
        raise exception 'duplicate_chat_attachment_id' using errcode = '22023';
    end if;

    select * into v_conversation from public.conversations
     where id = p_conversation_id and user_id = p_user_id and status = 'active' for update;
    if not found then raise exception 'conversation_not_found_or_inactive' using errcode = '42501'; end if;

    if cardinality(v_attachment_ids) > 0 then
        select count(*) into v_attachment_count from public.artifacts a
         where a.id = any(v_attachment_ids)
           and a.user_id = p_user_id
           and a.metadata->>'purpose' = 'chat_attachment'
           and a.metadata->>'conversation_id' = p_conversation_id::text
           and a.size_bytes between 1 and 2000000
           and a.mime_type in ('text/plain','text/markdown','text/csv','application/json',
             'application/pdf','image/jpeg','image/png','image/webp');
        if v_attachment_count <> cardinality(v_attachment_ids) then
            raise exception 'chat_attachment_not_owned_or_not_available' using errcode = '42501';
        end if;
    end if;

    select * into v_run from public.agent_runs
     where user_id = p_user_id and idempotency_key = p_idempotency_key;
    if found then
        if v_run.input->>'prompt' is distinct from p_content
           or v_run.input->>'agent_key' is distinct from p_agent_key
           or v_run.input->'agent_config' is distinct from v_agent_config_snapshot
           or coalesce(v_run.input->'attachment_ids','[]'::jsonb) is distinct from to_jsonb(v_attachment_ids) then
            raise exception 'chat_idempotency_key_payload_conflict' using errcode = '22023';
        end if;
        return jsonb_build_object('run',to_jsonb(v_run),'message',null,'replayed',true);
    end if;

    insert into public.conversation_messages(conversation_id,user_id,role,content,metadata)
    values(p_conversation_id,p_user_id,'user',p_content,'{}'::jsonb) returning * into v_message;
    insert into public.agent_runs(user_id,workspace_id,conversation_id,status,idempotency_key,input,max_attempts)
    values(
        p_user_id,v_conversation.workspace_id,p_conversation_id,'queued',p_idempotency_key,
        jsonb_build_object(
            'prompt',p_content,'agent_key',p_agent_key,'conversation_id',p_conversation_id,
            'message_id',v_message.id,'attachment_ids',to_jsonb(v_attachment_ids),
            'agent_config',v_agent_config_snapshot
        ),3
    ) returning * into v_run;
    update public.conversation_messages set run_id = v_run.id
     where id = v_message.id and user_id = p_user_id;
    v_message.run_id := v_run.id;
    if cardinality(v_attachment_ids) > 0 then
        insert into public.conversation_message_attachments(user_id,conversation_id,message_id,run_id,artifact_id)
        select p_user_id,p_conversation_id,v_message.id,v_run.id,x from unnest(v_attachment_ids) as x;
    end if;
    return jsonb_build_object('run',to_jsonb(v_run),'message',to_jsonb(v_message),'replayed',false);
end;

declare
  v_grant public.moreai_browser_takeover_grants%rowtype;
begin
  if p_token_sha256 !~ '^[0-9a-f]{64}$'
     or p_worker_id !~ '^[A-Za-z0-9._:-]{8,128}$' then
    return jsonb_build_object('status', 'invalid');
  end if;
  update public.moreai_browser_takeover_grants g
     set consumed_at = now(), consumed_by_worker = p_worker_id
   where g.token_sha256 = p_token_sha256
     and g.consumed_at is null
     and g.revoked_at is null
     and g.expires_at > now()
     and exists (
       select 1 from public.moreai_browser_sessions s
        where s.id = g.session_id and s.user_id = g.user_id
          and s.status = 'active' and s.expires_at > now()
     )
   returning g.* into v_grant;
  if not found then
    return jsonb_build_object('status', 'unavailable');
  end if;
  insert into public.moreai_browser_session_events(session_id,user_id,event_type,metadata)
  values (v_grant.session_id,v_grant.user_id,'takeover_grant_consumed',
    jsonb_build_object('grant_id',v_grant.id,'worker_id',p_worker_id,'scopes',v_grant.scopes));
  return jsonb_build_object(
    'status','consumed','grant_id',v_grant.id,'session_id',v_grant.session_id,
    'user_id',v_grant.user_id,'scopes',v_grant.scopes,'expires_at',v_grant.expires_at
  );
end;

declare v_count integer;
begin
  update public.moreai_browser_takeover_grants
     set revoked_at = now()
   where session_id = p_session_id and user_id = p_user_id
     and consumed_at is null and revoked_at is null;
  get diagnostics v_count = row_count;
  insert into public.moreai_browser_session_events(session_id,user_id,event_type,metadata)
  values (p_session_id,p_user_id,'takeover_grants_revoked',jsonb_build_object('count',v_count));
  return v_count;
end;

declare v_count integer;
begin
  if old.status = 'active' and new.status <> 'active' then
    update public.moreai_browser_takeover_grants
       set revoked_at = now()
     where session_id = new.id and user_id = new.user_id
       and consumed_at is null and revoked_at is null;
    get diagnostics v_count = row_count;
    if v_count > 0 then
      insert into public.moreai_browser_session_events(session_id,user_id,event_type,metadata)
      values (new.id,new.user_id,'takeover_grants_revoked',
        jsonb_build_object('reason','session_status_changed','count',v_count));
    end if;
  end if;
  return new;
end;

declare
  v_session record;
  v_count integer;
begin
  if new.status in ('succeeded','failed','cancelled','timed_out','expired')
     and old.status is distinct from new.status then
    for v_session in
      select s.id, s.user_id
        from public.moreai_browser_sessions s
       where s.user_id = new.user_id
         and (s.run_id = new.id or s.last_run_id = new.id)
    loop
      update public.moreai_browser_takeover_grants
         set revoked_at = now()
       where session_id = v_session.id and user_id = v_session.user_id
         and consumed_at is null and revoked_at is null;
      get diagnostics v_count = row_count;
      if v_count > 0 then
        insert into public.moreai_browser_session_events(session_id,user_id,event_type,metadata)
        values (v_session.id,v_session.user_id,'takeover_grants_revoked',
          jsonb_build_object('reason','agent_run_terminal','run_id',new.id,'count',v_count));
      end if;
    end loop;
  end if;
  return new;
end;

declare
  v_session record;
  v_total integer := 0;
  v_count integer;
begin
  if p_user_id is null then
    raise exception 'user_id_required';
  end if;
  for v_session in
    select distinct g.session_id
      from public.moreai_browser_takeover_grants g
     where g.user_id = p_user_id
       and g.consumed_at is null and g.revoked_at is null
  loop
    update public.moreai_browser_takeover_grants
       set revoked_at = now()
     where session_id = v_session.session_id and user_id = p_user_id
       and consumed_at is null and revoked_at is null;
    get diagnostics v_count = row_count;
    v_total := v_total + v_count;
    if v_count > 0 then
      insert into public.moreai_browser_session_events(session_id,user_id,event_type,metadata)
      values (v_session.session_id,p_user_id,'takeover_grants_revoked',
        jsonb_build_object('reason','customer_logout','count',v_count));
    end if;
  end loop;
  return v_total;
end;

declare v_row public.moreai_browser_preview_requests%rowtype;
begin
  if p_status not in ('succeeded','failed') then
    raise exception 'browser_preview_finish_status_invalid' using errcode='22023';
  end if;
  update public.moreai_browser_preview_requests
    set status=p_status,
        artifact_id=case when p_status='succeeded' then p_artifact_id else null end,
        error_code=case when p_status='failed' then left(coalesce(p_error_code,'browser_preview_failed'),100) else null end,
        finished_at=now(), lease_expires_at=null
    where id=p_request_id and status='processing' and claimed_by=p_worker_id
      and lease_expires_at>now()
      and (p_status <> 'succeeded' or p_artifact_id is not null);
  if not found then
    raise exception 'browser_preview_worker_lease_lost' using errcode='40001';
  end if;
  select * into v_row from public.moreai_browser_preview_requests where id=p_request_id;
  return jsonb_build_object('id',v_row.id,'status',v_row.status,'artifact_id',v_row.artifact_id);
end;
